    /// FM1/FM8: Archiver SHA-256 verification — archived segment data in S3
    /// must match the original segment on disk, bit-for-bit.
    #[test]
    fn fm1_archived_segment_content_integrity() {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();

        rt.block_on(async {
            let dir = tempfile::tempdir().unwrap();
            let store: Arc<dyn object_store::ObjectStore> =
                Arc::new(object_store::memory::InMemory::new());
            let prefix = "integrity-test";

            let config = StorageEngineConfig {
                commit_log: CommitLogConfig {
                    segment_size: 512, // small to force rotation
                    archive: Some(crate::commitlog::config::ArchiveConfig {
                        enabled: true,
                        poll_interval: std::time::Duration::from_millis(50),
                        ..crate::commitlog::config::ArchiveConfig::default()
                    }),
                    ..CommitLogConfig::test_config(dir.path())
                },
                ..StorageEngineConfig::test_config(dir.path())
            };

            let engine = StorageEngine::new_with_archive_store(
                config,
                Some(&tokio::runtime::Handle::current()),
                Some(Arc::clone(&store)),
                prefix.to_string(),
            )
            .unwrap();

            engine.register_table(test_schema()).unwrap();
            let tid = table_id();

            // Write enough data to trigger multiple segment rotations.
            for i in 0..30 {
                let key_str = format!("key-{i:04}");
                let val_str = format!("value-{i:04}");
                engine
                    .write(
                        &tid,
                        &make_key(&key_str),
                        make_row(val_str.as_bytes(), i),
                        i,
                    )
                    .unwrap();
            }

            // Wait for archiver to process.
            tokio::time::sleep(std::time::Duration::from_millis(500)).await;

            // Load archive manifest.
            let manifest =
                crate::commitlog::manifest::ArchiveManifest::load(store.as_ref(), prefix)
                    .await
                    .unwrap();

            assert!(
                !manifest.segments.is_empty(),
                "at least one segment must be archived"
            );

            // Verify each archived segment: SHA-256 in manifest matches S3 content.
            for seg in &manifest.segments {
                let hex = crate::upload::manager::hex_prefix_for(&seg.id.to_string());
                let s3_path = object_store::path::Path::from(format!(
                    "{prefix}/commitlog-archive/{hex}/{}.log",
                    seg.id
                ));
                let result = store.get(&s3_path).await.unwrap();
                let data = result.bytes().await.unwrap();

                // Independently compute SHA-256.
                use sha2::{Digest, Sha256};
                let mut hasher = Sha256::new();
                hasher.update(&data);
                let actual_sha = format!("{:x}", hasher.finalize());

                assert_eq!(
                    seg.sha256, actual_sha,
                    "archived segment {} SHA-256 mismatch",
                    seg.id
                );
                assert_eq!(
                    seg.size,
                    data.len() as u64,
                    "archived segment {} size mismatch",
                    seg.id
                );
            }

            engine.shutdown().unwrap();
        });
    }

    /// Snapshot manifest SHA-256 integrity — verify the manifest stored in the
    /// snapshot can be loaded and validated by RestoreManager.
    #[test]
    fn snapshot_manifest_sha256_roundtrip() {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();

        rt.block_on(async {
            let dir = tempfile::tempdir().unwrap();
            let (engine, store, prefix) = setup_snapshot_engine(dir.path()).await;

            engine.register_table(test_schema()).unwrap();
            let tid = table_id();

            // Write data so the manifest is non-empty.
            engine
                .write(&tid, &make_key("k"), make_row(b"v", 1), 1)
                .unwrap();
            engine.flush(&tid).unwrap();
            engine
                .upload_manifest_for_test(Arc::clone(&store), prefix)
                .await;

            let snap_meta = engine
                .create_snapshot_with_store(
                    "sha-test",
                    "node-1",
                    None,
                    false,
                    Arc::clone(&store),
                    prefix,
                )
                .await
                .unwrap();

            // RestoreManager must validate the SHA-256 successfully.
            let restore_mgr =
                crate::restore::RestoreManager::new(Arc::clone(&store), prefix.to_string());
            let (loaded_meta, loaded_manifest) = restore_mgr
                .load_and_validate_snapshot("sha-test")
                .await
                .unwrap();

            assert_eq!(loaded_meta.name, "sha-test");
            assert_eq!(loaded_meta.manifest_sha256, snap_meta.manifest_sha256);
            // Manifest must have at least one table with SSTables.
            assert!(
                !loaded_manifest.sstables.is_empty(),
                "snapshot manifest should reference at least one table"
            );

            engine.shutdown().unwrap();
        });
    }

    /// Snapshot expiry — verify cleanup_expired removes old snapshots while
    /// keeping non-expired ones, and that expired snapshot data is no longer
    /// restorable.
    #[test]
    fn snapshot_expiry_cleanup_works() {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();

        rt.block_on(async {
            let dir = tempfile::tempdir().unwrap();
            let (engine, store, prefix) = setup_snapshot_engine(dir.path()).await;

            engine.register_table(test_schema()).unwrap();
            let tid = table_id();
            engine
                .write(&tid, &make_key("k"), make_row(b"v", 1), 1)
                .unwrap();
            engine.flush(&tid).unwrap();
            engine
                .upload_manifest_for_test(Arc::clone(&store), prefix)
                .await;

            // Create one snapshot that expires in the past, one that doesn't expire.
            engine
                .create_snapshot_with_store(
                    "expired-snap",
                    "node-1",
                    Some("2020-01-01T00:00:00Z".to_string()), // already expired
                    false,
                    Arc::clone(&store),
                    prefix,
                )
                .await
                .unwrap();
            engine
                .create_snapshot_with_store(
                    "permanent-snap",
                    "node-1",
                    None, // no expiry
                    false,
                    Arc::clone(&store),
                    prefix,
                )
                .await
                .unwrap();

            let snap_mgr =
                crate::snapshot::SnapshotManager::new(Arc::clone(&store), prefix.to_string());

            // Before cleanup: both exist.
            let before = snap_mgr.list_snapshots().await.unwrap();
            assert_eq!(before.len(), 2);

            // Cleanup at "now" (well past the expired date).
            let deleted = snap_mgr
                .cleanup_expired("2026-01-01T00:00:00Z")
                .await
                .unwrap();
            assert_eq!(deleted.len(), 1);
            assert_eq!(deleted[0], "expired-snap");

            // After cleanup: only permanent remains.
            let after = snap_mgr.list_snapshots().await.unwrap();
            assert_eq!(after.len(), 1);
            assert_eq!(after[0].name, "permanent-snap");

            // Trying to restore expired snapshot must fail.
            let restore_mgr =
                crate::restore::RestoreManager::new(Arc::clone(&store), prefix.to_string());
            let result = restore_mgr.load_and_validate_snapshot("expired-snap").await;
            assert!(result.is_err(), "expired snapshot should not be loadable");

            engine.shutdown().unwrap();
        });
    }

    // =========================================================================
    // Task 3.2: Sidecar files survive table re-registration
    // =========================================================================

    /// The flush's own postings count: an index it wrote needs no rebuild.
    ///
    /// The end-to-end version of this only fails when the rebuild job is slow
    /// enough to still be queued when the read arrives, which is a loaded
    /// machine and not a reproducible test. The decision itself is pure, so
    /// this pins it directly.
    #[test]
    fn a_flushed_index_is_marked_indexed_not_rebuilt() {
        let covered = ["val_idx".to_string(), "city_idx".to_string()];
        let already: HashSet<String> = HashSet::new();

        assert_eq!(
            flush_index_action(&covered, "val_idx", &already, "7"),
            FlushIndexAction::AlreadyWritten,
            "the flush wrote this index's postings for this generation, so the \
             generation is indexed — marking it pending calls a complete index \
             incomplete for as long as the rebuild sits in the queue"
        );
        assert_eq!(
            flush_index_action(&covered, "other_idx", &already, "7"),
            FlushIndexAction::NeedsBuild,
            "an index the flush had no memtable postings for is genuinely \
             unbuilt for this generation and must be built from the SSTable"
        );

        let already: HashSet<String> = ["7".to_string()].into_iter().collect();
        assert_eq!(
            flush_index_action(&covered, "other_idx", &already, "7"),
            FlushIndexAction::Nothing,
            "a generation already recorded as indexed needs neither"
        );
    }

    /// A flush must not report the generation it just indexed as pending.
    ///
    /// `TableStore::flush` writes and installs that generation's sidecars
    /// inline, from the memtable index it swapped out — the postings are on
    /// disk and in the view before `flush` returns. The engine then marked the
    /// same generation pending and queued a rebuild anyway, so for as long as
    /// that job sat in the queue the tracker called a complete index
    /// incomplete.
    ///
    /// Nothing reacted to that window until reads started believing the
    /// tracker. Now two things do: a read through the index is refused
    /// outright at the storage layer, and the planner withholds the index and
    /// scans instead. Either way every flush opened a window in which the
    /// index it had just written was treated as unusable — which showed up as
    /// `sidecar_survives_table_reregistration` failing under a loaded suite
    /// and passing alone.
    #[test]
    fn an_index_is_current_the_moment_its_flush_returns() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine
            .register_table_with_indexes(test_schema(), vec![("val_idx".to_string(), 0_usize)])
            .unwrap();
        let tid = table_id();
        engine
            .write(&tid, &make_key("user1"), make_row(b"alice", 1000), 1000)
            .unwrap();

        engine.flush(&tid).unwrap();

        assert!(
            engine.index_is_current(&tid, "val_idx"),
            "the flush wrote and installed this generation's sidecar before returning, \
             so the index covers every row in it; leaving it pending makes readers \
             refuse or rescan an index that is complete"
        );
        let results = collect_index_results(&engine, &tid, "val_idx", &IndexKey(b"alice".to_vec()))
            .expect("a complete index answers");
        assert_eq!(results.len(), 1, "the flushed row is readable by index");
        engine.shutdown().unwrap();
    }

    /// A secondary-index stream whose consumer stops pulling must not stall
    /// schema changes.
    ///
    /// `read_by_index_stream_after` walks the index on a blocking worker and
    /// hands partitions through a bounded channel. The walk ran under the
    /// engine-wide `tables` read guard, so once the consumer paused, the
    /// producer slept in `blocking_send` holding it. The next raft
    /// `register_table` queued for the write lock, and because `parking_lot`
    /// prefers writers, every later reader queued behind it, including
    /// the consumer's own schema lookups. On 2026-10-03 that wedged node2 of the
    /// memory cluster: 24 threads parked on the lock, raft apply stopped, and
    /// node1 answered every CQL request with `request backpressure`
    /// (t_d938e6ae).
    #[test]
    fn a_paused_index_stream_does_not_block_table_registration() {
        use ferrosa_index::IndexKey;
        use futures::StreamExt;

        const ROWS: usize = 16;
        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = Arc::new(StorageEngine::new(config, None).unwrap());
        engine
            .register_table_with_indexes(test_schema(), vec![("val_idx".to_string(), 0_usize)])
            .unwrap();
        let tid = table_id();
        for i in 0..ROWS {
            engine
                .write(
                    &tid,
                    &make_key(&format!("user{i}")),
                    make_row(b"alice", 1000),
                    1000,
                )
                .unwrap();
        }
        engine.flush(&tid).unwrap();

        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        // Take one row and keep the stream open: the producer fills the
        // bounded channel and parks, as it does behind a paused CQL page.
        let mut stream = runtime.block_on(async {
            engine.read_by_index_stream(&tid, "val_idx", &IndexKey(b"alice".to_vec()))
        });
        let first = runtime.block_on(stream.next());
        assert!(
            matches!(first, Some(Ok(_))),
            "the stream yields its first row: {first:?}"
        );
        std::thread::sleep(std::time::Duration::from_millis(200));

        let (done_tx, done_rx) = std::sync::mpsc::channel();
        let ddl_engine = Arc::clone(&engine);
        let ddl = std::thread::spawn(move || {
            let mut other = test_schema();
            other.table = "other_table".to_string();
            let result = ddl_engine.register_table(other);
            done_tx.send(result.is_ok()).unwrap();
        });
        let registered = done_rx.recv_timeout(std::time::Duration::from_secs(5));

        // Release the producer before asserting, so a failure reports
        // instead of leaving the DDL thread parked forever.
        drop(stream);
        ddl.join().unwrap();
        assert_eq!(
            registered,
            Ok(true),
            "register_table must not wait on a paused index stream: the stream's \
             producer may not hold the engine-wide tables guard across a blocking send"
        );
        runtime.shutdown_timeout(std::time::Duration::from_secs(5));
        engine.shutdown().unwrap();
    }

    /// DROP TABLE no longer waits for the table's readers: it used to, by
    /// taking the table-map write lock, which is the wait that wedged node2
    /// (t_d938e6ae). A reader still holding the dropped table therefore
    /// races the directory delete. It may finish or fail, loudly — never
    /// return a short answer as `Ok`. And nothing it does may put files back
    /// into the directory a re-created table of the same name now owns.
    #[test]
    fn a_reader_of_a_dropped_table_fails_loud_and_resurrects_nothing() {
        use ferrosa_index::IndexKey;
        use futures::StreamExt;

        const ROWS: usize = 16;
        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = Arc::new(StorageEngine::new(config, None).unwrap());
        let indexes = vec![("val_idx".to_string(), 0_usize)];
        engine
            .register_table_with_indexes(test_schema(), indexes.clone())
            .unwrap();
        let tid = table_id();
        for i in 0..ROWS {
            engine
                .write(
                    &tid,
                    &make_key(&format!("user{i}")),
                    make_row(b"alice", 1000),
                    1000,
                )
                .unwrap();
        }
        engine.flush(&tid).unwrap();

        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let mut stream = runtime.block_on(async {
            engine.read_by_index_stream(&tid, "val_idx", &IndexKey(b"alice".to_vec()))
        });
        let first = runtime.block_on(stream.next());
        assert!(matches!(first, Some(Ok(_))), "first row: {first:?}");
        std::thread::sleep(std::time::Duration::from_millis(200));

        let (done_tx, done_rx) = std::sync::mpsc::channel();
        let ddl_engine = Arc::clone(&engine);
        let ddl_tid = tid.clone();
        let drop_thread = std::thread::spawn(move || {
            done_tx
                .send(
                    ddl_engine
                        .unregister_table(&ddl_tid)
                        .map_err(|e| e.to_string()),
                )
                .unwrap();
        });
        let dropped = done_rx.recv_timeout(std::time::Duration::from_secs(5));
        let drained = if dropped.is_ok() {
            engine
                .register_table_with_indexes(test_schema(), indexes)
                .unwrap();
            runtime.block_on(async {
                let mut items = Vec::new();
                while let Some(item) = stream.next().await {
                    items.push(item.map(|_| ()).map_err(|e| e.to_string()));
                }
                items
            })
        } else {
            drop(stream);
            Vec::new()
        };
        drop_thread.join().unwrap();
        assert_eq!(
            dropped,
            Ok(Ok(())),
            "DROP TABLE must not wait for a paused reader of the table"
        );

        let delivered = 1 + drained.iter().filter(|item| item.is_ok()).count();
        let failed = drained.iter().any(Result::is_err);
        assert!(
            failed || delivered == ROWS,
            "a reader racing DROP TABLE returned {delivered} of {ROWS} rows and no error: \
             a short answer reported as complete ({drained:?})"
        );
        let recreated = engine.read_range(&tid, None, None, 1_000).unwrap();
        assert!(
            recreated.is_empty(),
            "the re-created table must start empty, found {} partitions",
            recreated.len()
        );
        assert_eq!(engine.sstable_count(&tid), 0);
        runtime.shutdown_timeout(std::time::Duration::from_secs(5));
        engine.shutdown().unwrap();
    }

    #[test]
    fn sidecar_survives_table_reregistration() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let tid = table_id();

        // Phase 1: register table with an index, write indexed data, flush.
        {
            let config = StorageEngineConfig::test_config(dir.path());
            let engine = StorageEngine::new(config, None).unwrap();
            engine
                .register_table_with_indexes(test_schema(), vec![("val_idx".to_string(), 0_usize)])
                .unwrap();

            engine
                .write(&tid, &make_key("user1"), make_row(b"alice", 1000), 1000)
                .unwrap();
            engine.flush(&tid).unwrap();

            // Verify readable before drop.
            let results =
                collect_index_results(&engine, &tid, "val_idx", &IndexKey(b"alice".to_vec()))
                    .unwrap();
            assert_eq!(results.len(), 1, "pre-reregistration: should find user1");

            engine.shutdown().unwrap();
        }

        // Phase 2: create a new engine with the same data dir, re-register,
        // and verify the sidecar index is loaded from disk.
        {
            let config = StorageEngineConfig::test_config(dir.path());
            let (engine, pending) = StorageEngine::open(config, None).unwrap();
            engine
                .register_table_with_indexes(test_schema(), vec![("val_idx".to_string(), 0_usize)])
                .unwrap();
            engine.replay_mutations(pending).unwrap();

            let results =
                collect_index_results(&engine, &tid, "val_idx", &IndexKey(b"alice".to_vec()))
                    .unwrap();
            assert_eq!(
                results.len(),
                1,
                "post-reregistration: sidecar should be loaded from disk and return user1"
            );
            assert_eq!(results[0].key.key.as_bytes(), b"user1");
        }
    }

    // ── read_by_index_in_partition (t_430c4188) ──────────────────────────────
    //
    // Keyed secondary-index consult: postings for the indexed value are
    // restricted to ONE specified partition, so a full-partition-key +
    // indexed-column query does O(matching rows) work instead of scanning
    // O(partition rows).

    fn row_ck(ck: i32, value: &[u8], ts: i64) -> Row {
        Row {
            clustering: ck.to_be_bytes().to_vec(),
            cells: vec![(0, CellValue::live(value.to_vec(), ts))],
            deletion: DeletionTime::LIVE,
            primary_key_liveness: LivenessInfo::with_timestamp(ts),
        }
    }

    #[test]
    fn read_by_index_in_partition_returns_only_target_partition_rows() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        let tid = table_id();
        engine
            .register_table_with_indexes(test_schema(), vec![("val_idx".to_string(), 0_usize)])
            .unwrap();

        // p1 gets an "alice" row that is FLUSHED (sidecar index) and one that
        // stays in the memtable index, so the keyed consult must merge both
        // index layers. p1 also holds non-matching rows, and p2 holds a
        // matching row that must NOT leak into the p1 result.
        engine
            .write(&tid, &make_key("p1"), row_ck(1, b"alice", 1000), 1000)
            .unwrap();
        engine
            .write(&tid, &make_key("p2"), row_ck(1, b"alice", 1001), 1001)
            .unwrap();
        engine.flush(&tid).unwrap();
        engine
            .write(&tid, &make_key("p1"), row_ck(2, b"bob", 1002), 1002)
            .unwrap();
        engine
            .write(&tid, &make_key("p1"), row_ck(3, b"alice", 1003), 1003)
            .unwrap();

        let hits = engine
            .read_by_index_in_partition(&tid, "val_idx", &IndexKey(b"alice".to_vec()), b"p1")
            .unwrap();

        assert!(
            hits.iter().all(|p| p.key.key.as_bytes() == b"p1"),
            "keyed consult must never return rows from other partitions"
        );
        let mut cks: Vec<Vec<u8>> = hits
            .iter()
            .flat_map(|p| p.rows.iter().map(|r| r.clustering.clone()))
            .collect();
        cks.sort();
        assert_eq!(
            cks,
            vec![1_i32.to_be_bytes().to_vec(), 3_i32.to_be_bytes().to_vec()],
            "keyed consult must return exactly the matching rows (memtable + sidecar)"
        );

        // Sanity: the GLOBAL consult still sees p2, proving the keyed variant
        // actually restricted the postings rather than the data being absent.
        let global =
            collect_index_results(&engine, &tid, "val_idx", &IndexKey(b"alice".to_vec())).unwrap();
        assert!(
            global.iter().any(|p| p.key.key.as_bytes() == b"p2"),
            "global consult should see the p2 match"
        );
    }

    #[test]
    fn read_by_index_in_partition_no_matches_is_empty_not_error() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        let tid = table_id();
        engine
            .register_table_with_indexes(test_schema(), vec![("val_idx".to_string(), 0_usize)])
            .unwrap();
        engine
            .write(&tid, &make_key("p1"), row_ck(1, b"alice", 1000), 1000)
            .unwrap();

        // Value exists but not in the requested partition.
        let hits = engine
            .read_by_index_in_partition(&tid, "val_idx", &IndexKey(b"alice".to_vec()), b"p9")
            .unwrap();
        assert!(hits.is_empty(), "no matches in partition → empty result");

        // Value absent everywhere.
        let hits = engine
            .read_by_index_in_partition(&tid, "val_idx", &IndexKey(b"nobody".to_vec()), b"p1")
            .unwrap();
        assert!(hits.is_empty(), "absent value → empty result");

        let mut visitor = |_partition| std::ops::ControlFlow::Continue(());
        let err = engine.read_by_index_each(
            &TableId::new("nope", "nope"),
            "val_idx",
            &IndexKey(b"alice".to_vec()),
            &mut visitor,
        );
        assert!(
            err.is_err(),
            "unknown table stream must fail loud, not be empty"
        );

        // Unknown table fails loud (mirrors read_by_index).
        let err = engine.read_by_index_in_partition(
            &TableId::new("nope", "nope"),
            "val_idx",
            &IndexKey(b"alice".to_vec()),
            b"p1",
        );
        assert!(err.is_err(), "unknown table must be an error, not empty");
    }

    /// Clustering-column secondary index (t_430c4188): values are extracted
    /// from the composite clustering-key bytes on write, survive the
    /// memtable→sidecar flush drain, and serve both the global and the keyed
    /// (in-partition) consult.
    #[test]
    fn clustering_column_index_indexes_ck_values_across_flush() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        let tid = table_id();
        engine.register_table(test_schema()).unwrap();
        engine
            .add_clustering_index(&tid, "ck_idx", 0, ferrosa_index::IndexType::BTree)
            .unwrap();

        // test_schema has ONE clustering column (ck: int, big-endian bytes).
        // Two rows with ck=7 in different partitions + one non-matching row.
        engine
            .write(&tid, &make_key("p1"), row_ck(7, b"a", 1000), 1000)
            .unwrap();
        engine
            .write(&tid, &make_key("p2"), row_ck(7, b"b", 1001), 1001)
            .unwrap();
        engine.flush(&tid).unwrap(); // ck=7 entries now live in the SIDECAR
        engine
            .write(&tid, &make_key("p1"), row_ck(9, b"c", 1002), 1002)
            .unwrap(); // ck=9 stays in the MEMTABLE index

        let key7 = IndexKey(7_i32.to_be_bytes().to_vec());

        // Global consult sees both partitions (sidecar layer).
        let global = collect_index_results(&engine, &tid, "ck_idx", &key7).unwrap();
        let mut pks: Vec<Vec<u8>> = global
            .iter()
            .map(|p| p.key.key.as_bytes().to_vec())
            .collect();
        pks.sort();
        assert_eq!(
            pks,
            vec![b"p1".to_vec(), b"p2".to_vec()],
            "clustering index must serve flushed (sidecar) entries globally"
        );

        // Keyed consult restricted to p1 returns only p1's ck=7 row.
        let keyed = engine
            .read_by_index_in_partition(&tid, "ck_idx", &key7, b"p1")
            .unwrap();
        assert_eq!(keyed.len(), 1, "one matching row in p1");
        assert_eq!(keyed[0].key.key.as_bytes(), b"p1");
        assert_eq!(keyed[0].rows[0].clustering, 7_i32.to_be_bytes().to_vec());

        // Memtable layer: the post-flush ck=9 write is indexed too.
        let key9 = IndexKey(9_i32.to_be_bytes().to_vec());
        let keyed9 = engine
            .read_by_index_in_partition(&tid, "ck_idx", &key9, b"p1")
            .unwrap();
        assert_eq!(keyed9.len(), 1, "memtable-resident clustering entry found");
        assert_eq!(keyed9[0].rows[0].clustering, 9_i32.to_be_bytes().to_vec());
    }

    /// An index created on a table that ALREADY holds data must cover that
    /// data.
    ///
    /// This is the order that matters operationally: a table has been running
    /// for weeks, reads are slow, somebody adds an index. If the index only
    /// covers rows written after it was declared, the reads through it return
    /// a subset — and because the planner selects the index, that subset is
    /// reported as the complete answer. Silent, and worse than no index.
    ///
    /// So the data is written and FLUSHED to an SSTable before the index
    /// exists. Nothing in the memtable can satisfy this test.
    #[test]
    fn a_partition_key_index_backfills_data_that_predates_it() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        let tid = TableId::new("test_ks", "entity_store");

        let schema = ferrosa_common::TableSchema {
            keyspace: "test_ks".into(),
            table: "entity_store".into(),
            key_type: "org.apache.cassandra.db.marshal.CompositeType(\
                       org.apache.cassandra.db.marshal.UTF8Type,\
                       org.apache.cassandra.db.marshal.UTF8Type)"
                .into(),
            clustering_columns: vec![],
            static_columns: vec![],
            regular_columns: vec![ferrosa_common::ColumnDefinition {
                name: "body".into(),
                type_name: "org.apache.cassandra.db.marshal.UTF8Type".into(),
            }],
            extensions: Default::default(),
        };
        engine.register_table(schema).unwrap();

        // Phase 1: data first, index later. The flush is what makes this a
        // backfill test rather than a memtable test.
        let mut tenant_a_rows = 0usize;
        for i in 0..8u8 {
            let mut tenant = [0u8; 16];
            tenant[0] = if i % 2 == 0 { 1 } else { 2 };
            if i % 2 == 0 {
                tenant_a_rows += 1;
            }
            let mut session = [0u8; 16];
            session[0] = i;
            let row = Row {
                clustering: vec![],
                cells: vec![(0, CellValue::live(format!("row-{i}").into_bytes(), 1000))],
                deletion: DeletionTime::LIVE,
                primary_key_liveness: LivenessInfo::with_timestamp(1000),
            };
            engine
                .write(&tid, &make_entity_store_pk(tenant, session), row, 1000)
                .unwrap();
        }
        engine.flush(&tid).unwrap();

        // Phase 2: NOW declare the index.
        engine
            .add_partition_key_index(&tid, "idx_by_tenant", 0, ferrosa_index::IndexType::BTree)
            .unwrap();

        let mut tenant_a = [0u8; 16];
        tenant_a[0] = 1;
        let key = IndexKey(tenant_a.to_vec());

        // The backfill runs on the scheduler's worker threads. Poll for it,
        // bounded — a backfill that never completes must fail this test rather
        // than hang it.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        let mut found = 0usize;
        while std::time::Instant::now() < deadline {
            found = collect_index_results(&engine, &tid, "idx_by_tenant", &key)
                .unwrap()
                .iter()
                .map(|p| p.rows.len())
                .sum();
            if found >= tenant_a_rows {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(50));
        }

        assert_eq!(
            found, tenant_a_rows,
            "an index declared on a table that already holds flushed data must \
             backfill it: {tenant_a_rows} rows for this tenant were written and \
             flushed BEFORE the index existed, and the index returned {found}. \
             Zero means no backfill was submitted; a partial count means it was \
             submitted and did not finish."
        );
    }

    /// Commanding a rebuild must actually put the rows back in the index.
    ///
    /// The live condition this exists for: `ferrosa-ctl index list` reports
    /// six of thirty-one indexes on a dev cluster as `stale` or `failed`, with
    /// 11 to 17 SSTables queued apiece, on the tables memory search reads.
    /// `failed` never clears on its own — the retry backoff runs out and the
    /// rows stay missing.
    ///
    /// The assertion is deliberately about ROWS, not about the command being
    /// accepted. A rebuild that returns `Ok(())` and indexes nothing is the
    /// failure mode worth guarding: it reads as a repair and leaves the index
    /// exactly as short as it was.
    #[test]
    fn a_rebuild_restores_an_index_whose_sidecars_were_lost() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let engine =
            StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        let tid = TableId::new("test_ks", "entity_store");

        let schema = || ferrosa_common::TableSchema {
            keyspace: "test_ks".into(),
            table: "entity_store".into(),
            key_type: "org.apache.cassandra.db.marshal.CompositeType(\
                       org.apache.cassandra.db.marshal.UTF8Type,\
                       org.apache.cassandra.db.marshal.UTF8Type)"
                .into(),
            clustering_columns: vec![],
            static_columns: vec![],
            regular_columns: vec![ferrosa_common::ColumnDefinition {
                name: "body".into(),
                type_name: "org.apache.cassandra.db.marshal.UTF8Type".into(),
            }],
            extensions: Default::default(),
        };
        engine.register_table(schema()).unwrap();

        // Data first, flushed, so the index has something to backfill.
        let mut tenant_a_rows = 0usize;
        for i in 0..8u8 {
            let mut tenant = [0u8; 16];
            tenant[0] = if i % 2 == 0 { 1 } else { 2 };
            if i % 2 == 0 {
                tenant_a_rows += 1;
            }
            let mut session = [0u8; 16];
            session[0] = i;
            let row = Row {
                clustering: vec![],
                cells: vec![(0, CellValue::live(format!("row-{i}").into_bytes(), 1000))],
                deletion: DeletionTime::LIVE,
                primary_key_liveness: LivenessInfo::with_timestamp(1000),
            };
            engine
                .write(&tid, &make_entity_store_pk(tenant, session), row, 1000)
                .unwrap();
        }
        engine.flush(&tid).unwrap();
        engine
            .add_partition_key_index(&tid, "idx_by_tenant", 0, ferrosa_index::IndexType::BTree)
            .unwrap();

        let mut tenant_a = [0u8; 16];
        tenant_a[0] = 1;
        let key = IndexKey(tenant_a.to_vec());

        let count = |e: &StorageEngine| -> usize {
            collect_index_results(e, &tid, "idx_by_tenant", &key)
                .unwrap()
                .iter()
                .map(|p| p.rows.len())
                .sum()
        };

        assert_eq!(
            count(&engine),
            tenant_a_rows,
            "precondition: the fresh backfill must cover the flushed rows"
        );

        // Now break it the way the cluster is broken: the sidecars that carry
        // the index for those SSTables are gone. Nothing else changes — the
        // schema still declares the index and the data is untouched.
        let mut removed = 0usize;
        for entry in walkdir_sidecars(dir.path()) {
            std::fs::remove_file(&entry).unwrap();
            removed += 1;
        }
        assert!(
            removed > 0,
            "the test must actually remove sidecars to mean anything"
        );

        assert!(
            walkdir_sidecars(dir.path()).is_empty(),
            "precondition: the sidecars must actually be gone"
        );

        // The command under test. Note what is NOT used to set this up:
        // `add_partition_key_index` backfills on its own, so calling it again
        // would repair the index before `rebuild_index` was ever reached — the
        // first cut of this test did exactly that and passed 4 of 4 without
        // exercising the rebuild at all.
        let outcome = engine.rebuild_index(&tid, "idx_by_tenant").unwrap();

        // Did it do real work? The sidecars are the artifact a rebuild
        // produces; asserting only on rows would pass on a rebuild that
        // silently did nothing while the in-memory index still answered.
        assert!(
            !walkdir_sidecars(dir.path()).is_empty(),
            "a rebuild must write the sidecars back to disk, so the repair survives a restart"
        );
        assert!(
            outcome.sstables_rebuilt > 0,
            "the outcome must report the work it did, so an operator can tell a \
             repair from a rebuild that found nothing to do"
        );
        assert!(
            outcome.is_complete(),
            "every SSTable must be covered: {} of {} were rebuilt, and a partial \
             rebuild leaves reads through this index incomplete",
            outcome.sstables_rebuilt,
            outcome.sstables_total
        );

        // And is it still usable?
        assert_eq!(
            count(&engine),
            tenant_a_rows,
            "after a commanded rebuild the index must answer for every row: \
             {tenant_a_rows} exist for this tenant"
        );
    }

    // ---- t_e76b4d27: index rebuild over a table whose Data.db files are absent ----

    /// Remove `gen`'s files under `table_dir` at any depth: every component, or
    /// only `Data.db` when `only_data` (leaving TOC and sidecars, the
    /// "compacted away with metadata left behind" shape).
    fn remove_generation_files(table_dir: &std::path::Path, gen: &str, only_data: bool) -> usize {
        let prefix = format!("{gen}-");
        let mut removed = 0;
        let mut stack = vec![table_dir.to_path_buf()];
        while let Some(d) = stack.pop() {
            for entry in std::fs::read_dir(&d).unwrap().flatten() {
                let path = entry.path();
                if path.is_dir() {
                    stack.push(path);
                    continue;
                }
                let name = entry.file_name().to_string_lossy().into_owned();
                if name.starts_with(&prefix) && (!only_data || name.ends_with("-Data.db")) {
                    std::fs::remove_file(&path).unwrap();
                    removed += 1;
                }
            }
        }
        removed
    }

    /// A file-backed engine holding `n` SSTables of one row each (`k0`..),
    /// with a partition-key index over all of them. Automatic compaction is
    /// kept out of the way so the generation set is exactly what was flushed.
    fn engine_with_indexed_generations(
        n: usize,
    ) -> (tempfile::TempDir, StorageEngine, TableId, Vec<String>) {
        let dir = tempfile::tempdir().unwrap();
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.compaction.min_threshold = 50;
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        for i in 0..n {
            engine
                .write(
                    &tid,
                    &make_key(&format!("k{i}")),
                    make_row(b"v", 1000),
                    1000,
                )
                .unwrap();
            engine.flush(&tid).unwrap();
        }
        engine
            .add_partition_key_index(&tid, "idx_pk", 0, ferrosa_index::IndexType::BTree)
            .unwrap();
        let gens = engine
            .tables
            .load()
            .get(&tid)
            .unwrap()
            .store
            .sstable_generation_ids();
        assert_eq!(gens.len(), n, "fixture must hold {n} SSTables");
        (dir, engine, tid, gens)
    }

    /// Rows the partition-key index returns for the partition `key`.
    fn pk_index_rows(
        engine: &StorageEngine,
        tid: &TableId,
        key: &str,
    ) -> ferrosa_common::Result<usize> {
        let found = collect_index_results(
            engine,
            tid,
            "idx_pk",
            &ferrosa_index::IndexKey(key.as_bytes().to_vec()),
        )?;
        Ok(found.iter().map(|p| p.rows.len()).sum())
    }

    /// Live failure, 2026-09-14: the rebuild was handed generations that exist
    /// nowhere on disk (a stale enumeration), called them "compacted away" and
    /// reported the index complete. A generation with NO files at all is not
    /// metadata left behind: it is a stale manifest entry, and the index must
    /// stay stale and refuse reads rather than answer from a fraction of the table.
    #[test]
    fn a_rebuild_over_a_generation_missing_entirely_fails_and_leaves_the_index_stale() {
        let (dir, engine, tid, gens) = engine_with_indexed_generations(3);
        let table_dir = engine.table_sstable_dir(&tid);
        assert!(remove_generation_files(&table_dir, &gens[0], false) > 0);

        let outcome = engine.rebuild_index(&tid, "idx_pk").unwrap();

        assert_eq!(outcome.sstables_failed, 1, "{outcome:?}");
        assert_eq!(
            outcome.sstables_vanished, 0,
            "an absent generation must never be discounted: {outcome:?}"
        );
        assert!(!outcome.is_complete(), "{outcome:?}");
        assert!(
            !engine.index_is_current(&tid, "idx_pk"),
            "an index over a table with an unaccounted generation must not be current"
        );
        assert!(
            pk_index_rows(&engine, &tid, "k0").is_err(),
            "a stale index must refuse reads, not return a short count"
        );
        drop(dir);
    }

    /// `CREATE INDEX` backfills through `add_partition_key_index`. A failed
    /// backfill used to be visible only through the stale tracker and an ERROR
    /// log; the caller got `Ok(())`. It must see the outcome.
    #[test]
    fn add_partition_key_index_returns_the_outcome_of_a_failed_backfill() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.compaction.min_threshold = 50;
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        for i in 0..3 {
            engine
                .write(
                    &tid,
                    &make_key(&format!("k{i}")),
                    make_row(b"v", 1000),
                    1000,
                )
                .unwrap();
            engine.flush(&tid).unwrap();
        }
        let gens = engine
            .tables
            .load()
            .get(&tid)
            .unwrap()
            .store
            .sstable_generation_ids();
        let table_dir = engine.table_sstable_dir(&tid);
        assert!(remove_generation_files(&table_dir, &gens[0], false) > 0);

        let outcome = engine
            .add_partition_key_index(&tid, "idx_pk", 0, ferrosa_index::IndexType::BTree)
            .unwrap();

        assert_eq!(outcome.sstables_failed, 1, "{outcome:?}");
        assert!(!outcome.is_complete(), "{outcome:?}");
        assert!(!engine.index_is_current(&tid, "idx_pk"));
    }

    /// A clean backfill is reported complete to the caller.
    #[test]
    fn add_partition_key_index_reports_a_complete_backfill() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.compaction.min_threshold = 50;
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        engine
            .write(&tid, &make_key("k0"), make_row(b"v", 1000), 1000)
            .unwrap();
        engine.flush(&tid).unwrap();

        let outcome = engine
            .add_partition_key_index(&tid, "idx_pk", 0, ferrosa_index::IndexType::BTree)
            .unwrap();

        assert_eq!(outcome.sstables_rebuilt, 1, "{outcome:?}");
        assert!(outcome.is_complete(), "{outcome:?}");
    }

    /// The legitimate #406 case must keep working: TOC and sidecars still
    /// there, Data.db gone. Nothing to index; the rebuild completes.
    #[test]
    fn a_generation_with_metadata_but_no_data_file_is_vanished_and_the_rebuild_completes() {
        let (dir, engine, tid, gens) = engine_with_indexed_generations(3);
        let table_dir = engine.table_sstable_dir(&tid);
        assert_eq!(remove_generation_files(&table_dir, &gens[0], true), 1);

        let outcome = engine.rebuild_index(&tid, "idx_pk").unwrap();

        assert_eq!(outcome.sstables_vanished, 1, "{outcome:?}");
        assert_eq!(outcome.sstables_rebuilt, 2, "{outcome:?}");
        assert_eq!(outcome.sstables_failed, 0, "{outcome:?}");
        assert!(outcome.is_complete(), "{outcome:?}");
        assert!(engine.index_is_current(&tid, "idx_pk"));
        drop(dir);
    }

    /// Reconciliation backstop. An index whose component does not exist in the
    /// partition key decodes to nothing for every partition: the build "succeeds"
    /// with an empty sidecar. Without reconciling indexed entries against the
    /// partitions the build enumerated, that reads as a complete, current,
    /// EMPTY index, which is the shape of the live 68% shortfall regardless of
    /// how any generation was classified.
    #[test]
    fn a_build_that_indexes_fewer_partitions_than_it_enumerated_does_not_mark_the_index_current() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.compaction.min_threshold = 50;
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        for i in 0..2 {
            engine
                .write(
                    &tid,
                    &make_key(&format!("k{i}")),
                    make_row(b"v", 1000),
                    1000,
                )
                .unwrap();
            engine.flush(&tid).unwrap();
        }

        // Component 5 of a one-component key: every partition decodes to None.
        let outcome = engine
            .add_partition_key_index(&tid, "idx_bad", 5, ferrosa_index::IndexType::BTree)
            .unwrap();

        assert_eq!(outcome.sstables_failed, 2, "{outcome:?}");
        assert!(!outcome.is_complete(), "{outcome:?}");
        assert!(
            !engine.index_is_current(&tid, "idx_bad"),
            "an index that covers 0 of the rows its build enumerated must not be current"
        );
    }

    /// A live generation with a TOC and no `Data.db` is discounted on the
    /// ASSUMPTION that compaction removed it. Nothing positively proves that,
    /// so each such discount must be visible: a WARN naming the generation, not
    /// an info line that scrolls past.
    #[test]
    fn a_metadata_only_generation_is_discounted_with_a_warn_naming_it() {
        let (dir, engine, tid, gens) = engine_with_indexed_generations(3);
        let table_dir = engine.table_sstable_dir(&tid);
        assert_eq!(remove_generation_files(&table_dir, &gens[0], true), 1);

        let logs = CapturedLogs::default();
        let subscriber = tracing_subscriber::fmt()
            .with_writer(logs.clone())
            .with_max_level(tracing::Level::WARN)
            .with_ansi(false)
            .finish();
        let outcome = tracing::subscriber::with_default(subscriber, || {
            engine.rebuild_index(&tid, "idx_pk").unwrap()
        });

        assert_eq!(outcome.sstables_vanished, 1, "{outcome:?}");
        let text = logs.text();
        assert!(
            text.contains("WARN") && text.contains(gens[0].as_str()),
            "the discounted generation {} must be named in a WARN; got: {text}",
            gens[0]
        );
        assert!(
            text.contains("unverified"),
            "the WARN must say the compaction claim is unverified: {text}"
        );
        drop(dir);
    }

    /// A rebuild walks the LIVE set. After a compaction retired older
    /// generations, every live generation is enumerated and indexed, and the
    /// retired ones are not named at all.
    #[tokio::test]
    async fn a_rebuild_enumerates_every_live_generation_after_compaction() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.compaction.min_threshold = 50;
        let engine = Arc::new(StorageEngine::new(config, None).unwrap());
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        let flush_key = |name: &str| {
            engine
                .write(&tid, &make_key(name), make_row(b"v", 1000), 1000)
                .unwrap();
            engine.flush(&tid).unwrap();
        };
        for name in ["k0", "k1", "k2", "k3"] {
            flush_key(name);
        }
        engine.force_compact_all();
        for _ in 0..1500 {
            engine.poll_compactions().await;
            if engine.sstable_count(&tid) == 1 {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        }
        assert_eq!(engine.sstable_count(&tid), 1, "compaction must swap in");
        for name in ["k4", "k5"] {
            flush_key(name);
        }
        engine
            .add_partition_key_index(&tid, "idx_pk", 0, ferrosa_index::IndexType::BTree)
            .unwrap();

        let outcome = engine.rebuild_index(&tid, "idx_pk").unwrap();

        assert_eq!(outcome.sstables_total, 3, "{outcome:?}");
        assert_eq!(outcome.sstables_rebuilt, 3, "{outcome:?}");
        assert!(outcome.is_complete(), "{outcome:?}");
        for name in ["k0", "k1", "k2", "k3", "k4", "k5"] {
            assert_eq!(
                pk_index_rows(&engine, &tid, name).unwrap(),
                1,
                "partition {name} must be reachable through the rebuilt index"
            );
        }
    }

    /// Eviction removes `Data.db` while the generation stays live, with a
    /// marker and the objects in S3. That is neither "compacted away" nor a
    /// stale entry: it must be rehydrated and indexed. Discounting it as
    /// vanished drops live rows from the index and reports it complete.
    #[tokio::test(flavor = "multi_thread")]
    async fn an_evicted_generation_is_rehydrated_and_indexed_not_discounted() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, gen, keys) =
            engine_with_evicted_sstable(dir.path(), "test-rebuild-evicted").await;
        let tid = table_id();
        assert!(StorageEngine::evicted_marker_path(&table_dir, &gen).exists());

        engine
            .add_partition_key_index(&tid, "idx_pk", 0, ferrosa_index::IndexType::BTree)
            .unwrap();

        assert!(
            engine.index_is_current(&tid, "idx_pk"),
            "the evicted generation was indexed, so the index is current"
        );
        for key in &keys {
            assert_eq!(
                pk_index_rows(&engine, &tid, key).unwrap(),
                1,
                "row {key} of the evicted SSTable must be in the index"
            );
        }
        let outcome = engine.rebuild_index(&tid, "idx_pk").unwrap();
        assert_eq!(outcome.sstables_vanished, 0, "{outcome:?}");
        assert_eq!(outcome.sstables_rebuilt, 1, "{outcome:?}");
        assert!(outcome.is_complete(), "{outcome:?}");
        engine.shutdown().unwrap();
    }

    /// Same, but the objects are gone: the rebuild fails loud and the index is
    /// NOT current. Never vanished.
    #[tokio::test(flavor = "multi_thread")]
    async fn an_evicted_generation_that_cannot_be_rehydrated_fails_the_rebuild() {
        let dir = tempfile::tempdir().unwrap();
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let (engine, table_dir, gen, _keys) =
            engine_with_evicted_sstable_in(dir.path(), "test-rebuild-evicted-gone", &store).await;
        let tid = table_id();
        delete_all_objects(&store).await;

        engine
            .add_partition_key_index(&tid, "idx_pk", 0, ferrosa_index::IndexType::BTree)
            .unwrap();
        let outcome = engine.rebuild_index(&tid, "idx_pk").unwrap();

        assert_eq!(outcome.sstables_failed, 1, "{outcome:?}");
        assert_eq!(outcome.sstables_vanished, 0, "{outcome:?}");
        assert!(!outcome.is_complete(), "{outcome:?}");
        assert!(!engine.index_is_current(&tid, "idx_pk"));
        assert!(
            pk_index_rows(&engine, &tid, "k0").is_err(),
            "a stale index must refuse reads"
        );
        assert!(
            StorageEngine::evicted_marker_path(&table_dir, &gen).exists(),
            "the marker stays so a later rehydrate can still find the generation"
        );
        engine.shutdown().unwrap();
    }

    /// An index on a PARTITION-KEY column must survive a restart (t_50c8bc7d).
    ///
    /// The live failure: `agent_memory.entity_store` is keyed
    /// `((tenant_id, session_id), entity_id)` and carries
    /// `idx_entity_by_tenant ON entity_store (tenant_id)`. After a restart the
    /// reload re-registered regular and clustering indexes but not this one,
    /// so it was counted as a "dangling registration" and dropped. The CQL
    /// schema still listed it, the planner still chose it, and the engine
    /// answered a consult of an index it did not have with zero rows —
    /// 101,848 entities read as an empty database.
    ///
    /// The storage schema carries no partition-key column NAMES (only the
    /// composite key type), so the reload is told them by the caller, which
    /// holds the CQL schema.
    /// t_7ac6b0e3: an index created over data already flushed answers for
    /// that data as soon as its backfill completes. The scheduler wrote the
    /// backfilled sidecar to disk and marked the SSTable indexed, but never
    /// installed it: the index read nothing for pre-existing SSTables until a
    /// restart loaded the file.
    #[test]
    fn a_backfilled_sidecar_is_served_without_a_restart() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        (0..15).for_each(|i| {
            engine
                .write(
                    &tid,
                    &make_key(&format!("k{i}")),
                    make_row(b"shared", 1000),
                    1000,
                )
                .unwrap();
        });
        engine.flush(&tid).unwrap();

        engine
            .add_index(&tid, "val_idx", 0, ferrosa_index::IndexType::BTree)
            .unwrap();
        // Hang guard, not a timing assertion: the backfill always completes.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        while !engine.index_is_current(&tid, "val_idx") && std::time::Instant::now() < deadline {
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        assert!(
            engine.index_is_current(&tid, "val_idx"),
            "the backfill must complete"
        );

        let found = collect_index_results(&engine, &tid, "val_idx", &IndexKey(b"shared".to_vec()))
            .unwrap()
            .len();
        assert_eq!(
            found, 15,
            "once its backfill is current, the index answers for data that predates it"
        );
        assert!(
            engine
                .sidecar_backings_for_test(&tid, "val_idx")
                .iter()
                .all(|mapped| *mapped),
            "the backfilled sidecar is mapped"
        );
    }

    /// ST-43 catch-up path: an index re-registered over SSTables it has not
    /// covered (what a restart does for every table) backfills them, and a
    /// later no-op flush must not knock it back to pending with a phantom
    /// SSTable — which would withhold the index from the planner for good.
    #[test]
    fn restart_backfill_survives_a_following_empty_flush() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let engine =
            StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        (0..5).for_each(|i| {
            engine
                .write(
                    &tid,
                    &make_key(&format!("k{i}")),
                    make_row(b"shared", 1000),
                    1000,
                )
                .unwrap();
        });
        engine.flush(&tid).unwrap();
        engine
            .add_index(&tid, "val_idx", 0, ferrosa_index::IndexType::BTree)
            .unwrap();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        while !engine.index_is_current(&tid, "val_idx") && std::time::Instant::now() < deadline {
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        assert!(
            engine.index_is_current(&tid, "val_idx"),
            "the backfill must complete"
        );

        engine.flush(&tid).unwrap();

        assert!(
            engine.index_is_current(&tid, "val_idx"),
            "a flush with nothing to write must leave a current index current"
        );
        assert_eq!(
            collect_index_results(&engine, &tid, "val_idx", &IndexKey(b"shared".to_vec()))
                .unwrap()
                .len(),
            5
        );
    }

    /// A planner-visible index with outstanding backfill work must never answer
    /// an empty or partial result as though it were complete. Callers can retry
    /// after the tracker becomes current, but they cannot recover rows hidden by
    /// a false successful response.
    #[test]
    fn a_pending_index_read_fails_loud() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        engine
            .add_index(&tid, "val_idx", 0, ferrosa_index::IndexType::BTree)
            .unwrap();
        engine
            .write(&tid, &make_key("present"), make_row(b"shared", 1000), 1000)
            .unwrap();
        engine.index_tracker.mark_pending(
            tid.keyspace(),
            tid.table(),
            "val_idx",
            "backfill-not-installed",
            1,
        );

        let error = collect_index_results(&engine, &tid, "val_idx", &IndexKey(b"shared".to_vec()))
            .expect_err("a pending index must refuse to return a partial result");
        assert!(
            error.to_string().contains("not current"),
            "pending-index error must explain why the read was refused: {error}"
        );
    }

    /// A partition-level DELETE as the write path receives it: empty clustering, no
    /// cells, a non-LIVE deletion.
    fn partition_delete_row(deleted_at: i64, local_deletion_time: u32) -> Row {
        Row {
            clustering: vec![],
            cells: vec![],
            deletion: DeletionTime::new(deleted_at, local_deletion_time),
            primary_key_liveness: LivenessInfo::NONE,
        }
    }

    /// Two SSTables — live partitions plus `dead`, then a tombstone for `dead` — and
    /// a compaction of both. Returns the output's partition count.
    async fn compact_dead_partition_scenario(
        gc_grace_seconds: &str,
        tombstone_ldt: u32,
        unflushed_older_write_ts: Option<i64>,
    ) -> u64 {
        let dir = tempfile::tempdir().unwrap();
        let mut config = StorageEngineConfig::test_config(dir.path());
        // Keep the engine's own automatic compaction out of the way: it would run
        // after the second flush, before the unflushed write below exists, and
        // legitimately purge. Only the explicit `force_compact_all` should run.
        config.compaction.min_threshold = 50;
        let engine = Arc::new(StorageEngine::new(config, None).unwrap());
        let mut schema = test_schema();
        schema.extensions.insert(
            ferrosa_common::schema::GC_GRACE_EXTENSION.to_string(),
            gc_grace_seconds.to_string(),
        );
        engine.register_table(schema).unwrap();
        let tid = table_id();
        for name in ["live0", "live1", "live2", "dead"] {
            engine
                .write(&tid, &make_key(name), make_row(b"v", 1000), 1000)
                .unwrap();
        }
        engine.flush(&tid).unwrap();
        engine
            .write(
                &tid,
                &make_key("dead"),
                partition_delete_row(2000, tombstone_ldt),
                2000,
            )
            .unwrap();
        engine.flush(&tid).unwrap();
        assert_eq!(engine.sstable_count(&tid), 2);
        if let Some(ts) = unflushed_older_write_ts {
            // Sits in the memtable, unflushed, older than the tombstone.
            engine
                .write(&tid, &make_key("late"), make_row(b"v", ts), ts)
                .unwrap();
        }

        engine.force_compact_all();
        for _ in 0..1500 {
            engine.poll_compactions().await;
            if engine.sstable_count(&tid) == 1 {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        }
        assert_eq!(engine.sstable_count(&tid), 1, "compaction must swap in");
        let tables = engine.tables.load();
        let state = tables.get(&tid).unwrap();
        engine.collect_sstable_metadata(&tid, state)[0].partition_count
    }

    const LONG_AGO_LDT: u32 = 1_000_000_000;

    /// P0 found 2026-09-28 in a real 3-node quorum: 5000 rows, half deleted,
    /// then compaction. The compaction output passed its own streaming
    /// readback, then failed the startup smoke test ("read_exact_at: wanted N
    /// bytes, got M"), so self-heal quarantined it and the node served a
    /// near-empty table. Same shape here, no cluster: a table with no
    /// clustering column, partition deletes inside gc grace, several inputs.
    #[tokio::test]
    async fn compaction_output_with_deleted_partitions_passes_the_startup_smoke_test() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.compaction.min_threshold = 50;
        let engine = Arc::new(StorageEngine::new(config, None).unwrap());
        let mut schema = test_schema();
        schema.clustering_columns.clear();
        engine.register_table(schema).unwrap();
        let tid = table_id();
        let payload = vec![b'x'; 200];
        for i in 0..5000i64 {
            let row = Row {
                clustering: vec![],
                cells: vec![(0, CellValue::live(payload.clone(), 1_000 + i))],
                deletion: DeletionTime::LIVE,
                primary_key_liveness: LivenessInfo::with_timestamp(1_000 + i),
            };
            engine
                .write(&tid, &make_key(&i.to_string()), row, 1_000 + i)
                .unwrap();
            if i % 1_000 == 999 {
                engine.flush(&tid).unwrap();
            }
        }
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs() as u32;
        for i in (0..5000i64).step_by(2) {
            let ts = 100_000 + i;
            engine
                .write(
                    &tid,
                    &make_key(&i.to_string()),
                    partition_delete_row(ts, now),
                    ts,
                )
                .unwrap();
        }
        engine.flush(&tid).unwrap();
        assert!(
            engine.sstable_count(&tid) >= 2,
            "compaction needs several inputs"
        );

        engine.force_compact_all();
        for _ in 0..1500 {
            engine.poll_compactions().await;
            if engine.sstable_count(&tid) == 1 {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        }
        assert_eq!(engine.sstable_count(&tid), 1, "compaction must swap in");

        let table_dir = engine.table_sstable_dir(&tid);
        let gens = StorageEngine::list_generations_in_dir(&table_dir);
        assert_eq!(
            gens.len(),
            1,
            "only the compaction output remains: {gens:?}"
        );
        for gen in gens {
            if let Err(e) = StorageEngine::smoke_test_generation(&table_dir, gen) {
                panic!("compaction output gen {gen} fails the startup smoke test: {e}");
            }
        }
    }

    #[test]
    fn tombstone_purging_is_on_unless_explicitly_switched_off() {
        assert!(parse_purge_enabled(None));
        assert!(parse_purge_enabled(Some("1")));
        assert!(parse_purge_enabled(Some("garbage")));
        for off in ["0", "false", "off", "no", " 0 "] {
            assert!(!parse_purge_enabled(Some(off)), "{off:?} switches it off");
        }
    }

    #[tokio::test]
    async fn compaction_purges_a_tombstone_past_gc_grace() {
        let purged_before = crate::metrics::compaction_purged_markers_total();
        // live0..2 survive; the `dead` partition and its tombstone are gone.
        assert_eq!(
            compact_dead_partition_scenario("0", LONG_AGO_LDT, None).await,
            3
        );
        assert!(crate::metrics::compaction_purged_markers_total() > purged_before);
    }

    #[tokio::test]
    async fn compaction_keeps_a_tombstone_still_inside_gc_grace() {
        // Deleted "now": ldt is the current time, well inside a 10-day grace period.
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs() as u32;
        assert_eq!(
            compact_dead_partition_scenario("864000", now, None).await,
            4
        );
    }

    #[tokio::test]
    async fn compaction_keeps_a_tombstone_that_unflushed_older_data_could_sit_under() {
        // A write with ts 500 is still in the memtable. The ts-2000 tombstone may
        // shadow data like it once that flushes, so it must survive this compaction.
        assert_eq!(
            compact_dead_partition_scenario("0", LONG_AGO_LDT, Some(500)).await,
            4
        );
    }

    /// t_7ac6b0e3: an index still answers for rows a compaction merged. The
    /// swap used to install the output SSTable with NO sidecars (and the
    /// rebuilt file was written to disk but never installed), so every scalar
    /// index silently lost the compacted rows until the next restart.
    #[tokio::test]
    async fn an_index_answers_for_rows_a_compaction_merged() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.compaction.min_threshold = 2;
        let engine = Arc::new(StorageEngine::new(config, None).unwrap());
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        engine
            .add_index(&tid, "val_idx", 0, ferrosa_index::IndexType::BTree)
            .unwrap();
        (0..10).for_each(|i| {
            engine
                .write(
                    &tid,
                    &make_key(&format!("a{i}")),
                    make_row(b"shared", 1000),
                    1000,
                )
                .unwrap();
        });
        engine.flush(&tid).unwrap();
        (0..10).for_each(|i| {
            engine
                .write(
                    &tid,
                    &make_key(&format!("b{i}")),
                    make_row(b"shared", 2000),
                    2000,
                )
                .unwrap();
        });
        engine.flush(&tid).unwrap();
        assert_eq!(engine.sstable_count(&tid), 2);
        let key = IndexKey(b"shared".to_vec());
        assert_eq!(
            collect_index_results(&engine, &tid, "val_idx", &key)
                .unwrap()
                .len(),
            20,
            "precondition: both SSTables' sidecars answer"
        );

        {
            let tables = engine.tables.load();
            let state = tables.get(&tid).unwrap();
            let metadata = engine.collect_sstable_metadata(&tid, state);
            drop(tables);
            engine
                .compaction_executor
                .submit(crate::compaction::metadata::CompactionTask {
                    inputs: metadata,
                    output_dir: dir.path().join("compaction"),
                    schema: test_schema(),
                    table_id: tid.clone(),
                    purge: None,
                })
                .unwrap();
        }
        // Hang guard (~30s), not a timing assertion.
        let mut swapped = false;
        for _ in 0..1500 {
            engine.poll_compactions().await;
            if engine.sstable_count(&tid) == 1 {
                swapped = true;
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        }
        assert!(swapped, "the compaction must merge the two SSTables");

        assert_eq!(
            collect_index_results(&engine, &tid, "val_idx", &key)
                .unwrap()
                .len(),
            20,
            "after the compaction, without a restart, the index must still answer \
             for every row the compaction merged"
        );
        assert!(
            engine
                .sidecar_backings_for_test(&tid, "val_idx")
                .iter()
                .all(|mapped| *mapped),
            "the compaction output's sidecar is mapped"
        );
    }

    /// t_7ac6b0e3: a flushed sidecar is served from its file through a
    /// memory map. Flush used to keep a heap copy of every flushed sidecar in
    /// the view for the life of the SSTable, beside the file it had written.
    #[test]
    fn a_flushed_sidecar_is_read_through_a_memory_map() {
        use ferrosa_index::IndexKey;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        engine
            .add_index(&tid, "val_idx", 0, ferrosa_index::IndexType::BTree)
            .unwrap();
        (0..20).for_each(|i| {
            engine
                .write(
                    &tid,
                    &make_key(&format!("k{i}")),
                    make_row(b"shared", 1000),
                    1000,
                )
                .unwrap();
        });
        engine.flush(&tid).unwrap();

        let backings = engine.sidecar_backings_for_test(&tid, "val_idx");
        assert!(!backings.is_empty(), "the flush produced a sidecar");
        assert!(
            backings.iter().all(|mapped| *mapped),
            "every flushed sidecar must be mapped, not a heap image: {backings:?}"
        );
        let found = collect_index_results(&engine, &tid, "val_idx", &IndexKey(b"shared".to_vec()))
            .unwrap()
            .len();
        assert_eq!(
            found, 20,
            "the mapped sidecar answers for every flushed row"
        );
    }

    #[test]
    fn a_partition_key_index_survives_restart_and_answers() {
        use ferrosa_index::IndexKey;
        use ferrosa_schema::system::persistence;

        let dir = tempfile::tempdir().unwrap();
        let tid = TableId::new("test_ks", "entity_store");
        let indexes_tid = TableId::new("system_schema", "indexes");
        let schema = ferrosa_common::TableSchema {
            keyspace: "test_ks".into(),
            table: "entity_store".into(),
            key_type: "org.apache.cassandra.db.marshal.CompositeType(\
                       org.apache.cassandra.db.marshal.UUIDType,\
                       org.apache.cassandra.db.marshal.UUIDType)"
                .into(),
            clustering_columns: vec![],
            static_columns: vec![],
            regular_columns: vec![ferrosa_common::ColumnDefinition {
                name: "body".into(),
                type_name: "org.apache.cassandra.db.marshal.UTF8Type".into(),
            }],
            extensions: Default::default(),
        };
        let idx_meta = ferrosa_schema::metadata::index::IndexMetadata {
            keyspace: "test_ks".into(),
            table: "entity_store".into(),
            name: "idx_by_tenant".into(),
            index_type: ferrosa_index::IndexType::BTree,
            target_columns: vec!["tenant_id".into()],
            filter_predicate: None,
            options: std::collections::HashMap::new(),
        };
        let mut tenant_a = [0u8; 16];
        tenant_a[0] = 1;

        let mut tenant_a_rows = 0usize;
        {
            let config = StorageEngineConfig::test_config(dir.path());
            let engine = StorageEngine::new(config, None).unwrap();
            engine.register_table(schema.clone()).unwrap();
            engine.register_system_tables().unwrap();
            engine
                .add_partition_key_index(&tid, "idx_by_tenant", 0, ferrosa_index::IndexType::BTree)
                .unwrap();
            let row = persistence::index_to_rows(&idx_meta);
            engine
                .write(&indexes_tid, &row.key, row.row, now_micros_for_test())
                .unwrap();

            for i in 0..8u8 {
                let mut tenant = [0u8; 16];
                tenant[0] = if i % 2 == 0 { 1 } else { 2 };
                if i % 2 == 0 {
                    tenant_a_rows += 1;
                }
                let mut session = [0u8; 16];
                session[0] = i;
                let row = Row {
                    clustering: vec![],
                    cells: vec![(0, CellValue::live(format!("row-{i}").into_bytes(), 1000))],
                    deletion: DeletionTime::LIVE,
                    primary_key_liveness: LivenessInfo::with_timestamp(1000),
                };
                engine
                    .write(&tid, &make_entity_store_pk(tenant, session), row, 1000)
                    .unwrap();
            }
            engine.flush(&tid).unwrap();
            engine.flush(&indexes_tid).unwrap();
        }

        let config = StorageEngineConfig::test_config(dir.path());
        let (engine, _pending) = StorageEngine::open(config, None).unwrap();
        engine.register_system_tables().unwrap();

        let partition_keys = PartitionKeyColumns::from([(
            tid.clone(),
            vec!["tenant_id".to_string(), "session_id".to_string()],
        )]);
        let outcome = engine
            .reload_indexes_from_system_schema(&partition_keys)
            .unwrap();
        assert_eq!(
            (outcome.restored, outcome.skipped),
            (1, 0),
            "the partition-key index must be RESTORED after a restart, not \
             skipped as a dangling registration"
        );

        let found: usize =
            collect_index_results(&engine, &tid, "idx_by_tenant", &IndexKey(tenant_a.to_vec()))
                .unwrap()
                .iter()
                .map(|p| p.rows.len())
                .sum();
        assert_eq!(
            found, tenant_a_rows,
            "after a restart the tenant index must still answer for every \
             flushed row of the tenant"
        );
    }

    /// Geo schema: a `places` table whose `location` column is a
    /// `frozen<tuple<double,double>>` indexed with `IndexType::Geo`.
    fn geo_schema() -> TableSchema {
        TableSchema {
            keyspace: "geo".to_string(),
            table: "places".to_string(),
            key_type: "org.apache.cassandra.db.marshal.UTF8Type".to_string(),
            clustering_columns: vec![],
            static_columns: vec![],
            regular_columns: vec![ColumnDefinition {
                name: "location".to_string(),
                type_name:
                    "org.apache.cassandra.db.marshal.FrozenType(org.apache.cassandra.db.marshal.TupleType(org.apache.cassandra.db.marshal.DoubleType,org.apache.cassandra.db.marshal.DoubleType))"
                        .to_string(),
            }],
            extensions: Default::default(),
        }
    }

    fn geo_tuple_bytes(lat: f64, lon: f64) -> Vec<u8> {
        let mut v = Vec::with_capacity(24);
        for f in [lat, lon] {
            v.extend_from_slice(&8i32.to_be_bytes());
            v.extend_from_slice(&f.to_be_bytes());
        }
        v
    }

    #[test]
    fn engine_read_by_index_cell_ranges_finds_points_in_cover() {
        use ferrosa_index::geo::{cover_radius, DEFAULT_COVER_LEVEL};
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let tid = TableId::new("geo", "places");
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(geo_schema()).unwrap();
        engine
            .add_index(&tid, "loc_geo", 0, IndexType::Geo)
            .unwrap();

        for (pk, lat, lon) in [
            ("ferry", 37.7955, -122.3937),
            ("union", 37.7880, -122.4074),
            ("nyc", 40.7580, -73.9855),
        ] {
            let row = Row {
                clustering: vec![],
                cells: vec![(0, CellValue::live(geo_tuple_bytes(lat, lon), 1000))],
                deletion: DeletionTime::LIVE,
                primary_key_liveness: LivenessInfo::with_timestamp(1000),
            };
            engine.write(&tid, &make_key(pk), row, 1000).unwrap();
        }

        let ranges: Vec<(u64, u64)> = cover_radius(37.7955, -122.3937, 3000.0, DEFAULT_COVER_LEVEL)
            .iter()
            .map(|r| (r.start, r.end))
            .collect();
        let partitions = engine
            .read_by_index_cell_ranges(&tid, "loc_geo", &ranges)
            .unwrap();
        // The two SF points are inside the 3km cover; NYC is far away.
        assert!(
            partitions.len() >= 2,
            "expected >= 2 SF partitions, got {}",
            partitions.len()
        );
        let pks: Vec<Vec<u8>> = partitions
            .iter()
            .map(|p| p.key.key.as_bytes().to_vec())
            .collect();
        assert!(pks.iter().any(|k| k == b"ferry"));
        assert!(pks.iter().any(|k| k == b"union"));

        engine.shutdown().unwrap();
    }

