    #[tokio::test]
    async fn compaction_retirement_crash_scope_resets_after_panic_and_drop() {
        use futures::FutureExt;

        let dir = tempfile::tempdir().unwrap();
        let input = StorageEngine::compaction_input_retirement_stub(dir.path(), "1");
        let crash = TEST_CRASH_AFTER_N_INPUT_RETIREMENTS.scope(1, async {
            StorageEngine::evict_local_input_sstable_files(
                &table_id(),
                std::slice::from_ref(&input),
            );
        });
        assert!(std::panic::AssertUnwindSafe(crash)
            .catch_unwind()
            .await
            .is_err());
        assert!(TEST_CRASH_AFTER_N_INPUT_RETIREMENTS
            .try_with(|_| ())
            .is_err());

        // Poll and then drop a pending injected future on this same task.
        let mut abandoned = Box::pin(TEST_CRASH_AFTER_N_INPUT_RETIREMENTS.scope(1, async {
            assert_eq!(TEST_CRASH_AFTER_N_INPUT_RETIREMENTS.get(), 1);
            std::future::pending::<()>().await;
        }));
        assert!(futures::poll!(abandoned.as_mut()).is_pending());
        drop(abandoned);
        assert!(TEST_CRASH_AFTER_N_INPUT_RETIREMENTS
            .try_with(|_| ())
            .is_err());
        StorageEngine::evict_local_input_sstable_files(&table_id(), &[input]);
    }

    #[tokio::test]
    async fn compaction_commit_phase_reaches_swapped_before_retirement_finishes() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, _store, _prefix, tid) = make_engine_with_pending_compaction(&dir).await;
        let engine = Arc::new(engine);
        let sstable_dir = dir.path().join("sstables").join(tid.to_string());

        // The compaction executor runs on a background thread and may not
        // have pushed its result onto the channel yet (the same race
        // `compaction_output_uploaded_to_s3` documents), so a no-op poll must
        // not be mistaken for the seam failing to fire.
        let mut crashed = false;
        for _ in 0..40 {
            let poll_engine = Arc::clone(&engine);
            let joined = tokio::spawn(
                TEST_CRASH_AFTER_N_INPUT_RETIREMENTS
                    .scope(1, async move { poll_engine.poll_compactions().await }),
            )
            .await;
            if joined.is_err() {
                crashed = true;
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        assert!(
            crashed,
            "the T-023 crash seam must panic inside poll_compactions once the compaction \
             result is available, to simulate a crash"
        );

        let mut records = leftover_intent_records(&sstable_dir);
        assert_eq!(
            records.len(),
            1,
            "the interrupted compaction must leave exactly one replacement record"
        );
        let record = crate::compaction::intent::CompactionIntentRecord::read_at(&records.remove(0))
            .unwrap()
            .unwrap();
        assert_eq!(
            record.phase,
            crate::compaction::intent::CompactionIntentPhase::Swapped,
            "the record must have advanced Promoting -> Swapped before retirement -- and \
             therefore Retired -- ever started"
        );
    }

    /// `test_schema()` plus `gc_grace_seconds = 0`, so a tombstone with an
    /// ancient `local_deletion_time` (see `LONG_AGO_LDT` further below, used
    /// by the pre-existing purge tests) is genuinely purgeable under
    /// purge.rs's real rules rather than test-rigged.
    fn dead_partition_schema() -> TableSchema {
        let mut schema = test_schema();
        schema.extensions.insert(
            ferrosa_common::schema::GC_GRACE_EXTENSION.to_string(),
            "0".to_string(),
        );
        schema
    }

    /// THE resurrection regression (forge `t_fca66994`): two inputs, A with a
    /// live row and B with a tombstone that purges it, compacted together and
    /// then crashed after retiring only B. Without T-023, restart discovers
    /// the purged-tombstone output alongside the still-live A and the row
    /// comes back. With it, startup finishes retiring A and the row stays
    /// dead.
    #[tokio::test]
    async fn compaction_reconcile_resurrection_regression_row_stays_dead_after_restart() {
        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let rt = tokio::runtime::Handle::current();
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let engine = Arc::new(
            StorageEngine::new_with_upload_store(
                config,
                Arc::clone(&store),
                "test-node".to_string(),
                &rt,
            )
            .unwrap(),
        );
        let tid = table_id();
        engine.register_table(dead_partition_schema()).unwrap();

        // Input A (flush 1): "dead" holds a live row, plus an unrelated live
        // partition so the compaction's output is not entirely purged away
        // (which would make the executor keep one unpurged partition instead
        // -- `compaction_purge_held_back_total`).
        engine
            .write(&tid, &make_key("live"), make_row(b"v", 1000), 1000)
            .unwrap();
        engine
            .write(&tid, &make_key("dead"), make_row(b"v", 1000), 1000)
            .unwrap();
        engine.flush(&tid).unwrap();

        // Input B (flush 2): a partition tombstone for "dead", using purge.rs's
        // real rules via `gc_grace_seconds = 0` and an ancient local deletion
        // time, so it is genuinely purgeable rather than test-rigged.
        engine
            .write(
                &tid,
                &make_key("dead"),
                partition_delete_row(2000, LONG_AGO_LDT),
                2000,
            )
            .unwrap();
        engine.flush(&tid).unwrap();

        let (input_a, input_b) = {
            let tables = engine.tables.load();
            let state = tables.get(&tid).unwrap();
            let mut metadata = engine.collect_sstable_metadata(&tid, state);
            metadata.sort_by_key(|m| m.id.parse::<u64>().unwrap());
            (metadata[0].clone(), metadata[1].clone())
        };

        // B first: the crash seam below retires whichever input is first.
        let inputs = vec![input_b.clone(), input_a.clone()];
        let purge = {
            let tables = engine.tables.load();
            let state = tables.get(&tid).unwrap();
            engine.purge_policy_for(&tid, state, &inputs)
        };
        assert!(purge.is_some(), "gc_grace_seconds=0 must enable purging");

        let compaction_output_dir = dir.path().join("compaction").join(tid.to_string());
        let task = crate::compaction::metadata::CompactionTask {
            inputs,
            output_dir: compaction_output_dir,
            schema: dead_partition_schema(),
            table_id: tid.clone(),
            purge,
        };
        engine.compaction_executor.submit(task).unwrap();

        // ST-T9e30472a: wait on the executor's completion signal (a result
        // parked for the next poll), not on a wall-clock budget or on files
        // appearing under `compaction/`. The single `poll_compactions` below
        // then integrates that result deterministically.
        wait_for_compaction_result(&engine);

        // Simulate a crash after retiring only B (the tombstone holder): the
        // real `poll_compactions` runs inside a spawned task, so the panic the
        // seam raises is caught by `tokio::spawn` as a `JoinError` instead of
        // failing this test -- exactly what a process crash looks like, since
        // no code past the panic point ever runs (no phase=Retired write, no
        // record deletion).
        let poll_engine = Arc::clone(&engine);
        let joined = tokio::spawn(
            TEST_CRASH_AFTER_N_INPUT_RETIREMENTS
                .scope(1, async move { poll_engine.poll_compactions().await }),
        )
        .await;
        assert!(
            joined.as_ref().is_err_and(|e| e.is_panic()),
            "the crash seam must panic in the one poll that integrates the available \
             compaction result, to simulate a crash; got {joined:?}"
        );

        let sstable_dir = dir.path().join("sstables").join(tid.to_string());
        assert!(
            StorageEngine::generation_component_path(&sstable_dir, &input_b.id, "Data.db")
                .is_none(),
            "B (the tombstone holder) must be retired before the simulated crash"
        );
        assert!(
            StorageEngine::generation_component_path(&sstable_dir, &input_a.id, "Data.db")
                .is_some(),
            "A (the row holder) must survive the simulated crash"
        );

        // Restart: drop the crashed engine first so a fresh instance can open
        // the same data dir, then rediscover from disk exactly as a real
        // restart would.
        drop(engine);
        let rt2 = tokio::runtime::Handle::current();
        let config2 = StorageEngineConfig::test_config(dir.path());
        let engine2 =
            StorageEngine::new_with_upload_store(config2, store, "test-node".to_string(), &rt2)
                .unwrap();
        engine2.register_table(dead_partition_schema()).unwrap();

        let partition = engine2.read(&tid, &make_key("dead")).unwrap();
        let resurrected = partition
            .map(|p| !p.rows.is_empty() || p.static_row.is_some())
            .unwrap_or(false);
        assert!(
            !resurrected,
            "dead's row must NOT resurrect after the crash and restart (forge t_fca66994)"
        );

        let live_partition = engine2.read(&tid, &make_key("live")).unwrap();
        assert!(
            live_partition.is_some_and(|p| !p.rows.is_empty()),
            "unrelated live data must survive reconciliation"
        );

        assert!(
            StorageEngine::generation_component_path(&sstable_dir, &input_a.id, "Data.db")
                .is_none(),
            "startup reconciliation must finish retiring A"
        );
        let records = leftover_intent_records(&sstable_dir);
        assert_eq!(records.len(), 1, "S3 convergence still owns the record");
        let record = crate::compaction::intent::CompactionIntentRecord::read_at(&records[0])
            .unwrap()
            .unwrap();
        assert_eq!(
            record.phase,
            crate::compaction::intent::CompactionIntentPhase::Retired
        );
    }

    #[test]
    fn compaction_reconcile_rolls_back_when_output_missing() {
        let dir = tempfile::tempdir().unwrap();
        let table_dir = dir.path().join("sstables").join("ks.t");
        std::fs::create_dir_all(&table_dir).unwrap();

        // An input that is still live -- rollback must leave it exactly alone.
        std::fs::write(table_dir.join("3-Data.db"), b"still here").unwrap();

        let record = crate::compaction::intent::CompactionIntentRecord {
            task_id: "50".to_string(),
            output_gen: "51".to_string(), // never promoted; no such generation exists
            output_digest: 123,
            inputs: vec!["3".to_string(), "4".to_string()],
            phase: crate::compaction::intent::CompactionIntentPhase::Promoting,
        };
        record.write(&table_dir).unwrap();

        let before = crate::metrics::compaction_reconcile_rolled_back_total();
        StorageEngine::reconcile_compaction_intents(&table_dir);

        assert!(
            leftover_intent_records(&table_dir).is_empty(),
            "a record whose output was never promoted must be deleted"
        );
        assert!(
            table_dir.join("3-Data.db").exists(),
            "rollback must leave a still-live input untouched"
        );
        assert!(crate::metrics::compaction_reconcile_rolled_back_total() > before);
    }

    #[test]
    fn compaction_reconcile_quarantines_digest_mismatch_and_keeps_inputs() {
        let dir = tempfile::tempdir().unwrap();
        let table_dir = dir.path().join("sstables").join("ks.t");
        std::fs::create_dir_all(&table_dir).unwrap();

        let gen_dir = table_dir.join("5");
        std::fs::create_dir_all(&gen_dir).unwrap();
        std::fs::write(gen_dir.join("5-Data.db"), b"promoted but corrupted").unwrap();
        std::fs::write(
            gen_dir.join("5-Digest.crc32"),
            ferrosa_sstable::checksum::format_digest(12345),
        )
        .unwrap();
        std::fs::write(table_dir.join("3-Data.db"), b"an input").unwrap();

        let record = crate::compaction::intent::CompactionIntentRecord {
            task_id: "99".to_string(),
            output_gen: "5".to_string(),
            output_digest: 999, // does not match the 12345 written above
            inputs: vec!["3".to_string(), "4".to_string()],
            phase: crate::compaction::intent::CompactionIntentPhase::Swapped,
        };
        record.write(&table_dir).unwrap();

        let before = crate::metrics::compaction_reconcile_digest_mismatch_total();
        StorageEngine::reconcile_compaction_intents(&table_dir);

        assert!(
            !gen_dir.exists(),
            "a digest-mismatched output must never be left live"
        );
        assert!(
            table_dir.join("quarantine").join("5-Data.db").exists(),
            "the quarantined component must land in quarantine/"
        );
        assert!(
            leftover_intent_records(&table_dir).is_empty(),
            "the record must be deleted after quarantining its output"
        );
        assert!(
            table_dir.join("3-Data.db").exists(),
            "inputs must be kept live on a digest mismatch"
        );
        assert!(crate::metrics::compaction_reconcile_digest_mismatch_total() > before);
    }

    #[test]
    fn compaction_reconcile_sweeps_promote_star_debris_and_stale_intent_tmp_files() {
        let dir = tempfile::tempdir().unwrap();
        let table_dir = dir.path().join("sstables").join("ks.t");
        std::fs::create_dir_all(&table_dir).unwrap();

        let promote_debris = table_dir.join(".promote-1234-abcd");
        std::fs::create_dir_all(&promote_debris).unwrap();
        std::fs::write(promote_debris.join("1234-Data.db"), b"partial").unwrap();

        let tmp_intent = table_dir.join(".compaction-77.intent.tmp");
        std::fs::write(&tmp_intent, b"{}").unwrap();

        StorageEngine::reconcile_compaction_intents(&table_dir);

        assert!(
            !promote_debris.exists(),
            "leftover .promote-* staging must be swept at startup (window B)"
        );
        assert!(
            !tmp_intent.exists(),
            "a stale .intent.tmp left by an interrupted record write must be swept too"
        );
    }

    #[test]
    fn compaction_reconcile_no_records_is_a_noop_on_restart() {
        let dir = tempfile::tempdir().unwrap();
        let table_dir = dir.path().join("sstables").join("ks.t");
        std::fs::create_dir_all(&table_dir).unwrap();
        std::fs::write(table_dir.join("7-Data.db"), b"an ordinary live generation").unwrap();

        StorageEngine::reconcile_compaction_intents(&table_dir);

        assert!(
            table_dir.join("7-Data.db").exists(),
            "a table dir with no replacement records must be left untouched"
        );
    }

    #[test]
    fn compaction_promotion_preserves_other_pending_outputs_in_shared_staging_dir() {
        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        let tid = table_id();
        let tid_str = tid.to_string();
        let compaction_dir = dir.path().join("compaction").join(&tid_str);
        std::fs::create_dir_all(&compaction_dir).unwrap();

        let output_a = write_fake_compaction_output(&compaction_dir, "101");
        let output_b = write_fake_compaction_output(&compaction_dir, "202");

        let promoted_a = promote_via_reserve(&engine, &tid, &output_a)
            .expect("first compaction output should promote");
        assert!(
            promoted_a
                .path
                .join(format!("{}-Data.db", promoted_a.id))
                .exists(),
            "first output should be durable in the normal SSTable directory"
        );

        for component in [
            "Data.db",
            "Partitions.db",
            "Rows.db",
            "Filter.db",
            "Statistics.db",
            "TOC.txt",
        ] {
            let pending = compaction_dir.join(format!("202-{component}"));
            assert!(
                pending.exists(),
                "promoting one output must not delete pending component {}",
                pending.display()
            );
        }

        let promoted_b = promote_via_reserve(&engine, &tid, &output_b)
            .expect("second output should still promote after the first output");
        assert!(
            promoted_b
                .path
                .join(format!("{}-Data.db", promoted_b.id))
                .exists(),
            "second output should be durable in the normal SSTable directory"
        );

        let remaining: Vec<_> = compaction_dir
            .read_dir()
            .into_iter()
            .flatten()
            .filter_map(|entry| entry.ok())
            .collect();
        assert!(
            remaining.is_empty(),
            "shared compaction directory should be empty after all outputs promote"
        );
    }

    fn write_fake_compaction_output(
        compaction_dir: &std::path::Path,
        id: &str,
    ) -> crate::compaction::metadata::SSTableMetadata {
        for component in [
            "Data.db",
            "Partitions.db",
            "Rows.db",
            "Filter.db",
            "Statistics.db",
        ] {
            std::fs::write(
                compaction_dir.join(format!("{id}-{component}")),
                format!("{id}-{component}"),
            )
            .unwrap();
        }
        std::fs::write(
            compaction_dir.join(format!("{id}-TOC.txt")),
            b"Data.db\nPartitions.db\nRows.db\nFilter.db\nStatistics.db\n",
        )
        .unwrap();

        crate::compaction::metadata::SSTableMetadata {
            id: id.to_string(),
            path: compaction_dir.to_path_buf(),
            size_bytes: 128,
            min_token: 0,
            max_token: 1,
            min_timestamp: 10,
            max_timestamp: 20,
            partition_count: 1,
            legacy_format: false,
        }
    }

    // ── T-027: metrics + end-to-end tests ────────────────────────────────────

    /// Verifies that compaction S3 metrics are accurate after a compaction
    /// cycle that uploads the output and enqueues input deletions.
    ///
    /// Uses an in-memory object store (no Docker required).
    #[tokio::test]
    async fn compaction_s3_metrics_accurate() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, _store, _prefix, _tid) = make_engine_with_pending_compaction(&dir).await;

        // Before poll_compactions: all counters must be zero.
        assert_eq!(
            engine
                .compaction_metrics
                .s3_uploads_total
                .load(std::sync::atomic::Ordering::Relaxed),
            0,
            "s3_uploads_total should be 0 before poll_compactions"
        );
        assert_eq!(
            engine
                .compaction_metrics
                .s3_deletes_total
                .load(std::sync::atomic::Ordering::Relaxed),
            0,
            "s3_deletes_total should be 0 before poll_compactions"
        );
        assert_eq!(
            engine
                .compaction_metrics
                .input_bytes_reclaimed
                .load(std::sync::atomic::Ordering::Relaxed),
            0,
            "input_bytes_reclaimed should be 0 before poll_compactions"
        );

        // Run compaction: merges 2 SSTables → 1 output, uploads to S3,
        // updates manifest, enqueues 2 input deletions. Retry until the channel
        // result is consumed (compaction thread writes files before channel send).
        wait_for_compaction_result(&engine);
        for _ in 0..40 {
            engine.poll_compactions().await;
            if engine
                .compaction_metrics
                .s3_uploads_total
                .load(std::sync::atomic::Ordering::Relaxed)
                > 0
            {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }

        // Exactly 1 upload (the compacted output SSTable).
        assert_eq!(
            engine
                .compaction_metrics
                .s3_uploads_total
                .load(std::sync::atomic::Ordering::Relaxed),
            1,
            "s3_uploads_total should be 1 after compacting 2 SSTables into 1"
        );

        // Exactly 2 deletes enqueued (one per input SSTable).
        assert_eq!(
            engine
                .compaction_metrics
                .s3_deletes_total
                .load(std::sync::atomic::Ordering::Relaxed),
            2,
            "s3_deletes_total should be 2 (one per input SSTable)"
        );

        // Input bytes reclaimed must be positive (inputs had non-zero size).
        assert!(
            engine
                .compaction_metrics
                .input_bytes_reclaimed
                .load(std::sync::atomic::Ordering::Relaxed)
                > 0,
            "input_bytes_reclaimed should be > 0 after compaction"
        );

        // Verify Prometheus text export contains all three metric names.
        let text = engine.compaction_metrics.to_prometheus_text();
        assert!(
            text.contains("ferrosa_compaction_s3_uploads_total 1"),
            "prometheus text missing uploads counter: {text}"
        );
        assert!(
            text.contains("ferrosa_compaction_s3_deletes_total 2"),
            "prometheus text missing deletes counter: {text}"
        );
        assert!(
            text.contains("ferrosa_compaction_input_bytes_reclaimed"),
            "prometheus text missing bytes reclaimed gauge: {text}"
        );
    }

    /// Cassandra 5 reads a compacted SSTable from S3 (MinIO).
    ///
    /// Test flow:
    ///   1. Flush 2 SSTables with distinct partition keys and multiple cell types.
    ///   2. Compact them → single merged SSTable uploaded to MinIO.
    ///   3. Cassandra 5 mounts the MinIO-backed data directory and scans the table.
    ///   4. All original rows and cell types are present in the Cassandra output.
    ///
    /// Requires MinIO + Cassandra 5 containers (Docker or Podman).
    /// Set FERROSA_TEST_CONTAINERS=1 after starting the compose stack.
    #[cfg(feature = "live-infra-tests")]
    #[tokio::test]
    async fn cassandra_reads_compacted_sstable_from_s3() {
        if std::env::var("FERROSA_TEST_CONTAINERS").is_err() {
            panic!(
                "FERROSA_TEST_CONTAINERS not set — start MinIO+Cassandra containers \
                 (docker/podman compose up -d) then re-run with FERROSA_TEST_CONTAINERS=1"
            );
        }
        use std::process::Command;

        // ── Step 1: build engine, flush 2 SSTables with varied cell types ──
        let dir = tempfile::tempdir().unwrap();
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let prefix = "ferrosa-test".to_string();
        let rt = tokio::runtime::Handle::current();
        let engine = StorageEngine::new_with_upload_store(
            StorageEngineConfig::test_config(dir.path()),
            Arc::clone(&store),
            prefix.clone(),
            &rt,
        )
        .unwrap();

        let schema = TableSchema {
            keyspace: "test_ks".into(),
            table: "mixed_cells".into(),
            key_type: "org.apache.cassandra.db.marshal.UTF8Type".into(),
            clustering_columns: vec![],
            static_columns: vec![],
            regular_columns: vec![
                ferrosa_common::schema::ColumnDefinition {
                    name: "v_int".into(),
                    type_name: "org.apache.cassandra.db.marshal.Int32Type".into(),
                },
                ferrosa_common::schema::ColumnDefinition {
                    name: "v_text".into(),
                    type_name: "org.apache.cassandra.db.marshal.UTF8Type".into(),
                },
            ],
            extensions: Default::default(),
        };
        engine.register_table(schema).unwrap();
        let tid = TableId::new("test_ks", "mixed_cells");

        // Flush 1: row with text cell.
        let k1 = make_key("pk1");
        let row1 = ferrosa_sstable::types::Row {
            clustering: vec![],
            cells: vec![(
                1,
                ferrosa_common::cell::CellValue::live(b"hello".to_vec(), 1000),
            )],
            deletion: ferrosa_sstable::types::DeletionTime::LIVE,
            primary_key_liveness: ferrosa_sstable::types::LivenessInfo::with_timestamp(1000),
        };
        engine.write(&tid, &k1, row1, 1000).unwrap();
        engine.flush(&tid).unwrap();

        // Flush 2: row with int cell.
        let k2 = make_key("pk2");
        let int_bytes = 42i32.to_be_bytes().to_vec();
        let row2 = ferrosa_sstable::types::Row {
            clustering: vec![],
            cells: vec![(0, ferrosa_common::cell::CellValue::live(int_bytes, 2000))],
            deletion: ferrosa_sstable::types::DeletionTime::LIVE,
            primary_key_liveness: ferrosa_sstable::types::LivenessInfo::with_timestamp(2000),
        };
        engine.write(&tid, &k2, row2, 2000).unwrap();
        engine.flush(&tid).unwrap();

        // ── Step 2: compact and upload to MinIO ──
        {
            let tables = engine.tables.load();
            let state = tables.get(&tid).unwrap();
            let metadata = engine.collect_sstable_metadata(&tid, state);
            drop(tables);

            let compaction_output_dir = dir.path().join("compaction");
            let task = crate::compaction::metadata::CompactionTask {
                inputs: metadata,
                output_dir: compaction_output_dir.clone(),
                schema: TableSchema {
                    keyspace: "test_ks".into(),
                    table: "mixed_cells".into(),
                    key_type: "org.apache.cassandra.db.marshal.UTF8Type".into(),
                    clustering_columns: vec![],
                    static_columns: vec![],
                    regular_columns: vec![
                        ferrosa_common::schema::ColumnDefinition {
                            name: "v_int".into(),
                            type_name: "org.apache.cassandra.db.marshal.Int32Type".into(),
                        },
                        ferrosa_common::schema::ColumnDefinition {
                            name: "v_text".into(),
                            type_name: "org.apache.cassandra.db.marshal.UTF8Type".into(),
                        },
                    ],
                    extensions: Default::default(),
                },
                table_id: tid.clone(),
                purge: None,
            };
            engine.compaction_executor.submit(task).unwrap();
        }

        // Wait for the executor to finish, on the deterministic completion
        // signal rather than racing the filesystem (T-091): a file can
        // appear under compaction/ while the executor is still mid-write,
        // and this call site polls compactions exactly once afterward with
        // no retry, so an early wakeup here would fail the upload assertion
        // below outright rather than merely racing it.
        let compaction_completed = engine
            .compaction_executor
            .wait_for_result(std::time::Duration::from_secs(120))
            .await;
        assert!(
            compaction_completed,
            "compaction task did not complete within 120s; executor state: \
             pending_result_count={}",
            engine.compaction_executor.pending_result_count()
        );
        engine.poll_compactions().await;

        // Verify the output is in S3.
        assert_eq!(
            engine
                .compaction_metrics
                .s3_uploads_total
                .load(std::sync::atomic::Ordering::Relaxed),
            1,
            "compacted SSTable must be uploaded before Cassandra read"
        );

        // ── Step 3: start Cassandra container ──
        let compose_file = workspace_path("tests/docker/compaction-cassandra.yml");
        let cassandra_up = Command::new(container_runtime())
            .args(["compose", "-f", compose_file.to_str().unwrap(), "up", "-d"])
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        assert!(
            cassandra_up,
            "failed to start Cassandra container — is the runtime running?"
        );

        // Allow Cassandra to initialize (up to 120 s).
        // Two-phase probe: first wait for nodetool (JMX), then verify CQL responds,
        // because nodetool can succeed ~10 s before the CQL listener is ready.
        let mut cassandra_ready = false;
        'outer: for _ in 0..120 {
            tokio::time::sleep(std::time::Duration::from_secs(1)).await;
            let jmx_ok = Command::new(container_runtime())
                .args(["exec", "ferrosa-cassandra-test", "nodetool", "status"])
                .status()
                .map(|s| s.success())
                .unwrap_or(false);
            if !jmx_ok {
                continue;
            }
            // JMX ready — now wait for CQL port to accept a query.
            for _ in 0..15 {
                tokio::time::sleep(std::time::Duration::from_secs(1)).await;
                let cql_ok = Command::new(container_runtime())
                    .args([
                        "exec",
                        "ferrosa-cassandra-test",
                        "cqlsh",
                        "--execute",
                        "SELECT now() FROM system.local;",
                    ])
                    .status()
                    .map(|s| s.success())
                    .unwrap_or(false);
                if cql_ok {
                    cassandra_ready = true;
                    break 'outer;
                }
            }
        }
        assert!(
            cassandra_ready,
            "Cassandra did not become ready within 120 s"
        );

        // ── Step 4: create keyspace + table so nodetool import has a target ──
        let create_schema = "\
            CREATE KEYSPACE IF NOT EXISTS test_ks WITH replication = \
              {'class': 'SimpleStrategy', 'replication_factor': 1};\
            CREATE TABLE IF NOT EXISTS test_ks.mixed_cells \
              (pk text PRIMARY KEY, v_text text, v_int int);";
        let schema_ok = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "cqlsh",
                "--execute",
                create_schema,
            ])
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        assert!(schema_ok, "failed to create keyspace/table in Cassandra");

        let (manifest, _) = crate::manifest::Manifest::load(store.as_ref(), &prefix)
            .await
            .unwrap();
        let tid_str = tid.to_string();
        let entries = manifest.sstables.get(&tid_str).cloned().unwrap_or_default();
        assert_eq!(
            entries.len(),
            1,
            "manifest should contain exactly one promoted compacted SSTable"
        );
        let promoted_gen = entries[0].id.clone();
        let sstable_dir = dir.path().join("sstables").join(&tid_str);
        let import_source = StorageEngine::generation_dir_path(
            &sstable_dir,
            promoted_gen
                .parse::<u64>()
                .expect("numeric promoted generation"),
        )
        .expect("promoted compaction generation should be visible in SSTable directory");

        // ── Step 5: copy SSTable files into container and run nodetool import ──
        // Ferrosa names files `{gen}-Data.db`; Cassandra's SSTableLoader expects
        // the BTI descriptor prefix `da-{gen}-bti-`.  prepare_cassandra_import_dir
        // renames the files and rewrites the TOC.txt.
        let import_staging = dir.path().join("cassandra-import");
        prepare_cassandra_import_dir(&import_source, &import_staging);

        // Replace ferrosa's empty CompactionMetadata/StatsMetadata with real
        // Cassandra 5 bytes so nodetool import can deserialize Statistics.db.
        patch_statistics_for_cassandra_import(&import_staging);

        // Clean the import volume so stale files from previous runs don't confuse Cassandra.
        let _ = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "sh",
                "-c",
                "rm -f /var/lib/cassandra/import/*",
            ])
            .status();

        // Copy the renamed files into the container's import directory.
        for entry in std::fs::read_dir(&import_staging).expect("read import staging dir") {
            let src = entry.expect("entry").path();
            let cp_ok = Command::new(container_runtime())
                .args([
                    "cp",
                    src.to_str().unwrap(),
                    "ferrosa-cassandra-test:/var/lib/cassandra/import/",
                ])
                .status()
                .map(|s| s.success())
                .unwrap_or(false);
            assert!(cp_ok, "docker cp failed for {:?}", src);
        }

        // Import the SSTable into the running Cassandra node.
        let import_ok = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "nodetool",
                "import",
                "test_ks",
                "mixed_cells",
                "/var/lib/cassandra/import",
            ])
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        assert!(import_ok, "nodetool import failed");

        // ── Step 6: verify rows via exact partition reads and full scan ──
        let pk1_output = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "cqlsh",
                "--execute",
                "SELECT pk, v_text, v_int FROM test_ks.mixed_cells WHERE pk='pk1';",
            ])
            .output()
            .expect("cqlsh failed");

        let pk1_stdout = String::from_utf8_lossy(&pk1_output.stdout);
        let pk1_stderr = String::from_utf8_lossy(&pk1_output.stderr);

        assert!(
            pk1_stdout.contains("pk1") && pk1_stdout.contains("hello"),
            "Cassandra output missing pk1/v_text row.\nstdout: {pk1_stdout}\nstderr: {pk1_stderr}"
        );

        let pk2_output = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "cqlsh",
                "--execute",
                "SELECT pk, v_text, v_int FROM test_ks.mixed_cells WHERE pk='pk2';",
            ])
            .output()
            .expect("cqlsh failed");

        let pk2_stdout = String::from_utf8_lossy(&pk2_output.stdout);
        let pk2_stderr = String::from_utf8_lossy(&pk2_output.stderr);

        assert!(
            pk2_stdout.contains("pk2") && pk2_stdout.contains("42"),
            "Cassandra output missing pk2/v_int row.\nstdout: {pk2_stdout}\nstderr: {pk2_stderr}"
        );

        let scan_output = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "cqlsh",
                "--execute",
                "SELECT pk, v_text, v_int FROM test_ks.mixed_cells;",
            ])
            .output()
            .expect("cqlsh full scan failed");

        let scan_stdout = String::from_utf8_lossy(&scan_output.stdout);
        let scan_stderr = String::from_utf8_lossy(&scan_output.stderr);

        assert!(
            scan_output.status.success()
                && scan_stdout.contains("pk1")
                && scan_stdout.contains("hello")
                && scan_stdout.contains("pk2")
                && scan_stdout.contains("42"),
            "Cassandra full scan must read both imported rows.\nstdout: {scan_stdout}\nstderr: {scan_stderr}"
        );

        // Cleanup.
        let _ = Command::new(container_runtime())
            .args([
                "compose",
                "-f",
                compose_file.to_str().unwrap(),
                "down",
                "-v",
            ])
            .status();
    }

    /// End-to-end compaction pipeline: 4 flush cycles trigger STCS compaction,
    /// the output is confirmed in S3, the manifest is updated, old files are
    /// evicted locally, and Cassandra 5 can read the result from MinIO.
    ///
    /// Pipeline:
    ///   4 flushes → STCS detects 4-SSTable bucket → compaction triggered
    ///   → output uploaded to MinIO → manifest updated (1 entry)
    ///   → input SSTable files deleted locally
    ///   → Cassandra 5 reads all 4 partition keys from compacted SSTable
    ///
    /// Requires MinIO + Cassandra 5 containers (Docker or Podman).
    /// Set FERROSA_TEST_CONTAINERS=1 after starting the compose stack.
    #[cfg(feature = "live-infra-tests")]
    #[tokio::test]
    async fn compaction_end_to_end_pipeline() {
        if std::env::var("FERROSA_TEST_CONTAINERS").is_err() {
            panic!(
                "FERROSA_TEST_CONTAINERS not set — start MinIO+Cassandra containers \
                 (docker/podman compose up -d) then re-run with FERROSA_TEST_CONTAINERS=1"
            );
        }
        use std::process::Command;

        let dir = tempfile::tempdir().unwrap();
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let prefix = "ferrosa-e2e".to_string();
        let rt = tokio::runtime::Handle::current();

        // Use min_threshold=4 and a deliberately wide test bucket so these
        // tiny fixture SSTables compact as one STCS group. The production
        // default bucket ratio may correctly split very small files whose
        // fixed component overhead dominates their logical data size.
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.compaction.min_threshold = 4;
        config.compaction.bucket_low = 0.0;
        config.compaction.bucket_high = 2.0;
        let engine =
            StorageEngine::new_with_upload_store(config, Arc::clone(&store), prefix.clone(), &rt)
                .unwrap();
        engine.register_table(test_schema()).unwrap();
        let tid = table_id();

        // ── 4 flush cycles (each writes 1 partition to its own SSTable) ──
        for (i, key_suffix) in ["a", "b", "c", "d"].iter().enumerate() {
            let ts = (i as i64 + 1) * 1000;
            let value = format!("value-{key_suffix}");
            engine
                .write(
                    &tid,
                    &make_key(key_suffix),
                    make_row(value.as_bytes(), ts),
                    ts,
                )
                .unwrap();
            engine.flush(&tid).unwrap();
            // flush() calls maybe_compact(); on the 4th flush STCS will submit a task.
        }

        {
            let tables = engine.tables.load();
            let state = tables.get(&tid).unwrap();
            let metadata = engine.collect_sstable_metadata(&tid, state);
            let strategy = engine.strategy_for_table(state);
            let selected = strategy.select(&metadata, &state.schema(), &tid);
            assert_eq!(
                selected.len(),
                1,
                "configured STCS bucket should select the four E2E fixture SSTables; sizes={:?}",
                metadata.iter().map(|m| m.size_bytes).collect::<Vec<_>>()
            );
        }

        // Wait for the compaction executor background thread to finish, on
        // the deterministic completion signal rather than racing the
        // filesystem (T-091): a file can appear under compaction/ while the
        // executor is still mid-write.
        let compaction_completed = engine
            .compaction_executor
            .wait_for_result(std::time::Duration::from_secs(120))
            .await;
        assert!(
            compaction_completed,
            "compaction task did not complete within 120s; executor state: \
             pending_result_count={}",
            engine.compaction_executor.pending_result_count()
        );

        // ── poll_compactions: upload, manifest update, local eviction ──
        //
        // The executor writes compaction components before publishing the
        // completed result on its channel. A single non-blocking poll can race
        // that handoff; the production contract is eventual pickup by the
        // periodic poller, so this test waits for the observable upload.
        for _ in 0..100 {
            engine.poll_compactions().await;
            if engine
                .compaction_metrics
                .s3_uploads_total
                .load(std::sync::atomic::Ordering::Relaxed)
                == 1
            {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }

        // Upload confirmed — exactly 1 output SSTable uploaded.
        assert_eq!(
            engine
                .compaction_metrics
                .s3_uploads_total
                .load(std::sync::atomic::Ordering::Relaxed),
            1,
            "expected 1 S3 upload after STCS compaction of 4 SSTables"
        );

        // 4 input deletions enqueued.
        assert_eq!(
            engine
                .compaction_metrics
                .s3_deletes_total
                .load(std::sync::atomic::Ordering::Relaxed),
            4,
            "expected 4 S3 delete tasks for 4 input SSTables"
        );

        // Manifest: exactly 1 SSTable entry (the merged output).
        let (manifest, _) = crate::manifest::Manifest::load(store.as_ref(), &prefix)
            .await
            .unwrap();
        let tid_str = tid.to_string();
        let entries = manifest.sstables.get(&tid_str).cloned().unwrap_or_default();
        assert_eq!(
            entries.len(),
            1,
            "manifest should have exactly 1 SSTable entry after STCS compaction"
        );

        // Local input files must be evicted while the promoted output remains live.
        let sstable_dir = dir.path().join("sstables").join(&tid_str);
        let output_gen = entries[0].id.parse::<u64>().expect("numeric output id");
        let import_source = StorageEngine::generation_dir_path(&sstable_dir, output_gen)
            .expect("promoted compaction generation should be visible in SSTable directory");
        assert!(
            StorageEngine::generation_component_path(&sstable_dir, &entries[0].id, "Data.db")
                .is_some(),
            "promoted compacted SSTable Data.db should remain live"
        );
        if sstable_dir.exists() {
            let remaining_db_files: Vec<_> = std::fs::read_dir(&sstable_dir)
                .unwrap()
                .filter_map(|e| e.ok())
                .map(|e| e.path())
                .filter(|p| p.extension().map(|e| e == "db").unwrap_or(false))
                .collect();
            assert!(
                remaining_db_files.is_empty(),
                "all input .db files should be evicted after poll_compactions, remaining: {:?}",
                remaining_db_files
            );
        }

        // ── Cassandra: verify all 4 partition keys are readable ──
        let compose_file = workspace_path("tests/docker/compaction-cassandra.yml");
        let cassandra_up = Command::new(container_runtime())
            .args(["compose", "-f", compose_file.to_str().unwrap(), "up", "-d"])
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        assert!(cassandra_up, "failed to start Cassandra container");

        let mut cassandra_ready = false;
        'outer2: for _ in 0..120 {
            tokio::time::sleep(std::time::Duration::from_secs(1)).await;
            let jmx_ok = Command::new(container_runtime())
                .args(["exec", "ferrosa-cassandra-test", "nodetool", "status"])
                .status()
                .map(|s| s.success())
                .unwrap_or(false);
            if !jmx_ok {
                continue;
            }
            for _ in 0..15 {
                tokio::time::sleep(std::time::Duration::from_secs(1)).await;
                let cql_ok = Command::new(container_runtime())
                    .args([
                        "exec",
                        "ferrosa-cassandra-test",
                        "cqlsh",
                        "--execute",
                        "SELECT now() FROM system.local;",
                    ])
                    .status()
                    .map(|s| s.success())
                    .unwrap_or(false);
                if cql_ok {
                    cassandra_ready = true;
                    break 'outer2;
                }
            }
        }
        assert!(
            cassandra_ready,
            "Cassandra did not become ready within 120 s"
        );

        // test_schema() → test_ks.test_table with pk (text), ck (int), val (text)
        let create_schema = "\
            CREATE KEYSPACE IF NOT EXISTS test_ks WITH replication = \
              {'class': 'SimpleStrategy', 'replication_factor': 1};\
            CREATE TABLE IF NOT EXISTS test_ks.test_table \
              (pk text, ck int, val text, PRIMARY KEY (pk, ck));";
        let schema_ok = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "cqlsh",
                "--execute",
                create_schema,
            ])
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        assert!(schema_ok, "failed to create keyspace/table in Cassandra");

        let import_staging = dir.path().join("cassandra-import");
        prepare_cassandra_import_dir(&import_source, &import_staging);

        // Replace ferrosa's empty CompactionMetadata/StatsMetadata with real
        // Cassandra 5 bytes so nodetool import can deserialize Statistics.db.
        patch_statistics_for_cassandra_import(&import_staging);

        // Clean the import volume so stale files from previous runs don't confuse Cassandra.
        let _ = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "sh",
                "-c",
                "rm -f /var/lib/cassandra/import/*",
            ])
            .status();

        for entry in std::fs::read_dir(&import_staging).expect("read import staging dir") {
            let src = entry.expect("entry").path();
            let cp_ok = Command::new(container_runtime())
                .args([
                    "cp",
                    src.to_str().unwrap(),
                    "ferrosa-cassandra-test:/var/lib/cassandra/import/",
                ])
                .status()
                .map(|s| s.success())
                .unwrap_or(false);
            assert!(cp_ok, "docker cp failed for {:?}", src);
        }

        let import_ok = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "nodetool",
                "import",
                "test_ks",
                "test_table",
                "/var/lib/cassandra/import",
            ])
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        assert!(import_ok, "nodetool import failed");

        let cql_output = Command::new(container_runtime())
            .args([
                "exec",
                "ferrosa-cassandra-test",
                "cqlsh",
                "--execute",
                "SELECT pk FROM test_ks.test_table;",
            ])
            .output()
            .expect("cqlsh failed");

        let stdout = String::from_utf8_lossy(&cql_output.stdout);
        let stderr = String::from_utf8_lossy(&cql_output.stderr);
        for key in &["a", "b", "c", "d"] {
            assert!(
                stdout.contains(key),
                "Cassandra missing partition key '{key}'.\nstdout: {stdout}\nstderr: {stderr}"
            );
        }

        // Cleanup.
        let _ = Command::new(container_runtime())
            .args([
                "compose",
                "-f",
                compose_file.to_str().unwrap(),
                "down",
                "-v",
            ])
            .status();
    }

