    /// DROP TABLE cascade (forge t_ae06e925): `unregister_table` — the engine
    /// entry point every DDL route (Direct, pair, cluster/Raft) funnels
    /// through — must tombstone every live `system_schema.indexes` row
    /// registered on the dropped table — mixed kinds included — while leaving
    /// other tables' registrations untouched, and must drop the table's
    /// entries from the live `IndexStateTracker`.
    #[test]
    fn drop_table_index_tombstone_cascade_removes_all_rows() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        engine.register_system_tables().unwrap();

        persist_index_row(
            &engine,
            "test_ks",
            "test_table",
            "fts_probe_idx",
            IndexType::FullText,
        );
        persist_index_row(
            &engine,
            "test_ks",
            "test_table",
            "val_btree_idx",
            IndexType::BTree,
        );
        persist_index_row(
            &engine,
            "test_ks",
            "other_table",
            "survivor_idx",
            IndexType::BTree,
        );
        engine
            .index_tracker()
            .register_index("test_ks", "test_table", "fts_probe_idx");
        engine
            .index_tracker()
            .register_index("test_ks", "test_table", "val_btree_idx");
        engine
            .index_tracker()
            .register_index("test_ks", "other_table", "survivor_idx");

        assert_eq!(engine.read_persisted_indexes().unwrap().len(), 3);

        engine
            .unregister_table(&TableId::new("test_ks", "test_table"))
            .unwrap();

        let remaining = engine.read_persisted_indexes().unwrap();
        assert_eq!(
            remaining.len(),
            1,
            "only the other table's registration survives: {remaining:?}"
        );
        assert_eq!(remaining[0].index_name, "survivor_idx");

        // Live in-memory tracker state for the dropped table is gone too.
        assert!(
            !engine
                .index_tracker()
                .remove_index("test_ks", "test_table", "fts_probe_idx"),
            "tracker entry for the dropped table's index must already be removed"
        );
        assert!(
            engine
                .index_tracker()
                .remove_index("test_ks", "other_table", "survivor_idx"),
            "tracker entry for the surviving table must be untouched"
        );

        // Idempotent: a direct second cascade finds nothing live.
        assert_eq!(
            engine
                .write_index_tombstones_for_table("test_ks", "test_table")
                .unwrap(),
            0
        );
    }

    /// Reload observability (forge t_ae06e925): rows that cannot be resolved
    /// (orphaned registrations from a pre-fix DROP TABLE) are *counted* — one
    /// summary warn + a metric instead of a per-orphan warn — and the cascade
    /// clears them so the next reload reports zero skipped.
    #[test]
    fn reload_counts_skipped_orphan_rows_and_cascade_clears_them() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        engine.register_system_tables().unwrap();

        // One resolvable index on the registered table, two orphans on a
        // table that no longer exists (simulating pre-fix DROP TABLE debris).
        persist_index_row(
            &engine,
            "test_ks",
            "test_table",
            "val_idx",
            IndexType::BTree,
        );
        persist_index_row(
            &engine,
            "ghost_ks",
            "ghost_table",
            "fts_probe_1",
            IndexType::FullText,
        );
        persist_index_row(
            &engine,
            "ghost_ks",
            "ghost_table",
            "fts_probe_2",
            IndexType::FullText,
        );

        let metric_before = crate::metrics::index_reload_skipped_rows_total();
        let outcome = engine
            .reload_indexes_from_system_schema(&PartitionKeyColumns::new())
            .unwrap();
        assert_eq!(outcome.restored, 1, "the resolvable index is restored");
        assert_eq!(
            outcome.skipped, 2,
            "both orphaned registrations are counted as skipped"
        );
        assert!(
            crate::metrics::index_reload_skipped_rows_total() >= metric_before + 2,
            "the skipped-rows metric must expose orphan debris"
        );

        // The DROP TABLE cascade clears the orphans; the next reload is clean.
        assert_eq!(
            engine
                .write_index_tombstones_for_table("ghost_ks", "ghost_table")
                .unwrap(),
            2
        );
        let outcome = engine
            .reload_indexes_from_system_schema(&PartitionKeyColumns::new())
            .unwrap();
        assert_eq!(outcome.skipped, 0, "no orphans remain after the cascade");
        assert_eq!(outcome.restored, 1);
    }

    /// The live fmem-dev scenario end-to-end (forge t_ae06e925): CREATE
    /// indexes → DROP TABLE → engine restart. The reload after the restart
    /// must report zero skipped rows (before the cascade, every registration
    /// survived as an orphan and warned on every boot) — proving the cascade
    /// tombstones are durable through commit-log replay, not memtable-only.
    #[test]
    fn reload_after_drop_table_and_restart_reports_zero_skipped() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        {
            let config = StorageEngineConfig::test_config(dir.path());
            let engine = StorageEngine::new(config, None).unwrap();
            engine.register_table(test_schema()).unwrap();
            engine.register_system_tables().unwrap();

            persist_index_row(
                &engine,
                "test_ks",
                "test_table",
                "fts_probe_1",
                IndexType::FullText,
            );
            persist_index_row(
                &engine,
                "test_ks",
                "test_table",
                "fts_probe_2",
                IndexType::FullText,
            );
            std::thread::sleep(std::time::Duration::from_millis(2));

            // DROP TABLE via the engine choke point every DDL route uses.
            engine
                .unregister_table(&TableId::new("test_ks", "test_table"))
                .unwrap();
            // No flush of system_schema.indexes: the tombstones must survive
            // the restart via commit-log replay.
        }

        let config = StorageEngineConfig::test_config(dir.path());
        let (engine, pending) = StorageEngine::open(config, None).unwrap();
        engine.register_system_tables().unwrap();
        // Replay the pending commit-log mutations (the registration AND the
        // cascade tombstones). Without this replay the reopened store is empty
        // and `skipped == 0` holds VACUOUSLY — the pre-fix engine (registration
        // surviving, no tombstone) would pass too. With replay, a missing
        // cascade leaves an orphaned live row and `skipped` counts it (the
        // sibling `reload_counts_skipped_orphan_rows_...` test proves the
        // counter detects exactly that shape).
        assert!(
            !pending.is_empty(),
            "expected pending commit-log mutations to replay; an empty replay \
             set would make this test vacuous"
        );
        engine.replay_mutations(pending).unwrap();

        let outcome = engine
            .reload_indexes_from_system_schema(&PartitionKeyColumns::new())
            .unwrap();
        assert_eq!(
            outcome.skipped, 0,
            "no orphaned registrations may survive DROP TABLE + restart"
        );
        assert_eq!(outcome.restored, 0);
        assert!(
            engine.read_persisted_indexes().unwrap().is_empty(),
            "system_schema.indexes must hold no live rows for the dropped table"
        );
    }

    /// The conservative guard's storage-side predicate.
    ///
    /// `FerrosStateMachine::table_has_local_artifacts` is what refuses an
    /// ambiguous snapshot absence (a table in local state, absent from the
    /// incoming snapshot, with no explicit identity-matching drop marker). It
    /// delegates entirely to the three engine queries asserted here, so this
    /// test pins the contract the guard depends on: each signal must be TRUE
    /// for a table that holds durable data, and FALSE once it is genuinely
    /// gone.
    ///
    /// Both directions matter. If this predicate ever answers `false` for a
    /// data-bearing table, the guard silently stops protecting it and the
    /// snapshot-drop cascade deletes live SSTables and index registrations —
    /// the exact P0. If it answers `true` for an absent table, the guard
    /// deadlocks a real drop.
    ///
    /// Non-vacuous by construction: the second half drives the real
    /// `unregister_table` (the destructive path guarded against) and asserts
    /// the predicate flips, so a predicate that always returned `true` fails
    /// here.
    #[test]
    fn table_has_local_artifacts_predicate_tracks_durable_state() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let table_id = TableId::new("test_ks", "test_table");
        let table_dir = dir.path().join("sstables").join(table_id.to_string());

        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        engine.register_system_tables().unwrap();
        persist_index_row(
            &engine,
            "test_ks",
            "test_table",
            "val_idx",
            IndexType::BTree,
        );
        engine
            .add_index(&table_id, "val_idx", 0, IndexType::BTree)
            .unwrap();
        engine
            .write(&table_id, &make_key("pk"), make_row(b"indexed", 1000), 1000)
            .unwrap();
        engine.flush(&table_id).unwrap();
        engine
            .flush(&TableId::new("system_schema", "indexes"))
            .unwrap();

        // --- direction 1: a live, data-bearing table must be seen as durable
        // so the Raft guard refuses ambiguous absence instead of unregistering.
        assert!(
            engine.sstable_count(&table_id) > 0,
            "guard signal: a flushed table must report live SSTables"
        );
        assert!(
            !StorageEngine::list_generations_in_dir(&engine.table_sstable_dir(&table_id))
                .is_empty(),
            "guard signal: the on-disk generation list must be non-empty \
             (survives a restart where in-memory state is rebuilt)"
        );
        assert!(
            engine
                .read_persisted_indexes()
                .unwrap()
                .iter()
                .any(|row| row.keyspace_name == "test_ks"
                    && row.table_name == "test_table"
                    && row.index_name == "val_idx"),
            "guard signal: the persisted index registration must be present"
        );

        // --- direction 2: after a REAL drop the same signals must clear, or
        // the guard would refuse every legitimate DROP TABLE forever.
        engine.unregister_table(&table_id).unwrap();

        assert_eq!(
            engine.sstable_count(&table_id),
            0,
            "after a real drop the guard must no longer see live SSTables"
        );
        assert!(
            !table_dir.exists(),
            "after a real drop the SSTable directory is gone"
        );
        assert!(
            engine
                .read_persisted_indexes()
                .unwrap()
                .iter()
                .all(|row| row.keyspace_name != "test_ks" || row.table_name != "test_table"),
            "after a real drop no persisted index registration for the table may remain"
        );
    }

    #[test]
    fn snapshot_explicit_drop_cascades_indexes_and_sstables() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let table_id = TableId::new("test_ks", "test_table");
        let table_dir = dir.path().join("sstables").join(table_id.to_string());

        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        engine.register_system_tables().unwrap();
        persist_index_row(
            &engine,
            "test_ks",
            "test_table",
            "val_idx",
            IndexType::BTree,
        );
        engine
            .add_index(&table_id, "val_idx", 0, IndexType::BTree)
            .unwrap();
        engine
            .write(&table_id, &make_key("pk"), make_row(b"indexed", 1000), 1000)
            .unwrap();
        engine.flush(&table_id).unwrap();

        assert!(table_dir.exists(), "precondition: table SSTable dir exists");
        assert_eq!(
            engine
                .read_persisted_indexes()
                .unwrap()
                .iter()
                .filter(|row| row.keyspace_name == "test_ks" && row.table_name == "test_table")
                .count(),
            1,
            "precondition: persisted index row exists"
        );

        engine.unregister_table(&table_id).unwrap();

        assert!(
            !table_dir.exists(),
            "a real explicit drop must remove the old table SSTable directory"
        );
        assert!(
            engine
                .read_persisted_indexes()
                .unwrap()
                .iter()
                .all(|row| row.keyspace_name != "test_ks" || row.table_name != "test_table"),
            "a real explicit drop must tombstone the table's system_schema.indexes rows"
        );
        assert!(
            !engine.declares_index(&table_id, "val_idx"),
            "a real explicit drop must remove live declared/registered index state"
        );
    }

    #[test]
    fn restart_after_ambiguous_snapshot_preserves_declared_persisted_registered_index_sets() {
        use ferrosa_index::IndexType;
        use std::collections::BTreeSet;

        let dir = tempfile::tempdir().unwrap();
        let table_id = TableId::new("test_ks", "test_table");
        let schema_declared: BTreeSet<String> = ["val_idx".to_string()].into_iter().collect();

        {
            let config = StorageEngineConfig::test_config(dir.path());
            let engine = StorageEngine::new(config, None).unwrap();
            engine.register_table(test_schema()).unwrap();
            engine.register_system_tables().unwrap();
            persist_index_row(
                &engine,
                "test_ks",
                "test_table",
                "val_idx",
                IndexType::BTree,
            );
            engine
                .add_index(&table_id, "val_idx", 0, IndexType::BTree)
                .unwrap();
            engine
                .write(&table_id, &make_key("pk"), make_row(b"indexed", 1000), 1000)
                .unwrap();
            engine.flush(&table_id).unwrap();
            engine
                .flush(&TableId::new("system_schema", "indexes"))
                .unwrap();
        }

        let config = StorageEngineConfig::test_config(dir.path());
        let (engine, pending) = StorageEngine::open(config, None).unwrap();
        engine.register_system_tables().unwrap();
        engine.replay_mutations(pending).unwrap();
        let outcome = engine
            .reload_indexes_from_system_schema(&PartitionKeyColumns::new())
            .unwrap();

        let persisted: BTreeSet<String> = engine
            .read_persisted_indexes()
            .unwrap()
            .into_iter()
            .filter(|row| row.keyspace_name == "test_ks" && row.table_name == "test_table")
            .map(|row| row.index_name)
            .collect();
        let declared_by_engine: BTreeSet<String> = schema_declared
            .iter()
            .filter(|name| engine.declares_index(&table_id, name))
            .cloned()
            .collect();

        assert_eq!(
            persisted, schema_declared,
            "persisted system_schema.indexes rows must match schema-declared indexes"
        );
        assert_eq!(
            declared_by_engine, schema_declared,
            "engine-declared/registered indexes must match schema-declared indexes"
        );
        assert_eq!(
            outcome.restored,
            schema_declared.len(),
            "reload outcome must prove persisted index rows were restored, not silently empty"
        );
        assert_eq!(outcome.skipped, 0);
    }

    #[test]
    fn restart_after_real_drop_has_no_orphaned_index_rows() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let table_id = TableId::new("test_ks", "test_table");
        {
            let config = StorageEngineConfig::test_config(dir.path());
            let engine = StorageEngine::new(config, None).unwrap();
            engine.register_table(test_schema()).unwrap();
            engine.register_system_tables().unwrap();
            persist_index_row(
                &engine,
                "test_ks",
                "test_table",
                "val_idx",
                IndexType::BTree,
            );
            engine
                .add_index(&table_id, "val_idx", 0, IndexType::BTree)
                .unwrap();
            engine.unregister_table(&table_id).unwrap();
        }

        let config = StorageEngineConfig::test_config(dir.path());
        let (engine, pending) = StorageEngine::open(config, None).unwrap();
        engine.register_system_tables().unwrap();
        assert!(
            !pending.is_empty(),
            "test must replay both index registration and explicit-drop tombstone mutations"
        );
        engine.replay_mutations(pending).unwrap();
        let outcome = engine
            .reload_indexes_from_system_schema(&PartitionKeyColumns::new())
            .unwrap();

        assert_eq!(outcome.skipped, 0);
        assert_eq!(outcome.restored, 0);
        assert!(
            engine
                .read_persisted_indexes()
                .unwrap()
                .iter()
                .all(|row| row.keyspace_name != "test_ks" || row.table_name != "test_table"),
            "real drop must leave no orphaned persisted index rows after restart"
        );
        assert!(
            !engine.declares_index(&table_id, "val_idx"),
            "real drop must leave no registered index declaration after restart"
        );
    }

    /// Recreate edge (forge t_ae06e925): after the DROP TABLE cascade
    /// tombstones a registration, re-persisting a same-named registration
    /// with fresh timestamps must be live — the older tombstone cannot shadow
    /// the new row (row-deletion suppression keeps cells with
    /// `timestamp >= marked_for_delete_at`).
    #[test]
    fn recreated_same_named_index_after_cascade_is_live() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_table(test_schema()).unwrap();
        engine.register_system_tables().unwrap();

        persist_index_row(
            &engine,
            "test_ks",
            "test_table",
            "val_idx",
            IndexType::BTree,
        );
        assert_eq!(
            engine
                .write_index_tombstones_for_table("test_ks", "test_table")
                .unwrap(),
            1
        );
        assert!(engine.read_persisted_indexes().unwrap().is_empty());

        // Fresh registration strictly after the tombstone's wall-clock stamp.
        std::thread::sleep(std::time::Duration::from_millis(2));
        persist_index_row(
            &engine,
            "test_ks",
            "test_table",
            "val_idx",
            IndexType::Phonetic,
        );

        let rows = engine.read_persisted_indexes().unwrap();
        assert_eq!(
            rows.len(),
            1,
            "recreated same-named registration must be live: {rows:?}"
        );
        assert_eq!(rows[0].index_name, "val_idx");
        assert_eq!(
            rows[0].kind, "phonetic",
            "the NEW registration's kind wins, not the pre-drop one"
        );
    }

    /// Regression guard for the compaction eager-index re-typing bug: the
    /// post-flush AND post-compaction eager rebuild both construct their
    /// `IndexBuildJob` via [`eager_index_build_job`], which must carry the
    /// index's *real* type read from the store — not a hardcoded `BTree`.
    ///
    /// The compaction site (engine.rs `poll_compactions`) previously stamped
    /// every rebuild job `index_type: IndexType::BTree`, so a Phonetic index
    /// got a BTree-typed rebuild after compaction and dispatched to the wrong
    /// builder. This asserts the shared helper both sites now call preserves
    /// the Phonetic type, and that an unknown index name still defaults to
    /// BTree (matching `index_type_for`).
    #[test]
    fn eager_index_build_job_carries_real_index_type_after_compaction() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let table_id = TableId::new("test_ks", "test_table");
        let table_dir = dir.path().join("sstables").join(table_id.to_string());
        std::fs::create_dir_all(&table_dir).unwrap();

        let schema = test_schema();
        let store = TableStore::new(
            schema.clone(),
            FileFlushTarget::new_starting_at(table_dir).unwrap(),
            write_options_for_schema(&schema, true).unwrap(),
        );
        // Register a non-BTree (Phonetic) index on column 0, exactly as the DDL
        // path does, so the store can report its real type.
        let _rotation: FlushOutcome = store
            .add_index("val_phonetic_idx".to_string(), 0, IndexType::Phonetic)
            .unwrap();

        // The eager helper now RESOLVES the target SSTable's header (fail-closed
        // ordinal contract), so the job must reference a real, readable SSTable
        // — exactly like the production call sites, which run after the flush /
        // compaction swap has installed the output in the view. Flush one row
        // to create it.
        store
            .write(&make_key("eager-type-pk"), make_row(b"v", 1000))
            .unwrap();
        store.flush().unwrap();
        let sstable_id = store
            .sstable_generation_ids()
            .pop()
            .expect("flush must install one SSTable generation");

        // Mirror the compaction eager-rebuild call: output SSTable id + col pos.
        let job = eager_index_build_job(
            &store,
            &table_id,
            sstable_id.clone(),
            "val_phonetic_idx",
            0,
            None,
            None,
        )
        .expect("eager job must resolve for a readable in-view SSTable");
        assert_eq!(
            job.index_type,
            IndexType::Phonetic,
            "compaction rebuild job must carry the real Phonetic type, not a hardcoded BTree"
        );
        assert_eq!(job.sstable_id, sstable_id);
        assert_eq!(job.index_name, "val_phonetic_idx");
        assert_eq!(job.table, ("test_ks".to_string(), "test_table".to_string()));

        // Control: an index name the store does not know still defaults to
        // BTree (so the fix does not over-reach and break the common path).
        let btree_job = eager_index_build_job(
            &store,
            &table_id,
            sstable_id.clone(),
            "unknown_idx",
            0,
            None,
            None,
        )
        .expect("eager job must resolve for a readable in-view SSTable");
        assert_eq!(
            btree_job.index_type,
            IndexType::BTree,
            "an unregistered index defaults to BTree, matching index_type_for"
        );
    }

    /// A schema shaped like the live `agent_memory.mentioned_in` edge table:
    /// three regular columns sorted by name, so the indexed `session_id` and
    /// `tenant_id` sit at ordinals 1 and 2. Column types are text/int so
    /// `make_key`/`make_row` rows validate; the ordinals are what matter here.
    fn edge_table_schema() -> TableSchema {
        let utf8 = "org.apache.cassandra.db.marshal.UTF8Type";
        let col = |name: &str, type_name: &str| ColumnDefinition {
            name: name.to_string(),
            type_name: type_name.to_string(),
        };
        TableSchema {
            keyspace: "agent_memory".to_string(),
            table: "mentioned_in".to_string(),
            key_type: utf8.to_string(),
            clustering_columns: vec![col("fold_id", "org.apache.cassandra.db.marshal.Int32Type")],
            static_columns: vec![],
            regular_columns: vec![
                col("created_at", utf8),
                col("session_id", utf8),
                col("tenant_id", utf8),
            ],
            extensions: Default::default(),
        }
    }

    /// ST-43 (live: every `agent_memory` edge table, 2026-09-30): flushing a
    /// table with NOTHING in its memtable published no SSTable, yet the eager
    /// index build ran against `last_flush_generation()` — 0 for a table this
    /// process has not flushed, e.g. after its SSTables were evicted. Each
    /// index then marked a PHANTOM SSTable "0" pending and logged
    /// "cannot resolve ordinal layout" because "0" is not in the live view.
    #[test]
    fn empty_flush_queues_no_eager_index_build_for_a_phantom_sstable() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let engine =
            StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        let schema = edge_table_schema();
        let table_id = TableId::new(&schema.keyspace, &schema.table);
        engine.register_table(schema).unwrap();
        engine
            .add_index(
                &table_id,
                "idx_mentioned_in_by_session",
                1,
                IndexType::BTree,
            )
            .unwrap();
        engine
            .add_index(&table_id, "idx_mentioned_in_by_tenant", 2, IndexType::BTree)
            .unwrap();

        engine.flush(&table_id).unwrap();

        for index_name in ["idx_mentioned_in_by_session", "idx_mentioned_in_by_tenant"] {
            let (indexed, pending) =
                engine
                    .index_tracker()
                    .get_coverage("agent_memory", "mentioned_in", index_name);
            assert!(
                pending.is_empty() && indexed.is_empty(),
                "{index_name}: a flush that wrote no SSTable must not touch the index \
                 tracker; indexed={indexed:?} pending={pending:?}"
            );
            assert!(
                engine
                    .index_tracker()
                    .is_current("agent_memory", "mentioned_in", index_name),
                "{index_name}: index must stay Current after a no-op flush"
            );
        }
    }

    /// Control for ST-43: a flush that DOES publish an SSTable still reaches
    /// the eager index path, and records the real generation, not a stale one.
    #[test]
    fn publishing_flush_still_tracks_its_sstable_for_each_index() {
        use ferrosa_index::IndexType;

        let dir = tempfile::tempdir().unwrap();
        let engine =
            StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        let schema = edge_table_schema();
        let table_id = TableId::new(&schema.keyspace, &schema.table);
        engine.register_table(schema).unwrap();
        engine
            .add_index(&table_id, "idx_mentioned_in_by_tenant", 2, IndexType::BTree)
            .unwrap();
        engine
            .write(&table_id, &make_key("pk"), make_row(b"v", 1000), 1000)
            .unwrap();

        engine.flush(&table_id).unwrap();

        let (indexed, pending) = engine.index_tracker().get_coverage(
            "agent_memory",
            "mentioned_in",
            "idx_mentioned_in_by_tenant",
        );
        let tracked: HashSet<String> = indexed.union(&pending).cloned().collect();
        assert_eq!(
            tracked.len(),
            1,
            "exactly the one flushed SSTable must be tracked: {tracked:?}"
        );
        assert!(
            !tracked.contains("0"),
            "the tracked id must be the real flush generation: {tracked:?}"
        );
    }

    /// A Filtered (partial) index — its `FilterPredicate` persisted under the
    /// reserved `__filter_predicate` options key — must survive an engine
    /// restart. After `reload_indexes_from_system_schema`, the index is
    /// re-registered as Filtered, its predicate is restored exactly, and the
    /// memtable index still filters: a write whose filter cell fails the
    /// predicate is excluded from the index even though it is in the table.
    #[test]
    fn reopen_restores_filtered_index_predicate_and_still_filters() {
        use ferrosa_common::schema::{ColumnDefinition, TableSchema};
        use ferrosa_index::{FilterOp, FilterPredicate, IndexType};
        use ferrosa_schema::system::persistence;

        let dir = tempfile::tempdir().unwrap();
        let user_tid = TableId::new("test_ks", "filtered_table");
        let indexes_tid = TableId::new("system_schema", "indexes");

        // name (storage col) indexed; status (storage col) is the filter column.
        let user_schema = TableSchema {
            keyspace: "test_ks".to_string(),
            table: "filtered_table".to_string(),
            key_type: "org.apache.cassandra.db.marshal.UTF8Type".to_string(),
            clustering_columns: vec![],
            static_columns: vec![],
            regular_columns: vec![
                ColumnDefinition {
                    name: "name".to_string(),
                    type_name: "org.apache.cassandra.db.marshal.UTF8Type".to_string(),
                },
                ColumnDefinition {
                    name: "status".to_string(),
                    type_name: "org.apache.cassandra.db.marshal.UTF8Type".to_string(),
                },
            ],
            extensions: Default::default(),
        };
        // Storage ordinal of the filter column `status`: regular columns are
        // stored name-sorted with no statics here, so `name`=0, `status`=1.
        let mut regular_names: Vec<&str> = user_schema
            .regular_columns
            .iter()
            .map(|c| c.name.as_str())
            .collect();
        regular_names.sort_unstable();
        let status_pos = regular_names
            .iter()
            .position(|n| *n == "status")
            .expect("status column present");

        let predicate = FilterPredicate::single(status_pos, FilterOp::Eq, b"active".to_vec());
        let mut options = std::collections::HashMap::new();
        options.insert(
            FILTER_PREDICATE_OPTION_KEY.to_string(),
            predicate.to_option_string().unwrap(),
        );
        let idx_meta = ferrosa_schema::metadata::index::IndexMetadata {
            keyspace: "test_ks".to_string(),
            table: "filtered_table".to_string(),
            name: "name_active_idx".to_string(),
            index_type: IndexType::Filtered,
            target_columns: vec!["name".to_string()],
            filter_predicate: Some(predicate.clone()),
            options,
        };

        {
            let config = StorageEngineConfig::test_config(dir.path());
            let engine = StorageEngine::new(config, None).unwrap();
            engine.register_table(user_schema.clone()).unwrap();
            engine.register_system_tables().unwrap();

            let row = persistence::index_to_rows(&idx_meta);
            engine
                .write(&indexes_tid, &row.key, row.row, now_micros_for_test())
                .unwrap();

            engine.flush(&user_tid).unwrap();
            engine.flush(&indexes_tid).unwrap();
        }

        let config = StorageEngineConfig::test_config(dir.path());
        let (engine, _pending) = StorageEngine::open(config, None).unwrap();
        engine.register_system_tables().unwrap();

        let outcome = engine
            .reload_indexes_from_system_schema(&PartitionKeyColumns::new())
            .unwrap();
        assert_eq!(outcome.restored, 1, "the filtered index should be restored");

        assert_eq!(
            engine.index_type_for_test(&user_tid, "name_active_idx"),
            Some(IndexType::Filtered),
            "index must survive restart as Filtered"
        );
        assert_eq!(
            engine.filter_predicate_for_test(&user_tid, "name_active_idx"),
            Some(predicate),
            "the partial predicate must survive restart exactly"
        );

        // The reloaded index still filters live writes: alice/active is indexed,
        // alice/inactive is not.
        let storage_to_cell = |name: &str, status: &str, ts: i64| Row {
            clustering: vec![],
            cells: vec![
                (0, CellValue::live(name.as_bytes().to_vec(), ts)),
                (1, CellValue::live(status.as_bytes().to_vec(), ts)),
            ],
            deletion: DeletionTime::LIVE,
            primary_key_liveness: LivenessInfo::with_timestamp(ts),
        };
        engine
            .write(
                &user_tid,
                &make_key("pk-active"),
                storage_to_cell("alice", "active", 1000),
                1000,
            )
            .unwrap();
        engine
            .write(
                &user_tid,
                &make_key("pk-inactive"),
                storage_to_cell("alice", "inactive", 1001),
                1001,
            )
            .unwrap();

        let hits = collect_index_results(
            &engine,
            &user_tid,
            "name_active_idx",
            &ferrosa_index::IndexKey(b"alice".to_vec()),
        )
        .unwrap();
        let pks: Vec<Vec<u8>> = hits.iter().map(|p| p.key.key.as_bytes().to_vec()).collect();
        assert_eq!(
            pks,
            vec![b"pk-active".to_vec()],
            "reloaded filtered index must return only the active row, not the inactive one"
        );
    }

    fn now_micros_for_test() -> i64 {
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_micros() as i64
    }

    /// A persisted `system_schema.types` row survives a flush + reopen and
    /// `read_persisted_types` decodes it back into the original UDT fields,
    /// including a nested collection field type (lossless serde round-trip).
    #[test]
    fn read_persisted_types_round_trips_through_storage() {
        use ferrosa_common::CqlType;
        use ferrosa_schema::metadata::user_type::UserTypeMetadata;
        use ferrosa_schema::system::persistence;

        let dir = tempfile::tempdir().unwrap();
        let types_tid = TableId::new("system_schema", "types");
        let udt = UserTypeMetadata {
            keyspace: "app".to_string(),
            name: "address".to_string(),
            fields: vec![
                ("street".to_string(), CqlType::Varchar),
                ("zip".to_string(), CqlType::Int),
                (
                    "tags".to_string(),
                    CqlType::List(Box::new(CqlType::Varchar)),
                ),
            ],
        };

        {
            let config = StorageEngineConfig::test_config(dir.path());
            let engine = StorageEngine::new(config, None).unwrap();
            engine.register_system_tables().unwrap();

            // Persist the type row exactly as the DDL write path does.
            let row = persistence::type_to_row(&udt);
            engine
                .write(&types_tid, &row.key, row.row, now_micros_for_test())
                .unwrap();
            engine.flush(&types_tid).unwrap();
        }

        // Reopen and read from storage (SSTable, not memtable).
        let config = StorageEngineConfig::test_config(dir.path());
        let (engine, _pending) = StorageEngine::open(config, None).unwrap();
        engine.register_system_tables().unwrap();

        let stored = engine.read_persisted_types().unwrap();
        assert_eq!(stored.len(), 1, "exactly one persisted type expected");
        let row = &stored[0];
        assert_eq!(row.keyspace_name, "app");
        assert_eq!(row.type_name, "address");
        assert_eq!(
            row.fields,
            vec![
                ("street".to_string(), CqlType::Varchar),
                ("zip".to_string(), CqlType::Int),
                (
                    "tags".to_string(),
                    CqlType::List(Box::new(CqlType::Varchar))
                ),
            ],
            "fields (incl. nested list<text>) must round-trip losslessly"
        );
    }

    /// A tombstoned `system_schema.types` row (DROP TYPE) masks the live row:
    /// `read_persisted_types` returns nothing after the tombstone is written.
    #[test]
    fn read_persisted_types_skips_tombstoned_rows() {
        use ferrosa_common::CqlType;
        use ferrosa_schema::metadata::user_type::UserTypeMetadata;
        use ferrosa_schema::system::persistence;

        let dir = tempfile::tempdir().unwrap();
        let types_tid = TableId::new("system_schema", "types");
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();
        engine.register_system_tables().unwrap();

        let udt = UserTypeMetadata {
            keyspace: "app".to_string(),
            name: "gone".to_string(),
            fields: vec![("x".to_string(), CqlType::Int)],
        };
        let row = persistence::type_to_row(&udt);
        engine
            .write(&types_tid, &row.key, row.row, now_micros_for_test())
            .unwrap();
        assert_eq!(engine.read_persisted_types().unwrap().len(), 1);

        // Tombstone the same (keyspace, type_name) via a row deletion.
        let ts = now_micros_for_test() + 1;
        let key = DecoratedKey::new(PartitionKey::new(b"app".to_vec()));
        let tombstone = Row {
            clustering: b"gone".to_vec(),
            cells: vec![],
            deletion: DeletionTime::new(ts, (ts / 1_000_000) as u32),
            primary_key_liveness: LivenessInfo::NONE,
        };
        engine.write(&types_tid, &key, tombstone, ts).unwrap();

        assert!(
            engine.read_persisted_types().unwrap().is_empty(),
            "dropped type must not appear in read_persisted_types"
        );
    }

