    #[test]
    fn a_torn_set_aside_file_is_reported_and_kept_not_skipped() {
        let dir = tempfile::tempdir().unwrap();
        let path = set_aside_test_keys(dir.path(), &["f0", "f1"]);
        let mut bytes = std::fs::read(&path).unwrap();
        bytes.truncate(bytes.len() - 3);
        std::fs::write(&path, &bytes).unwrap();

        let engine =
            StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        engine.register_table(test_schema()).unwrap();

        assert_eq!(
            std::fs::read(&path).unwrap(),
            bytes,
            "file kept for the operator"
        );
        let status = engine.replay_set_aside_status();
        let unreadable = status.unreadable();
        assert_eq!(unreadable.len(), 1, "the torn file is named");
        assert!(unreadable[0]
            .error
            .as_deref()
            .unwrap()
            .contains("torn frame"));
    }

    /// Writes `n` unflushed rows to a table that is then dropped, leaving its
    /// mutations in the commit log while the persisted schema holds only the
    /// surviving table. Returns the data dir holder.
    fn data_dir_with_commit_log_for_a_dropped_table(n: usize) -> tempfile::TempDir {
        let dir = tempfile::tempdir().unwrap();
        let tid = table_id();
        let dropped = TableSchema {
            table: "dropped_table".to_string(),
            ..test_schema()
        };
        let dropped_id = TableId::new(&dropped.keyspace, &dropped.table);
        let engine =
            StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        engine.register_table(test_schema()).unwrap();
        engine.register_table(dropped).unwrap();
        for i in 0..n {
            engine
                .write(
                    &dropped_id,
                    &make_key(&format!("d{i}")),
                    make_row(b"v", i as i64),
                    i as i64,
                )
                .unwrap();
        }
        engine.unregister_table(&dropped_id).unwrap();
        // A flush persists storage-schema.json, now without the dropped table.
        engine
            .write(&tid, &make_key("anchor"), make_row(b"v", 9), 9)
            .unwrap();
        engine.flush(&tid).unwrap();
        engine.commit_log.shutdown().unwrap();
        dir
    }

    /// t_f5a69b0b: mutations for a table absent from an existing schema were
    /// held in an unbounded `Vec`, so a large commit log for a dropped table
    /// could exhaust memory at startup. Past the bound they spill to the
    /// durable set-aside store, counted per table.
    #[test]
    fn replay_spills_absent_table_mutations_past_the_deferral_bound() {
        let dir = data_dir_with_commit_log_for_a_dropped_table(5);

        let (engine, _pending) = StorageEngine::open_with_deferred_limit(
            StorageEngineConfig::test_config(dir.path()),
            None,
            2,
        )
        .expect("an overfull deferral buffer must spill, not refuse to open");

        assert_eq!(
            engine.deferred_replay_mutation_count_for_test(),
            2,
            "memory stays bounded at the limit"
        );
        // `replay_set_aside_report()` became `replay_set_aside_status()`, which
        // reports every set-aside file rather than one aggregate; this spill
        // writes a single file, so that file IS the report.
        let status = engine.replay_set_aside_status();
        assert_eq!(status.files.len(), 1, "the overflow went to one file");
        let report = &status.files[0];
        assert_eq!(report.mutations, 3);
        assert_eq!(report.tables.get("test_ks.dropped_table"), Some(&3));
        let on_disk = crate::replay_set_aside::read_set_aside_file(&report.path).unwrap();
        assert_eq!(on_disk.len(), 3, "the set-aside file holds the overflow");
        assert!(on_disk.iter().all(|m| m.table == "dropped_table"));
    }

    #[test]
    fn replay_defers_absent_table_mutations_under_the_bound_as_before() {
        let dir = data_dir_with_commit_log_for_a_dropped_table(5);

        let (engine, _pending) = StorageEngine::open_with_deferred_limit(
            StorageEngineConfig::test_config(dir.path()),
            None,
            10,
        )
        .unwrap();

        assert_eq!(engine.deferred_replay_mutation_count_for_test(), 5);
        assert!(
            engine.replay_set_aside_status().is_empty(),
            "nothing is set aside while the buffer has room"
        );
    }

    #[test]
    fn deferred_replay_bound_tunable_rejects_invalid_values_naming_the_variable() {
        assert_eq!(
            parse_max_deferred_replay_mutations(None).unwrap(),
            DEFAULT_MAX_DEFERRED_REPLAY_MUTATIONS
        );
        assert_eq!(
            parse_max_deferred_replay_mutations(Some("  ")).unwrap(),
            DEFAULT_MAX_DEFERRED_REPLAY_MUTATIONS
        );
        assert_eq!(parse_max_deferred_replay_mutations(Some("64")).unwrap(), 64);
        for bad in ["0", "-1", "lots", "1.5"] {
            let err = parse_max_deferred_replay_mutations(Some(bad))
                .expect_err("an invalid bound must be rejected")
                .to_string();
            assert!(
                err.contains("FERROSA_MAX_DEFERRED_REPLAY_MUTATIONS") && err.contains(bad),
                "error must name the variable and the value, got: {err}"
            );
        }
    }

    #[test]
    fn replayed_legacy_collection_blob_does_not_panic_flush_beside_element_cells() {
        let dir = tempfile::tempdir().unwrap();
        let tid = TableId::new("test_ks", "mixed_replay");
        let list_type = "org.apache.cassandra.db.marshal.ListType(\
                         org.apache.cassandra.db.marshal.UTF8Type)";
        let live_row = |cell: CellValue, ts: i64| Row {
            clustering: vec![],
            cells: vec![(0, cell)],
            deletion: ferrosa_sstable::types::DeletionTime::LIVE,
            primary_key_liveness: ferrosa_sstable::types::LivenessInfo::with_timestamp(ts),
        };
        {
            let engine =
                StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
            engine
                .register_table(collection_schema("test_ks", "mixed_replay", list_type))
                .unwrap();
            // An old commit log: a whole-value blob in one partition...
            let blob = encode_cql_sequence(&[b"a", b"b"]);
            engine
                .write(
                    &tid,
                    &make_key("blob"),
                    live_row(CellValue::live(blob, 1_000), 1_000),
                    1_000,
                )
                .unwrap();
            // ...and a per-element cell in another, so the flush is framed complex.
            let element = CellValue::live(b"c".to_vec(), 2_000)
                .with_path(ferrosa_row_bridge::collection::list_cell_path(2_000, 0));
            engine
                .write(&tid, &make_key("elem"), live_row(element, 2_000), 2_000)
                .unwrap();
            engine.commit_log.shutdown().unwrap();
        }

        // No schema file was ever persisted, so replay is handed back to the
        // caller, exactly as `main.rs` does: register the table, then replay.
        let (engine, pending) =
            StorageEngine::open(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        assert_eq!(pending.len(), 2);
        engine
            .register_table(collection_schema("test_ks", "mixed_replay", list_type))
            .unwrap();
        engine.replay_mutations(pending).unwrap();
        engine.flush(&tid).expect(
            "replayed legacy blob must be normalised so flush cannot hit the writer assertion",
        );
        for key in ["blob", "elem"] {
            let partition = engine.read(&tid, &make_key(key)).unwrap().unwrap();
            assert!(
                partition.rows[0]
                    .cells
                    .iter()
                    .all(|(_, c)| c.path.is_some() || c.is_tombstone()),
                "{key}: no live path-less cell may survive on a complex column"
            );
        }
    }

    /// Panic A of 2026-10-03, reproduced through the LIVE write path. Any
    /// producer that hands `write` a whole-collection blob — a mixed-version
    /// peer's MutationForward, an old hint or batchlog entry, a graph write,
    /// a wire that dropped paths — stores it as a live path-less cell. One
    /// element write on another partition then frames the flush complex, and
    /// the writer refused the blob: on main that `assert!` killed
    /// `storage-flush` for good. Normalising only on replay and on a merge
    /// with an element row left this path open. The blob must be expanded
    /// before it reaches a complex-framed writer, flush must succeed, and the
    /// elements must read back.
    #[test]
    fn live_written_collection_blob_survives_a_complex_flush() {
        let dir = tempfile::tempdir().unwrap();
        let tid = TableId::new("test_ks", "mixed_live");
        let list_type = "org.apache.cassandra.db.marshal.ListType(\
                         org.apache.cassandra.db.marshal.UTF8Type)";
        let live_row = |cell: CellValue, ts: i64| Row {
            clustering: vec![],
            cells: vec![(0, cell)],
            deletion: ferrosa_sstable::types::DeletionTime::LIVE,
            primary_key_liveness: ferrosa_sstable::types::LivenessInfo::with_timestamp(ts),
        };
        let engine =
            StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        engine
            .register_table(collection_schema("test_ks", "mixed_live", list_type))
            .unwrap();
        let blob = encode_cql_sequence(&[b"a", b"b"]);
        engine
            .write(
                &tid,
                &make_key("blob"),
                live_row(CellValue::live(blob, 1_000), 1_000),
                1_000,
            )
            .unwrap();
        let element = CellValue::live(b"c".to_vec(), 2_000)
            .with_path(ferrosa_row_bridge::collection::list_cell_path(2_000, 0));
        engine
            .write(&tid, &make_key("elem"), live_row(element, 2_000), 2_000)
            .unwrap();

        engine
            .flush(&tid)
            .expect("a blob written live must be expanded before it reaches a complex writer");

        let blob_partition = engine.read(&tid, &make_key("blob")).unwrap().unwrap();
        let cells = &blob_partition.rows[0].cells;
        assert!(
            cells
                .iter()
                .all(|(_, c)| c.path.is_some() || c.is_tombstone()),
            "no live path-less cell may survive on a complex column: {cells:?}"
        );
        let values: Vec<_> = cells
            .iter()
            .filter(|(_, c)| c.path.is_some() && !c.is_tombstone())
            .map(|(_, c)| c.value.clone().unwrap())
            .collect();
        assert_eq!(
            values,
            vec![b"a".to_vec(), b"b".to_vec()],
            "elements survive"
        );
        // The rewrite is counted, never silent.
        assert_eq!(
            crate::metrics::collection_blob_expansions_total("test_ks.mixed_live"),
            1
        );
    }

    /// A value that is NOT a well-formed collection on a list column (e.g. a
    /// graph write of a plain string) must be refused at the write, loudly,
    /// rather than stored to wedge a later flush.
    #[test]
    fn malformed_collection_blob_is_refused_at_write() {
        let dir = tempfile::tempdir().unwrap();
        let tid = TableId::new("test_ks", "bad_blob");
        let list_type = "org.apache.cassandra.db.marshal.ListType(\
                         org.apache.cassandra.db.marshal.UTF8Type)";
        let engine =
            StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        engine
            .register_table(collection_schema("test_ks", "bad_blob", list_type))
            .unwrap();
        let row = Row {
            clustering: vec![],
            cells: vec![(0, CellValue::live(b"not a list".to_vec(), 1_000))],
            deletion: ferrosa_sstable::types::DeletionTime::LIVE,
            primary_key_liveness: ferrosa_sstable::types::LivenessInfo::with_timestamp(1_000),
        };
        let err = engine
            .write(&tid, &make_key("k"), row, 1_000)
            .expect_err("a malformed collection value must be refused");
        assert!(err.to_string().contains("collection"), "got: {err}");
        assert!(engine.read(&tid, &make_key("k")).unwrap().is_none());
    }

    /// Panic A's compaction form (node1, 2026-10-03): a simple-framed SSTable
    /// holding a whole-value blob, compacted with a complex-framed one, gives
    /// a complex-framed output that cannot hold the blob as-is. The executor
    /// must expand it, the compaction must swap in, and the elements must read
    /// back from the output.
    #[tokio::test]
    async fn legacy_blob_sstable_compacts_with_a_complex_sstable() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = StorageEngineConfig::test_config(dir.path());
        // Only the explicit `force_compact_all` below may compact.
        config.compaction.min_threshold = 50;
        let engine = Arc::new(StorageEngine::new(config, None).unwrap());
        let tid = TableId::new("test_ks", "mixed_compact");
        let list_type = "org.apache.cassandra.db.marshal.ListType(\
                         org.apache.cassandra.db.marshal.UTF8Type)";
        engine
            .register_table(collection_schema("test_ks", "mixed_compact", list_type))
            .unwrap();
        let live_row = |cell: CellValue, ts: i64| Row {
            clustering: vec![],
            cells: vec![(0, cell)],
            deletion: ferrosa_sstable::types::DeletionTime::LIVE,
            primary_key_liveness: ferrosa_sstable::types::LivenessInfo::with_timestamp(ts),
        };
        // A blob alone flushes simple-framed (no cell has a path)...
        let blob = encode_cql_sequence(&[b"a", b"b"]);
        engine
            .write(
                &tid,
                &make_key("blob"),
                live_row(CellValue::live(blob, 1_000), 1_000),
                1_000,
            )
            .unwrap();
        engine.flush(&tid).unwrap();
        // ...an element alone flushes complex-framed.
        let element = CellValue::live(b"c".to_vec(), 2_000)
            .with_path(ferrosa_row_bridge::collection::list_cell_path(2_000, 0));
        engine
            .write(&tid, &make_key("elem"), live_row(element, 2_000), 2_000)
            .unwrap();
        engine.flush(&tid).unwrap();
        assert_eq!(engine.sstable_count(&tid), 2);

        engine.force_compact_all();
        let mut polls = 0;
        while engine.sstable_count(&tid) != 1 {
            assert!(polls < 1500, "compaction never swapped in");
            engine.poll_compactions().await;
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
            polls += 1;
        }

        let cells = engine.read(&tid, &make_key("blob")).unwrap().unwrap().rows[0]
            .cells
            .clone();
        let values: Vec<_> = cells
            .iter()
            .filter(|(_, c)| c.path.is_some() && !c.is_tombstone())
            .map(|(_, c)| c.value.clone().unwrap())
            .collect();
        assert_eq!(values, vec![b"a".to_vec(), b"b".to_vec()], "{cells:?}");
        // The sentinel sits one microsecond below the blob, under the inputs'
        // minimum timestamp; it must survive the delta encoding exactly.
        assert!(
            cells
                .iter()
                .any(|(_, c)| c.path.is_none() && c.is_tombstone() && c.timestamp == 999),
            "collection-deletion sentinel at ts 999 expected: {cells:?}"
        );
        assert_eq!(
            crate::metrics::collection_blob_expansions_total("test_ks.mixed_compact"),
            1,
            "the compaction's rewrite of the legacy blob must be counted"
        );
    }

    /// Bytes that FRAME as a collection but whose elements cannot be values of
    /// the declared element type are not a whole-value collection (for example
    /// a path-dropped element). They must be refused, never expanded: a 3-byte
    /// element in a `list<int>`, a non-UTF-8 element in a `set<text>`.
    #[test]
    fn implausible_collection_elements_are_refused_not_expanded() {
        let dir = tempfile::tempdir().unwrap();
        let engine =
            StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        let cases: [(&str, &str, Vec<u8>); 3] = [
            (
                "bad_int_list",
                "org.apache.cassandra.db.marshal.ListType(org.apache.cassandra.db.marshal.Int32Type)",
                encode_cql_sequence(&[&[0, 0, 1]]),
            ),
            (
                "bad_text_set",
                "org.apache.cassandra.db.marshal.SetType(org.apache.cassandra.db.marshal.UTF8Type)",
                encode_cql_sequence(&[&[0xff, 0xfe]]),
            ),
            (
                "bad_map_value",
                "org.apache.cassandra.db.marshal.MapType(org.apache.cassandra.db.marshal.UTF8Type,\
                 org.apache.cassandra.db.marshal.Int32Type)",
                encode_cql_map(&[(b"k", &[1, 2])]),
            ),
        ];
        for (table, col_type, blob) in cases {
            engine
                .register_table(collection_schema("test_ks", table, col_type))
                .unwrap();
            let tid = TableId::new("test_ks", table);
            let row = Row {
                clustering: vec![],
                cells: vec![(0, CellValue::live(blob, 1_000))],
                deletion: ferrosa_sstable::types::DeletionTime::LIVE,
                primary_key_liveness: ferrosa_sstable::types::LivenessInfo::with_timestamp(1_000),
            };
            let err = engine
                .write(&tid, &make_key("k"), row, 1_000)
                .expect_err("an implausible element must be refused");
            assert!(
                err.to_string().contains("element") || err.to_string().contains("value"),
                "{table}: {err}"
            );
            assert!(
                engine.read(&tid, &make_key("k")).unwrap().is_none(),
                "{table}"
            );
        }
    }

    /// Restart safety for node2 (2026-10-03): its unflushed commit log holds
    /// `agent_memory.tasks` writes in BOTH collection shapes for the same
    /// `set<text>` column — whole values from builds before e513bc60 beside
    /// element cells from later builds, in separate partitions and in the same
    /// row. Replay then flush must succeed, and every partition must assemble
    /// to exactly the collection a reader expects.
    #[test]
    fn replayed_mixed_collection_shapes_flush_and_read_back() {
        use ferrosa_common::{CqlType, CqlValue};
        let dir = tempfile::tempdir().unwrap();
        let tid = TableId::new("test_ks", "tasks_like");
        let set_type = "org.apache.cassandra.db.marshal.SetType(\
                        org.apache.cassandra.db.marshal.UTF8Type)";
        let schema = || TableSchema {
            keyspace: "test_ks".to_string(),
            table: "tasks_like".to_string(),
            key_type: "org.apache.cassandra.db.marshal.UTF8Type".to_string(),
            clustering_columns: vec![],
            static_columns: vec![],
            regular_columns: vec![
                ColumnDefinition {
                    name: "related_entity_ids".to_string(),
                    type_name: set_type.to_string(),
                },
                ColumnDefinition {
                    name: "title".to_string(),
                    type_name: "org.apache.cassandra.db.marshal.UTF8Type".to_string(),
                },
            ],
            extensions: Default::default(),
        };
        let row = |cells: Vec<(u16, CellValue)>, ts: i64| Row {
            clustering: vec![],
            cells,
            deletion: ferrosa_sstable::types::DeletionTime::LIVE,
            primary_key_liveness: ferrosa_sstable::types::LivenessInfo::with_timestamp(ts),
        };
        let blob = |members: &[&[u8]], ts: i64| CellValue::live(encode_cql_sequence(members), ts);
        // CQL's element shape: the deletion sentinel at ts-1, then one cell per
        // member whose path is the member and whose value is empty.
        let elements = |members: &[&[u8]], ts: i64| {
            let mut cells = vec![(0, CellValue::tombstone(ts - 1, 1_700_000_000))];
            cells.extend(
                members
                    .iter()
                    .map(|m| (0, CellValue::live(Vec::new(), ts).with_path(m.to_vec()))),
            );
            cells
        };
        let title = |t: &str, ts: i64| (1, CellValue::live(t.as_bytes().to_vec(), ts));

        {
            let engine =
                StorageEngine::new(StorageEngineConfig::test_config(dir.path()), None).unwrap();
            engine.register_table(schema()).unwrap();
            let write = |key: &str, r: Row, ts: i64| {
                engine.write(&tid, &make_key(key), r, ts).unwrap();
            };
            // Whole value only (pre-e513bc60 UPDATE).
            write(
                "blob",
                row(
                    vec![(0, blob(&[b"a", b"b"], 1_000)), title("t-blob", 1_000)],
                    1_000,
                ),
                1_000,
            );
            // Elements only (current CQL).
            let mut cells = elements(&[b"c"], 2_000);
            cells.push(title("t-elem", 2_000));
            write("elem", row(cells, 2_000), 2_000);
            // Whole value, then a later element add to the same row.
            write(
                "blob_then_elem",
                row(vec![(0, blob(&[b"x"], 1_000))], 1_000),
                1_000,
            );
            write(
                "blob_then_elem",
                row(
                    vec![(
                        0,
                        CellValue::live(Vec::new(), 2_000).with_path(b"y".to_vec()),
                    )],
                    2_000,
                ),
                2_000,
            );
            // Elements, then a later whole-value overwrite of the same row.
            write(
                "elem_then_blob",
                row(elements(&[b"p"], 1_000), 1_000),
                1_000,
            );
            write(
                "elem_then_blob",
                row(vec![(0, blob(&[b"q"], 2_000))], 2_000),
                2_000,
            );
            // Whole value of the empty set.
            write("empty_blob", row(vec![(0, blob(&[], 1_000))], 1_000), 1_000);
            engine.commit_log.shutdown().unwrap();
        }

        let (engine, pending) =
            StorageEngine::open(StorageEngineConfig::test_config(dir.path()), None).unwrap();
        engine.register_table(schema()).unwrap();
        engine.replay_mutations(pending).unwrap();
        engine
            .flush(&tid)
            .expect("replayed mixed collection shapes must flush");
        assert!(engine.sstable_count(&tid) >= 1);

        let set_of = |key: &str| -> Option<CqlValue> {
            let partition = engine.read(&tid, &make_key(key)).unwrap().unwrap();
            let cells: Vec<&CellValue> = partition.rows[0]
                .cells
                .iter()
                .filter(|(idx, _)| *idx == 0)
                .map(|(_, c)| c)
                .collect();
            ferrosa_row_bridge::collection::assemble_column_cells(
                &CqlType::Set(Box::new(CqlType::Varchar)),
                &cells,
                1_800_000_000,
            )
            .unwrap()
        };
        let text_set = |members: &[&str]| {
            Some(CqlValue::Set(
                members
                    .iter()
                    .map(|m| CqlValue::Text(m.to_string()))
                    .collect(),
            ))
        };
        assert_eq!(set_of("blob"), text_set(&["a", "b"]));
        assert_eq!(set_of("elem"), text_set(&["c"]));
        assert_eq!(set_of("blob_then_elem"), text_set(&["x", "y"]));
        assert_eq!(set_of("elem_then_blob"), text_set(&["q"]));
        // Cassandra reads an emptied collection as absent.
        assert_eq!(set_of("empty_blob"), None);
        let blob_partition = engine.read(&tid, &make_key("blob")).unwrap().unwrap();
        assert!(
            blob_partition.rows[0]
                .cells
                .iter()
                .any(|(idx, c)| *idx == 1 && c.value.as_deref() == Some(&b"t-blob"[..])),
            "the scalar beside the collection survives"
        );
        assert!(
            crate::metrics::collection_blob_expansions_total("test_ks.tasks_like") >= 4,
            "every whole value rewritten on replay is counted"
        );
    }

    #[test]
    fn schema_survives_restart() {
        let dir = tempfile::tempdir().unwrap();
        let tid = TableId::new("test_ks", "test_table");

        // First engine: register, write, flush (flush writes storage-schema.json).
        {
            let config = StorageEngineConfig::test_config(dir.path());
            let engine = StorageEngine::new(config, None).unwrap();
            engine.register_table(test_schema()).unwrap();
            let key = make_key("restart_key");
            engine
                .write(&tid, &key, make_row(b"restart_val", 1000), 1000)
                .unwrap();
            engine.flush(&tid).unwrap();
            // engine drops here — storage-schema.json is now on disk
        }

        // Second engine at the SAME directory: must NOT call register_table.
        let config2 = StorageEngineConfig::test_config(dir.path());
        let engine2 = StorageEngine::new(config2, None).unwrap();

        // Write succeeds only if the table was re-registered from local schema metadata.
        let key2 = make_key("restart_key2");
        let write_result = engine2.write(&tid, &key2, make_row(b"after_restart", 2000), 2000);
        assert!(
            write_result.is_ok(),
            "write after restart must succeed — schema must have been loaded \
             from storage-schema.json; got: {:?}",
            write_result.err()
        );

        // Data written before restart is readable too.
        let key1 = make_key("restart_key");
        let read_result = engine2.read(&tid, &key1).unwrap();
        assert!(
            read_result.is_some(),
            "row written before restart must be readable after restart"
        );
        assert_eq!(
            read_result.unwrap().rows[0].cells[0].1.value.as_deref(),
            Some(b"restart_val".as_slice()),
            "row value must be unchanged after restart"
        );
    }

    /// Like `schema_survives_restart` but explicitly confirms SSTable files
    /// are present on disk before the restart — this exercises the "non-empty
    /// data directory" code path where the old S3 bootstrap was gated.
    #[test]
    fn schema_survives_binary_upgrade() {
        let dir = tempfile::tempdir().unwrap();
        let tid = TableId::new("test_ks", "test_table");

        // First engine: register, write, flush.
        {
            let config = StorageEngineConfig::test_config(dir.path());
            let engine = StorageEngine::new(config, None).unwrap();
            engine.register_table(test_schema()).unwrap();
            let key = make_key("upgrade_key");
            engine
                .write(&tid, &key, make_row(b"upgrade_val", 5000), 5000)
                .unwrap();
            engine.flush(&tid).unwrap();
        }

        // Verify at least one .db file exists on disk before restart.
        let table_dir = dir.path().join("sstables").join(tid.to_string());
        let db_files: Vec<_> = std::fs::read_dir(&table_dir)
            .expect("sstables table dir must exist after flush")
            .filter_map(|e| e.ok())
            .filter(|e| e.path().extension().map(|x| x == "db").unwrap_or(false))
            .collect();
        assert!(
            !db_files.is_empty(),
            "at least one .db SSTable file must exist on disk before restart"
        );

        // Second engine: schema must be present without calling register_table.
        let config2 = StorageEngineConfig::test_config(dir.path());
        let engine2 = StorageEngine::new(config2, None).unwrap();

        // The pre-restart row must be readable.
        let key = make_key("upgrade_key");
        let result = engine2.read(&tid, &key).unwrap();
        assert!(
            result.is_some(),
            "row written before binary upgrade must be readable after restart"
        );
        assert_eq!(
            result.unwrap().rows[0].cells[0].1.value.as_deref(),
            Some(b"upgrade_val".as_slice()),
            "row value must survive binary upgrade restart"
        );
    }

    /// Test that a map<text,int> encoded in CQL v4+ wire format (as gocql would
    /// send it) survives the full write→flush→read cycle without any byte loss
    /// or reinterpretation.
    ///
    /// Wire format: 4B BE count, then for each entry:
    ///   4B BE key_len + key_bytes + 4B BE val_len + val_bytes.
    #[test]
    fn collection_via_gocql_roundtrip() {
        let dir = tempfile::tempdir().unwrap();
        let config = StorageEngineConfig::test_config(dir.path());
        let engine = StorageEngine::new(config, None).unwrap();

        let schema = collection_schema(
            "test_ks",
            "gocql_map_table",
            "org.apache.cassandra.db.marshal.MapType(\
             org.apache.cassandra.db.marshal.UTF8Type,\
             org.apache.cassandra.db.marshal.Int32Type)",
        );
        engine.register_table(schema).unwrap();

        let tid = TableId::new("test_ks", "gocql_map_table");
        let key = make_key("gocql_pk");

        // Encode {'hello': 42, 'world': 99} as CQL v4+ wire format.
        let map_bytes = encode_cql_map(&[
            (b"hello", &42i32.to_be_bytes()),
            (b"world", &99i32.to_be_bytes()),
        ]);

        let row = Row {
            clustering: vec![],
            cells: vec![(0, CellValue::live(map_bytes.clone(), 7000))],
            deletion: ferrosa_sstable::types::DeletionTime::LIVE,
            primary_key_liveness: ferrosa_sstable::types::LivenessInfo::with_timestamp(7000),
        };
        engine.write(&tid, &key, row, 7000).unwrap();

        engine.flush(&tid).unwrap();
        assert_eq!(
            engine.sstable_count(&tid),
            1,
            "flush should have written 1 SSTable"
        );
        assert_eq!(
            engine.memtable_size(&tid),
            0,
            "memtable should be empty after flush"
        );

        let result = engine.read(&tid, &key).unwrap();
        assert!(result.is_some(), "map row must be readable after flush");
        let partition = result.unwrap();
        assert_eq!(
            partition.rows[0].cells[0].1.value.as_deref(),
            Some(map_bytes.as_slice()),
            "gocql map bytes must survive write→flush→read unchanged"
        );
    }

    // ── C2.2: S3 upload confirmation before manifest update ──────────────────

    fn s3_sync_fixture(
        prefix: &str,
        components: &[(&str, &[u8])],
    ) -> (
        tempfile::TempDir,
        StorageEngine,
        Arc<dyn object_store::ObjectStore>,
        String,
        TableId,
    ) {
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let dir = tempfile::tempdir().unwrap();
        let prefix = prefix.to_string();
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.object_store = Some(crate::upload::ObjectStoreConfig {
            prefix: prefix.clone(),
            ..crate::upload::ObjectStoreConfig::test_config()
        });
        let engine = StorageEngine::new_with_upload_store(
            config,
            Arc::clone(&store),
            prefix.clone(),
            &tokio::runtime::Handle::current(),
        )
        .unwrap();

        engine.register_table(test_schema()).unwrap();
        let tid = table_id();
        let table_dir = engine.table_sstable_dir(&tid);
        std::fs::create_dir_all(&table_dir).unwrap();
        for (component, bytes) in components {
            std::fs::write(table_dir.join(format!("1-{component}")), bytes).unwrap();
        }

        (dir, engine, store, prefix, tid)
    }

    /// Build an S3-backed engine over `dir` whose uploaded-SSTable cache is
    /// one byte, so every sync evicts what it uploaded, exactly as disk
    /// pressure did on the live cluster.
    fn evicting_s3_engine(
        dir: &std::path::Path,
        store: &Arc<dyn object_store::ObjectStore>,
        prefix: &str,
    ) -> StorageEngine {
        evicting_s3_engine_with_hot_window(dir, store, prefix, 900)
    }

    /// [`evicting_s3_engine`] with an explicit hot window in seconds.
    fn evicting_s3_engine_with_hot_window(
        dir: &std::path::Path,
        store: &Arc<dyn object_store::ObjectStore>,
        prefix: &str,
        hot_window_secs: u64,
    ) -> StorageEngine {
        let mut config = StorageEngineConfig::test_config(dir);
        config.local_cache_max_bytes = 1;
        config.cache_hot_window_secs = hot_window_secs;
        config.object_store = Some(crate::upload::ObjectStoreConfig {
            prefix: prefix.to_string(),
            ..crate::upload::ObjectStoreConfig::test_config()
        });
        StorageEngine::new_with_upload_store(
            config,
            Arc::clone(store),
            prefix.to_string(),
            &tokio::runtime::Handle::current(),
        )
        .unwrap()
    }

    /// Two flushed tables over the cache limit; the first (`test_table`) is
    /// read by a foreground query before the sync that evicts. Returns the
    /// engine and the two tables' SSTable dirs, hot table first.
    async fn sync_two_tables_reading_the_first(
        dir: &std::path::Path,
        hot_window_secs: u64,
        prefix: &str,
    ) -> (StorageEngine, std::path::PathBuf, std::path::PathBuf) {
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let engine = evicting_s3_engine_with_hot_window(dir, &store, prefix, hot_window_secs);
        engine.register_table(test_schema()).unwrap();
        engine.register_table(test_schema_2()).unwrap();
        for tid in [table_id(), table_id_2()] {
            engine
                .write(&tid, &make_key("k"), make_row(b"v", 1000), 1000)
                .unwrap();
            engine.flush(&tid).unwrap();
        }
        engine.read(&table_id(), &make_key("k")).unwrap();
        assert!(engine.sync_sstables_to_s3().await.unwrap() >= 2);
        let hot_dir = engine.table_sstable_dir(&table_id());
        let other_dir = engine.table_sstable_dir(&table_id_2());
        (engine, hot_dir, other_dir)
    }

    /// 2026-09-29: the evictor ordered by write age, so hot, rarely-written
    /// tables (`schema_version`, `entity_store`) went first and reads failed.
    /// A table read inside the hot window keeps its SSTables local while a
    /// never-read table over the limit is evicted.
    #[tokio::test(flavor = "multi_thread")]
    async fn cache_eviction_keeps_a_recently_read_table_local_and_evicts_the_cold_one() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, hot_dir, cold_dir) =
            sync_two_tables_reading_the_first(dir.path(), 900, "test-hot-window").await;

        assert!(
            !StorageEngine::list_generations_in_dir(&hot_dir).is_empty(),
            "the table read inside the hot window must stay local"
        );
        assert!(
            StorageEngine::list_generations_in_dir(&cold_dir).is_empty(),
            "the never-read table must be evicted"
        );
        engine.shutdown().unwrap();
    }

    /// A hot window of zero disables hotness: the read table is evicted too.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_zero_hot_window_evicts_the_recently_read_table_too() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, hot_dir, cold_dir) =
            sync_two_tables_reading_the_first(dir.path(), 0, "test-hot-window-zero").await;

        assert!(StorageEngine::list_generations_in_dir(&hot_dir).is_empty());
        assert!(StorageEngine::list_generations_in_dir(&cold_dir).is_empty());
        engine.shutdown().unwrap();
    }

    /// The restore's start line reports what it will do: only marked
    /// generations the manifest lists count, grouped by table.
    #[test]
    fn restore_work_counts_marked_manifest_generations() {
        let entry = |id: &str, size: u64| crate::manifest::ManifestEntry {
            id: id.to_string(),
            size,
            min_token: i64::MIN,
            max_token: i64::MAX,
            min_timestamp: 0,
            max_timestamp: 0,
        };
        let mut manifest = crate::manifest::Manifest::new();
        manifest.add_sstable("ks.a", entry("1", 100));
        manifest.add_sstable("ks.a", entry("2", 200));
        manifest.add_sstable("ks.a", entry("3", 400)); // not marked evicted
        manifest.add_sstable("ks.b", entry("7", 1000));
        let mut evicted = std::collections::BTreeMap::new();
        evicted.insert(
            "ks.a".to_string(),
            ["1", "2"].map(String::from).into_iter().collect(),
        );
        evicted.insert(
            "ks.b".to_string(),
            ["7", "8"].map(String::from).into_iter().collect(), // 8 not in manifest
        );
        evicted.insert(
            "ks.gone".to_string(),
            ["9"].map(String::from).into_iter().collect(), // table not in manifest
        );

        assert_eq!(
            restore_work(&evicted, &manifest),
            RestoreWork {
                tables: 2,
                generations: 3,
                bytes: 1300
            }
        );
    }

    #[test]
    fn restore_progress_is_due_by_count_or_by_time() {
        use std::time::Duration;
        assert!(!restore_progress_due(Duration::from_secs(5), 3));
        assert!(restore_progress_due(Duration::from_secs(5), 25));
        assert!(restore_progress_due(Duration::from_secs(30), 1));
        assert!(!restore_progress_due(Duration::from_secs(29), 24));
    }

    /// The "hot data keeps the cache over its limit" warning reports edges,
    /// not every sync.
    #[test]
    fn hot_block_warning_fires_on_the_edges_only() {
        let flag = AtomicBool::new(false);
        assert_eq!(hot_block_edge(&flag, false), HotBlockEdge::Unchanged);
        assert_eq!(hot_block_edge(&flag, true), HotBlockEdge::Started);
        assert_eq!(hot_block_edge(&flag, true), HotBlockEdge::Unchanged);
        assert_eq!(hot_block_edge(&flag, true), HotBlockEdge::Unchanged);
        assert_eq!(hot_block_edge(&flag, false), HotBlockEdge::Cleared);
        assert_eq!(hot_block_edge(&flag, false), HotBlockEdge::Unchanged);
    }

    /// Data loss on the live ferrosa-memory cluster, 2026-09-29.
    ///
    /// Under disk pressure the uploaded-cache evictor deleted the local copy
    /// of 371 SSTables whose only remaining copy was in S3 (all still listed
    /// in the manifest). The next restart discovered generations by listing
    /// `*-Data.db` on local disk only, so every evicted SSTable silently left
    /// its table: `document_chunks` went from 17 SSTables (1.46 GB) to 0 and
    /// every node reported an order of magnitude fewer rows. Nothing was
    /// deleted from S3; the engine simply stopped looking there.
    ///
    /// A restart must serve every row the manifest says it holds, whether or
    /// not its SSTable is still in the local cache.
    #[tokio::test(flavor = "multi_thread")]
    async fn rows_of_an_evicted_sstable_are_readable_after_restart() {
        let dir = tempfile::tempdir().unwrap();
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let prefix = "test-evicted-restart";
        let tid = table_id();
        let keys: Vec<String> = (0..5).map(|i| format!("k{i}")).collect();

        {
            let engine = evicting_s3_engine(dir.path(), &store, prefix);
            engine.register_table(test_schema()).unwrap();
            for key in &keys {
                engine
                    .write(&tid, &make_key(key), make_row(b"v", 1000), 1000)
                    .unwrap();
            }
            engine.flush(&tid).unwrap();
            assert!(engine.sync_sstables_to_s3().await.unwrap() >= 1);
            let table_dir = engine.table_sstable_dir(&tid);
            assert!(
                StorageEngine::list_generations_in_dir(&table_dir).is_empty(),
                "precondition: the sync evicted the uploaded SSTable's local copy"
            );
            assert!(
                !StorageEngine::evicted_generations(&dir.path().join("sstables")).is_empty(),
                "the eviction is durably recorded, so a restart knows to restore it"
            );
            engine.shutdown().unwrap();
        }

        // Restart: a fresh engine over the same data dir and bucket.
        let engine = evicting_s3_engine(dir.path(), &store, prefix);
        engine.register_table(test_schema()).unwrap();

        for key in &keys {
            assert!(
                engine.read(&tid, &make_key(key)).unwrap().is_some(),
                "row {key} of an evicted SSTable must survive a restart"
            );
        }
        engine.shutdown().unwrap();
    }

    /// Build an evicting engine holding one flushed, uploaded, evicted SSTable
    /// of five rows, with its pooled reader and cached `Data.db` descriptor
    /// dropped so the next read must reopen it by path. Returns the engine, the
    /// table dir, the evicted generation and the keys.
    async fn engine_with_evicted_sstable(
        dir: &std::path::Path,
        prefix: &str,
    ) -> (StorageEngine, std::path::PathBuf, String, Vec<String>) {
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        engine_with_evicted_sstable_in(dir, prefix, &store).await
    }

    /// [`engine_with_evicted_sstable`] over a caller-held object store, so a
    /// test can take the objects away after the eviction.
    async fn engine_with_evicted_sstable_in(
        dir: &std::path::Path,
        prefix: &str,
        store: &Arc<dyn object_store::ObjectStore>,
    ) -> (StorageEngine, std::path::PathBuf, String, Vec<String>) {
        let tid = table_id();
        let engine = evicting_s3_engine(dir, store, prefix);
        // The test constructor does not install the read-through hook the
        // production constructors do. Hooks are process-global but keyed by
        // data dir, so this tempdir's hook ignores every other test's paths.
        StorageEngine::install_s3_file_read_rehydration_hook(
            dir.to_path_buf(),
            prefix.to_string(),
            Arc::clone(store),
        );
        engine.register_table(test_schema()).unwrap();
        let keys: Vec<String> = (0..5).map(|i| format!("k{i}")).collect();
        for key in &keys {
            engine
                .write(&tid, &make_key(key), make_row(b"v", 1000), 1000)
                .unwrap();
        }
        engine.flush(&tid).unwrap();
        assert!(engine.sync_sstables_to_s3().await.unwrap() >= 1);
        let table_dir = engine.table_sstable_dir(&tid);
        let evicted = StorageEngine::evicted_generations(&dir.join("sstables"));
        let gens = evicted
            .values()
            .next()
            .expect("the sync recorded an eviction");
        let gen = gens.iter().next().expect("one evicted generation").clone();
        assert!(StorageEngine::list_generations_in_dir(&table_dir).is_empty());
        engine.evict_pooled_reader_for_test(&tid, gen.parse().unwrap());
        ferrosa_sstable::io::evict_global_fd_for_test(table_dir.join(format!("{gen}-Data.db")));
        (engine, table_dir, gen, keys)
    }

    /// Live failure on the memory cluster, 2026-09-29 (t_bfc0e4da): between an
    /// eviction and the next restart, the read path could not reopen the
    /// evicted SSTable because the required-component `exists()` check failed
    /// BEFORE the S3 read-through hook could run, so reads returned partial
    /// data. A marked generation must be reopenable. Since ST-51 a query open
    /// reads it through ranged GETs instead of rehydrating the whole generation,
    /// so `Data.db` stays remote and the marker stays (the generation is still
    /// evicted; a restart or compaction restores it in full).
    #[tokio::test(flavor = "multi_thread")]
    async fn rows_of_an_evicted_sstable_are_readable_live_without_a_restart() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, gen, keys) =
            engine_with_evicted_sstable(dir.path(), "test-evicted-live").await;
        let tid = table_id();

        for key in &keys {
            assert!(
                engine.read(&tid, &make_key(key)).unwrap().is_some(),
                "row {key} of an evicted SSTable must be readable before any restart"
            );
        }
        assert!(
            StorageEngine::generation_component_path(&table_dir, &gen, "Data.db").is_none(),
            "a query open must not download Data.db (ST-51)"
        );
        assert!(
            StorageEngine::evicted_marker_path(&table_dir, &gen).exists(),
            "the generation is still evicted, so its marker stays"
        );
        engine.shutdown().unwrap();
    }

    /// Remove every object from `store`: the evicted SSTable's S3 copy is gone
    /// (object missing, bucket emptied), so a rehydrate cannot succeed.
    async fn delete_all_objects(store: &Arc<dyn object_store::ObjectStore>) {
        use futures::StreamExt;
        let mut locations = Vec::new();
        let mut listing = store.list(None);
        while let Some(object) = listing.next().await {
            locations.push(object.expect("listing the in-memory store").location);
        }
        drop(listing);
        assert!(!locations.is_empty(), "the sync uploaded objects to remove");
        for location in locations {
            store
                .delete(&location)
                .await
                .expect("deleting an in-memory object");
        }
    }

    /// t_73659682: a range read over a table whose evicted SSTable cannot be
    /// rehydrated must FAIL, not return the rows of the healthy sources as if
    /// it were the whole table. Every range entry point is covered.
    #[tokio::test(flavor = "multi_thread")]
    async fn range_reads_fail_loud_when_an_evicted_sstable_cannot_be_rehydrated() {
        let dir = tempfile::tempdir().unwrap();
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let (engine, _table_dir, gen, _keys) =
            engine_with_evicted_sstable_in(dir.path(), "test-evicted-gone", &store).await;
        let tid = table_id();
        // A live memtable row, so a partial result would be non-empty and
        // look like a complete answer.
        engine
            .write(&tid, &make_key("live"), make_row(b"v", 2000), 2000)
            .unwrap();
        delete_all_objects(&store).await;

        let err = engine
            .read_range(&tid, None, None, 100)
            .expect_err("read_range must not return only the memtable row");
        assert!(
            err.corrupt_sstable_range().is_some() && err.to_string().contains(&gen),
            "typed CorruptSstable naming gen {gen}, got: {err}"
        );
        engine
            .read_token_range(&tid, i64::MIN, i64::MAX, 100)
            .expect_err("read_token_range must fail loud");
        engine
            .read_token_range_bounded(&tid, i64::MIN, i64::MAX, 100, usize::MAX)
            .expect_err("read_token_range_bounded must fail loud");
        engine
            .walk_token_range(&tid, i64::MIN, i64::MAX, |_| Ok(()))
            .expect_err("walk_token_range must fail loud");
        engine
            .walk_token_range_for_digest(&tid, i64::MIN, i64::MAX, |_, _, _, _| Ok(()))
            .expect_err("walk_token_range_for_digest must fail loud");
        engine.shutdown().unwrap();
    }

    /// Counterpart: with the S3 objects present the same range read rehydrates
    /// the evicted SSTable and returns every row, so the fail-loud path above
    /// is not simply a range read that always errors on eviction.
    #[tokio::test(flavor = "multi_thread")]
    async fn range_reads_rehydrate_an_evicted_sstable_when_its_objects_exist() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, _table_dir, _gen, keys) =
            engine_with_evicted_sstable(dir.path(), "test-evicted-range-ok").await;
        let tid = table_id();
        let rows = engine
            .read_range(&tid, None, None, 100)
            .expect("range read over an evicted SSTable rehydrates it");
        assert_eq!(rows.len(), keys.len());
        engine.shutdown().unwrap();
    }

    /// The rehydration is for MARKED generations only. An unmarked generation
    /// with missing components was compacted away, and restoring it from S3
    /// would resurrect purged rows; its open must keep failing loud so the
    /// read path's view-retry fires.
    #[tokio::test(flavor = "multi_thread")]
    async fn an_unmarked_missing_sstable_is_not_rehydrated_on_open() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, gen, _keys) =
            engine_with_evicted_sstable(dir.path(), "test-unmarked-missing").await;
        std::fs::remove_file(StorageEngine::evicted_marker_path(&table_dir, &gen)).unwrap();

        let err = match crate::flush::open_file_sstable(&table_dir, &gen) {
            Ok(_) => panic!("an unmarked missing generation must not open"),
            Err(e) => e,
        };
        assert!(err.to_string().contains("missing required"), "{err}");
        assert!(
            StorageEngine::generation_component_path(&table_dir, &gen, "Data.db").is_none(),
            "nothing may be restored for an unmarked generation"
        );
        engine.shutdown().unwrap();
    }

    /// An evicted SSTable can still be compacted (execution rehydrates its
    /// inputs). When compaction then retires it, its eviction marker must go
    /// with it, or the next restart restores a compacted-away input and
    /// resurrects the rows the compaction purged.
    #[test]
    fn retiring_an_evicted_generation_clears_its_eviction_marker() {
        let dir = tempfile::tempdir().unwrap();
        let table_dir = dir.path().join("sstables").join(table_id().to_string());
        std::fs::create_dir_all(&table_dir).unwrap();
        std::fs::write(table_dir.join("42-Data.db"), b"x").unwrap();
        StorageEngine::record_eviction(&table_dir, "42", &crate::eviction_marker::test_record())
            .unwrap();

        StorageEngine::delete_sstable_files(&table_dir, "42");

        assert!(
            StorageEngine::evicted_generations(&dir.path().join("sstables")).is_empty(),
            "a retired generation must not keep an eviction marker"
        );
    }

    /// ST-61: compaction retired an evicted input without clearing its marker,
    /// so every later start logged an ERROR per marker for rows that are
    /// deliberately not served, training operators to ignore the message.
    #[tokio::test(flavor = "multi_thread")]
    async fn compaction_retiring_an_evicted_input_leaves_no_marker_for_the_next_start() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, gen, _keys) =
            engine_with_evicted_sstable(dir.path(), "test-retire-evicted-marker").await;
        assert!(StorageEngine::evicted_marker_path(&table_dir, &gen).exists());

        assert!(crate::compaction::retire::retire(&table_dir, &gen));

        assert!(
            StorageEngine::evicted_generations(&dir.path().join("sstables")).is_empty(),
            "a start after the retirement has no marker to complain about"
        );
        assert_eq!(
            StorageEngine::restore_evicted_sstables_blocking_in(dir.path(), None).unwrap(),
            0
        );
        engine.shutdown().unwrap();
    }

    /// A generation compaction retired must not be pulled back from S3 by a
    /// reader that still holds a stale view of the table.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_retired_generation_is_not_rehydrated_again() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, gen, _keys) =
            engine_with_evicted_sstable(dir.path(), "test-retired-not-rehydrated").await;
        assert!(crate::compaction::retire::retire(&table_dir, &gen));

        let rehydrated =
            ferrosa_sstable::io::rehydrate_file(table_dir.join(format!("{gen}-Data.db"))).unwrap();

        assert!(!rehydrated, "a retired generation is refused, not restored");
        assert!(StorageEngine::generation_component_path(&table_dir, &gen, "Data.db").is_none());
        engine.shutdown().unwrap();
    }

    /// ST-61 (t_dfd7d1bd): one run logged `failed to promote SSTable
    /// rehydration temp file ...rehydrate.tmp` beside `compaction: task failed
    /// ... Data.db is missing`. Retirement sweeps every `<gen>-*` entry, temp
    /// files included, so retiring a generation while a rehydrate of it was
    /// between "temp file complete" and "rename" moved the temp file away.
    ///
    /// The seam fires in exactly that window and starts the retirement there.
    /// The retirement must wait for the rehydrate, which then completes, and
    /// only afterwards remove the generation: never a half-present generation.
    #[tokio::test(flavor = "multi_thread")]
    async fn retiring_a_generation_while_it_is_promoting_waits_for_the_rehydrate() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, gen, _keys) =
            engine_with_evicted_sstable(dir.path(), "test-promote-vs-retire").await;

        let retirement: Arc<parking_lot::Mutex<Option<std::thread::JoinHandle<bool>>>> =
            Arc::new(parking_lot::Mutex::new(None));
        let finished_inside_window = Arc::new(AtomicBool::new(false));
        {
            let retirement = Arc::clone(&retirement);
            let finished_inside_window = Arc::clone(&finished_inside_window);
            let (dir_for_retire, gen_for_retire) = (table_dir.clone(), gen.clone());
            rehydrate_promote_seam::install(
                &table_dir,
                Arc::new(move |_tmp| {
                    let mut slot = retirement.lock();
                    if slot.is_some() {
                        return;
                    }
                    let (dir, gen) = (dir_for_retire.clone(), gen_for_retire.clone());
                    let handle =
                        std::thread::spawn(move || crate::compaction::retire::retire(&dir, &gen));
                    std::thread::sleep(std::time::Duration::from_millis(300));
                    finished_inside_window.store(handle.is_finished(), Ordering::SeqCst);
                    *slot = Some(handle);
                }),
            );
        }

        let rehydrated =
            ferrosa_sstable::io::rehydrate_file(table_dir.join(format!("{gen}-Data.db")))
                .expect("the rehydrate must complete, not fail on a vanished temp file");

        assert!(rehydrated);
        assert!(
            !finished_inside_window.load(Ordering::SeqCst),
            "the retirement ran while the rehydrate was promoting"
        );
        let handle = retirement
            .lock()
            .take()
            .expect("the seam started the retirement");
        assert!(
            handle.join().unwrap(),
            "the retirement completes afterwards"
        );
        let leftovers: Vec<String> = std::fs::read_dir(&table_dir)
            .unwrap()
            .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
            .filter(|name| name.contains(gen.as_str()))
            .collect();
        assert!(
            leftovers.is_empty(),
            "a retired generation leaves nothing behind, found {leftovers:?}"
        );
        engine.shutdown().unwrap();
    }

    /// Build an engine over `dir` holding generations `1` and `2` (80 bytes
    /// each) that the manifest lists as uploaded, with the given cache cap and
    /// disk-free reserve. Returns the engine, its table dir and the manifest.
    fn engine_with_two_uploaded_sstables(
        dir: &std::path::Path,
        cache_max_bytes: u64,
        free_reserve_bytes: u64,
    ) -> (StorageEngine, std::path::PathBuf, crate::manifest::Manifest) {
        let mut config = StorageEngineConfig::test_config(dir);
        config.local_cache_max_bytes = cache_max_bytes;
        config.local_disk_free_reserve_bytes = free_reserve_bytes;
        let engine = StorageEngine::new(config, None).unwrap();
        let table_id = table_id().to_string();
        let table_dir = dir.join("sstables").join(&table_id);
        std::fs::create_dir_all(&table_dir).unwrap();
        let mut manifest = crate::manifest::Manifest::new();
        for id in ["1", "2"] {
            std::fs::write(table_dir.join(format!("{id}-Data.db")), vec![1u8; 80]).unwrap();
            manifest.add_sstable(
                &table_id,
                crate::manifest::ManifestEntry {
                    id: id.to_string(),
                    size: 80,
                    min_token: i64::MIN,
                    max_token: i64::MAX,
                    min_timestamp: 0,
                    max_timestamp: 0,
                },
            );
        }
        (engine, table_dir, manifest)
    }

    /// The record of the eviction that saw the whole cache: the one with the
    /// largest `total_bytes` among the markers in `table_dir`.
    fn first_eviction_record(
        table_dir: &std::path::Path,
    ) -> crate::eviction_marker::EvictionRecord {
        use crate::eviction_marker::{read_marker, MarkerState};
        let records: Vec<_> = ["1", "2"]
            .iter()
            .filter_map(|gen| {
                let marker = StorageEngine::evicted_marker_path(table_dir, gen);
                marker.exists().then(|| read_marker(&marker))
            })
            .map(|state| match state {
                MarkerState::Recorded(r) => r,
                other => panic!("a fresh eviction must write a readable record, got {other:?}"),
            })
            .collect();
        assert!(!records.is_empty(), "an eviction wrote a marker");
        records
            .into_iter()
            .max_by_key(|r| r.total_bytes)
            .expect("non-empty")
    }

    /// 2026-09-29: ~1000 SSTables were evicted and nobody could say why,
    /// because the marker was empty and the reason lived in a rotated log. A
    /// cache-cap eviction must name that trigger and the byte figures.
    #[test]
    fn a_cache_cap_eviction_marker_names_its_trigger_and_figures() {
        use crate::eviction_marker::Trigger;
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, manifest) = engine_with_two_uploaded_sstables(dir.path(), 100, 0);

        let evicted = engine
            .enforce_uploaded_sstable_cache_limit(&manifest)
            .unwrap();
        assert!(evicted >= 1, "160 cached bytes over a 100 byte cap evicts");

        let record = first_eviction_record(&table_dir);
        assert_eq!(record.trigger, Trigger::CacheCap);
        assert_eq!(record.source, "ferrosa-storage evictor");
        assert_eq!(record.generation_bytes, Some(80));
        assert_eq!(record.total_bytes, Some(160));
        assert_eq!(record.max_bytes, Some(100));
        assert_eq!(record.min_bytes, Some(0));
        assert_eq!(record.target_free, Some(0));
        assert!(record.written_at_unix_ms > 0);
    }

    /// A free-space eviction (cache well under its cap, disk under its free
    /// target) names that trigger and carries the free-space figures.
    #[test]
    fn a_free_space_eviction_marker_names_its_trigger_and_figures() {
        use crate::eviction_marker::Trigger;
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, manifest) =
            engine_with_two_uploaded_sstables(dir.path(), 1024 * 1024, u64::MAX / 4);

        let evicted = engine
            .enforce_uploaded_sstable_cache_limit(&manifest)
            .unwrap();
        assert!(evicted >= 1);

        let record = first_eviction_record(&table_dir);
        assert_eq!(record.trigger, Trigger::FreeSpace);
        assert_eq!(record.max_bytes, Some(1024 * 1024));
        assert_eq!(record.total_bytes, Some(160));
        assert!(record.target_free.unwrap() > record.projected_available.unwrap());
    }

    /// Every pass that finds pressure leaves a durable record naming what it
    /// saw (manifest claim AND real disk total), what it did, and who wrote it.
    #[test]
    fn an_eviction_pass_leaves_a_durable_audit_record() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, _table_dir, mut manifest) =
            engine_with_two_uploaded_sstables(dir.path(), 100, 0);
        // The manifest over-claims: 1000 bytes per entry against 80 on disk.
        let listed = manifest.sstables.get_mut(&table_id().to_string()).unwrap();
        listed.iter_mut().for_each(|entry| entry.size = 1000);

        let evicted = engine
            .enforce_uploaded_sstable_cache_limit(&manifest)
            .unwrap();
        assert_eq!(evicted, 1);

        let text =
            std::fs::read_to_string(dir.path().join("eviction-audit/audit.current.jsonl")).unwrap();
        let record: crate::eviction_audit::PassRecord =
            serde_json::from_str(text.lines().next().unwrap()).unwrap();
        assert_eq!(record.trigger, crate::eviction_marker::Trigger::CacheCap);
        assert_eq!(record.max_bytes, 100);
        assert_eq!(record.min_bytes, 0);
        assert_eq!(record.target_free, 0);
        assert_eq!(record.manifest_bytes, 2000, "what the manifest claims");
        assert_eq!(record.disk_bytes, 160, "what is on disk");
        assert_eq!(record.evicted_generations, 1);
        assert_eq!(record.evicted_bytes, 80);
        assert_eq!(record.pid, std::process::id());
        assert_eq!(record.build, env!("CARGO_PKG_VERSION"));
        assert_eq!(text.lines().count(), 1);
    }

    /// An audit that cannot be written must not stop the eviction or its
    /// marker: durability of the marker outranks the audit record.
    #[test]
    fn an_unwritable_audit_does_not_prevent_an_eviction() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, manifest) = engine_with_two_uploaded_sstables(dir.path(), 100, 0);
        // A regular file where the audit directory must go.
        std::fs::write(dir.path().join("eviction-audit"), b"in the way").unwrap();

        let evicted = engine
            .enforce_uploaded_sstable_cache_limit(&manifest)
            .unwrap();

        assert_eq!(evicted, 1, "the eviction proceeded");
        let marked = ["1", "2"]
            .iter()
            .filter(|g| StorageEngine::evicted_marker_path(&table_dir, g).exists())
            .count();
        assert_eq!(marked, 1, "and its marker was written");
        assert!(engine.eviction_audit.is_failing());
        assert_eq!(engine.eviction_audit.write_failure_edges(), 1);
    }

    /// The latest pass is readable without touching the audit files.
    #[test]
    fn the_eviction_audit_is_exposed_as_metrics() {
        let text = crate::metrics::render_prometheus();
        let wanted = [
            "ferrosa_storage_eviction_audit_last_unix_ms",
            "ferrosa_storage_eviction_audit_last_manifest_bytes",
            "ferrosa_storage_eviction_audit_last_disk_bytes",
            "ferrosa_storage_eviction_audit_last_evicted_generations",
            "ferrosa_storage_eviction_audit_write_failures_total",
        ];
        wanted
            .iter()
            .for_each(|name| assert!(text.contains(name), "{name} missing from the metrics"));
    }

    fn manifest_entry(id: &str, size: u64) -> crate::manifest::ManifestEntry {
        crate::manifest::ManifestEntry {
            id: id.to_string(),
            size,
            min_token: i64::MIN,
            max_token: i64::MAX,
            min_timestamp: 0,
            max_timestamp: 0,
        }
    }

    /// A manifest that lists the same generation twice (a re-upload pushes a
    /// second entry) must not double the evictor's byte count or evict the
    /// same files twice. The real bytes (160) are under the 170 byte cap; the
    /// duplicate makes the manifest-derived sum 240, which is over it.
    #[test]
    fn a_duplicate_manifest_entry_does_not_drive_an_eviction() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, mut manifest) =
            engine_with_two_uploaded_sstables(dir.path(), 170, 0);
        manifest
            .sstables
            .get_mut(&table_id().to_string())
            .unwrap()
            .push(manifest_entry("1", 80));

        let evicted = engine
            .enforce_uploaded_sstable_cache_limit(&manifest)
            .unwrap();

        assert_eq!(evicted, 0, "160 real bytes under a 170 byte cap");
        assert!(
            engine.manifest_drift_flagged.load(Ordering::Relaxed),
            "a generation listed twice is reported"
        );
        assert!(table_dir.join("1-Data.db").exists());
        assert!(table_dir.join("2-Data.db").exists());
    }

    /// Manifest entries for generations that are not on disk (retired
    /// compaction inputs not yet dropped, or evicted ones) claim bytes that
    /// are not there. They must not push the evictor over its cap when the
    /// real on-disk total is far under it.
    #[test]
    fn manifest_entries_that_are_not_on_disk_do_not_drive_an_eviction() {
        let dir = tempfile::tempdir().unwrap();
        let (engine, table_dir, mut manifest) =
            engine_with_two_uploaded_sstables(dir.path(), 1024 * 1024, 0);
        let listed = manifest.sstables.get_mut(&table_id().to_string()).unwrap();
        for gen in 100..110 {
            listed.push(manifest_entry(&gen.to_string(), 10 * 1024 * 1024 * 1024));
        }

        let evicted = engine
            .enforce_uploaded_sstable_cache_limit(&manifest)
            .unwrap();

        assert_eq!(evicted, 0, "160 real bytes under a 1 MiB cap");
        assert!(
            engine.manifest_drift_flagged.load(Ordering::Relaxed),
            "100 GiB claimed against 160 bytes on disk is reported as drift"
        );
        assert!(table_dir.join("1-Data.db").exists());
        assert!(table_dir.join("2-Data.db").exists());
    }

    /// The drift signal: the manifest claims far more than is on disk.
    #[test]
    fn manifest_drift_needs_both_a_ratio_and_a_floor() {
        const MIB: u64 = 1024 * 1024;
        assert!(manifest_drift(4_840 * MIB, 2_940 * MIB), "1.65x of 2.9 GB");
        assert!(manifest_drift(6_690 * MIB, 3_010 * MIB));
        assert!(!manifest_drift(2_940 * MIB, 2_940 * MIB), "equal");
        assert!(!manifest_drift(3_000 * MIB, 2_940 * MIB), "a little over");
        assert!(
            !manifest_drift(100, 10),
            "10x of nothing is below the floor"
        );
        assert!(!manifest_drift(0, 0));
    }

    /// Markers written before the record existed are empty. They must keep
    /// restoring, and be reported as "evicted, reason unknown".
    #[test]
    fn an_empty_legacy_marker_is_still_honoured_and_reason_unknown() {
        use crate::eviction_marker::{read_marker, MarkerState};
        let dir = tempfile::tempdir().unwrap();
        let table_dir = dir.path().join("sstables").join(table_id().to_string());
        std::fs::create_dir_all(&table_dir).unwrap();
        std::fs::File::create(StorageEngine::evicted_marker_path(&table_dir, "7")).unwrap();

        let found = StorageEngine::evicted_generations(&dir.path().join("sstables"));
        assert!(found.values().next().unwrap().contains("7"));
        assert_eq!(
            read_marker(&StorageEngine::evicted_marker_path(&table_dir, "7")),
            MarkerState::Legacy
        );
    }

    /// A truncated or garbage marker is still an eviction marker: restore
    /// honours it, startup does not fail, and it reads as reason-unknown with
    /// the parse error preserved.
    #[test]
    fn a_corrupt_marker_is_honoured_as_reason_unknown_not_an_error() {
        use crate::eviction_marker::{read_marker, MarkerState};
        let dir = tempfile::tempdir().unwrap();
        let table_dir = dir.path().join("sstables").join(table_id().to_string());
        std::fs::create_dir_all(&table_dir).unwrap();
        let full = serde_json::to_vec(&crate::eviction_marker::test_record()).unwrap();
        std::fs::write(
            StorageEngine::evicted_marker_path(&table_dir, "8"),
            &full[..full.len() / 2],
        )
        .unwrap();
        std::fs::write(
            StorageEngine::evicted_marker_path(&table_dir, "9"),
            [0xff, 0xfe, 0x00, 0x41],
        )
        .unwrap();

        let found = StorageEngine::evicted_generations(&dir.path().join("sstables"));
        let gens = found.values().next().unwrap();
        assert!(gens.contains("8") && gens.contains("9"));
        for gen in ["8", "9"] {
            assert!(
                matches!(
                    read_marker(&StorageEngine::evicted_marker_path(&table_dir, gen)),
                    MarkerState::Unreadable(_)
                ),
                "generation {gen}"
            );
        }
    }

    /// The same loss through the crash-recovery constructor.
    ///
    /// A node with commit-log segments starts through `StorageEngine::open`,
    /// not `new`, and `open` registers tables before the engine exists. The
    /// first live recovery (2026-09-29) restored node3 (no segments, `new`)
    /// while node1 and node2 (`open`) came up serving their tables without
    /// a single evicted SSTable.
    #[tokio::test(flavor = "multi_thread")]
    async fn rows_of_an_evicted_sstable_survive_a_restart_through_commit_log_replay() {
        let dir = tempfile::tempdir().unwrap();
        let bucket = tempfile::tempdir().unwrap();
        let prefix = "test-evicted-open";
        let tid = table_id();
        let keys: Vec<String> = (0..5).map(|i| format!("k{i}")).collect();

        {
            let store: Arc<dyn object_store::ObjectStore> = Arc::new(
                object_store::local::LocalFileSystem::new_with_prefix(bucket.path()).unwrap(),
            );
            let engine = evicting_s3_engine(dir.path(), &store, prefix);
            engine.register_table(test_schema()).unwrap();
            for key in &keys {
                engine
                    .write(&tid, &make_key(key), make_row(b"v", 1000), 1000)
                    .unwrap();
            }
            engine.flush(&tid).unwrap();
            assert!(engine.sync_sstables_to_s3().await.unwrap() >= 1);
            assert!(
                StorageEngine::list_generations_in_dir(&engine.table_sstable_dir(&tid)).is_empty(),
                "precondition: the sync evicted the uploaded SSTable's local copy"
            );
            engine.shutdown().unwrap();
        }

        // Restart through the crash-recovery constructor, against the same
        // bucket (a file:// backend over the directory engine one wrote to).
        let mut config = StorageEngineConfig::test_config(dir.path());
        config.object_store = Some(crate::upload::ObjectStoreConfig {
            local_path: Some(bucket.path().to_path_buf()),
            prefix: prefix.to_string(),
            ..crate::upload::ObjectStoreConfig::test_config()
        });
        let (engine, _mutations) =
            StorageEngine::open(config, Some(&tokio::runtime::Handle::current())).unwrap();
        engine.register_table(test_schema()).unwrap();

        for key in &keys {
            assert!(
                engine.read(&tid, &make_key(key)).unwrap().is_some(),
                "row {key} of an evicted SSTable must survive a restart through open()"
            );
        }
        engine.shutdown().unwrap();
    }

    /// Serves from memory, but the first `drops` GETs send half the body and
    /// then fail — how an R2 download of a 100 MB Data.db died mid-stream
    /// ("error decoding response body") during the 2026-09-29 recovery.
    #[derive(Debug)]
    struct MidStreamDropStore {
        inner: object_store::memory::InMemory,
        drops: std::sync::atomic::AtomicU32,
    }

    impl std::fmt::Display for MidStreamDropStore {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "MidStreamDropStore")
        }
    }

    #[async_trait::async_trait]
    impl object_store::ObjectStore for MidStreamDropStore {
        async fn put_opts(
            &self,
            location: &object_store::path::Path,
            payload: object_store::PutPayload,
            opts: object_store::PutOptions,
        ) -> object_store::Result<object_store::PutResult> {
            self.inner.put_opts(location, payload, opts).await
        }
        async fn put_multipart_opts(
            &self,
            location: &object_store::path::Path,
            opts: object_store::PutMultipartOpts,
        ) -> object_store::Result<Box<dyn object_store::MultipartUpload>> {
            self.inner.put_multipart_opts(location, opts).await
        }
        async fn get_opts(
            &self,
            location: &object_store::path::Path,
            options: object_store::GetOptions,
        ) -> object_store::Result<object_store::GetResult> {
            let result = self.inner.get_opts(location, options).await?;
            let drop_this = self
                .drops
                .fetch_update(
                    std::sync::atomic::Ordering::SeqCst,
                    std::sync::atomic::Ordering::SeqCst,
                    |n| n.checked_sub(1),
                )
                .is_ok();
            if !drop_this {
                return Ok(result);
            }
            let meta = result.meta.clone();
            let range = result.range.clone();
            let attributes = result.attributes.clone();
            let body = result.bytes().await?;
            let half = body.slice(0..body.len() / 2);
            let stream = futures::stream::iter(vec![
                Ok(half),
                Err(object_store::Error::Generic {
                    store: "S3",
                    source: "error decoding response body".into(),
                }),
            ]);
            Ok(object_store::GetResult {
                payload: object_store::GetResultPayload::Stream(Box::pin(stream)),
                meta,
                range,
                attributes,
            })
        }
        async fn delete(&self, location: &object_store::path::Path) -> object_store::Result<()> {
            self.inner.delete(location).await
        }
        fn list(
            &self,
            prefix: Option<&object_store::path::Path>,
        ) -> futures::stream::BoxStream<'_, object_store::Result<object_store::ObjectMeta>>
        {
            self.inner.list(prefix)
        }
        async fn list_with_delimiter(
            &self,
            prefix: Option<&object_store::path::Path>,
        ) -> object_store::Result<object_store::ListResult> {
            self.inner.list_with_delimiter(prefix).await
        }
        async fn copy(
            &self,
            from: &object_store::path::Path,
            to: &object_store::path::Path,
        ) -> object_store::Result<()> {
            self.inner.copy(from, to).await
        }
        async fn copy_if_not_exists(
            &self,
            from: &object_store::path::Path,
            to: &object_store::path::Path,
        ) -> object_store::Result<()> {
            self.inner.copy_if_not_exists(from, to).await
        }
    }

    /// A download whose body dies mid-stream is retried from the start, and
    /// the file ends up whole — not truncated, not a failed restore.
    #[tokio::test]
    async fn a_component_download_that_drops_mid_stream_is_retried_whole() {
        let store = MidStreamDropStore {
            inner: object_store::memory::InMemory::new(),
            drops: std::sync::atomic::AtomicU32::new(0),
        };
        let path = object_store::path::Path::from("p/ab/ks.t/7/7-Data.db");
        let body: Vec<u8> = (0..4096u32).map(|i| (i % 251) as u8).collect();
        object_store::ObjectStore::put(&store, &path, object_store::PutPayload::from(body.clone()))
            .await
            .unwrap();
        store.drops.store(2, std::sync::atomic::Ordering::SeqCst);
        let dir = tempfile::tempdir().unwrap();
        let local = dir.path().join("7-Data.db");

        let written = StorageEngine::download_sstable_component_to_path(&store, &path, &local)
            .await
            .expect("a transient mid-stream failure must be retried, not fail the restore");

        assert_eq!(written, Some(body.len() as u64));
        assert_eq!(
            std::fs::read(&local).unwrap(),
            body,
            "the file must be whole"
        );
    }

    /// A generation whose download fails for good leaves no staging
    /// directory behind: node1's failed restore left a `.download-*`
    /// directory holding a half-written Data.db.
    #[tokio::test]
    async fn a_failed_generation_download_removes_its_staging_directory() {
        let store: Arc<dyn object_store::ObjectStore> = Arc::new(MidStreamDropStore {
            inner: object_store::memory::InMemory::new(),
            drops: std::sync::atomic::AtomicU32::new(u32::MAX),
        });
        let prefix = "p";
        let tid = table_id();
        let table = tid.to_string();
        let gen = "1790000000000009";
        let hex = crate::upload::manager::hex_prefix_for(gen);
        for component in ["Data.db", "Partitions.db", "Rows.db"] {
            let key =
                crate::upload::manager::sstable_object_key(prefix, &hex, &table, gen, component);
            store
                .put(&key, object_store::PutPayload::from(vec![7u8; 64]))
                .await
                .unwrap();
        }
        let mut manifest = crate::manifest::Manifest::new();
        manifest.add_sstable(
            &table,
            crate::manifest::ManifestEntry {
                id: gen.to_string(),
                size: 64,
                min_token: i64::MIN,
                max_token: i64::MAX,
                min_timestamp: 0,
                max_timestamp: 0,
            },
        );
        let dir = tempfile::tempdir().unwrap();

        let result =
            StorageEngine::download_sstables_into(dir.path(), &store, prefix, &tid, &manifest)
                .await;

        assert!(
            result.is_err(),
            "a download that never succeeds is an error"
        );
        let table_dir = dir.path().join("sstables").join(&table);
        let leftovers: Vec<_> = std::fs::read_dir(&table_dir)
            .unwrap()
            .flatten()
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| n.starts_with(".download-"))
            .collect();
        assert!(leftovers.is_empty(), "staging left behind: {leftovers:?}");
    }

    /// Restore must bring back only what the evictor removed.
    ///
    /// The manifest drops a compaction's inputs only after the local swap,
    /// and a timed-out upload confirmation or a pending-upload replay ("adding
    /// SSTable to manifest without input cleanup") can leave a compacted-away
    /// input listed there indefinitely. Such an input is "in the manifest,
    /// absent locally" exactly like an evicted SSTable. Restoring it would
    /// resurrect every row its compaction purged, so a generation nobody
    /// evicted must stay gone.
    #[tokio::test(flavor = "multi_thread")]
    async fn restart_does_not_restore_a_manifest_entry_that_was_never_evicted() {
        let dir = tempfile::tempdir().unwrap();
        let store: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let prefix = "test-stale-compacted-input";
        let tid = table_id();
        let table_id_str = tid.to_string();

        // A stale manifest entry for a compacted-away input: its objects are
        // still in S3, it is still listed, and it is not on local disk.
        let stale = "1790000000000001";
        let hex = crate::upload::manager::hex_prefix_for(stale);
        for (component, bytes) in [
            ("Data.db", b"data".as_slice()),
            ("Partitions.db", b"partitions".as_slice()),
            ("Rows.db", b"rows".as_slice()),
        ] {
            let path = crate::upload::manager::sstable_object_key(
                prefix,
                &hex,
                &table_id_str,
                stale,
                component,
            );
            store
                .put(
                    &path,
                    object_store::PutPayload::from(bytes::Bytes::copy_from_slice(bytes)),
                )
                .await
                .unwrap();
        }
        let mut manifest = crate::manifest::Manifest::new();
        manifest.add_sstable(
            &table_id_str,
            crate::manifest::ManifestEntry {
                id: stale.to_string(),
                size: 4,
                min_token: i64::MIN,
                max_token: i64::MAX,
                min_timestamp: 0,
                max_timestamp: 0,
            },
        );
        manifest
            .save_without_cas(store.as_ref(), prefix)
            .await
            .unwrap();

        // Restart: a fresh engine over the same data dir and bucket.
        let engine = evicting_s3_engine(dir.path(), &store, prefix);

        let table_dir = dir.path().join("sstables").join(&table_id_str);
        assert!(
            StorageEngine::generation_component_path(&table_dir, stale, "Data.db").is_none(),
            "a generation that was never evicted must not be restored: it may be a \
             compacted-away input whose purged rows would come back"
        );
        engine.shutdown().unwrap();
    }

    /// t_7ac6b0e3: a sidecar built after its generation is already in S3 (a
    /// CREATE INDEX backfill over uploaded data) is uploaded too. The sync
    /// skips any generation already in the manifest, so such a sidecar was
    /// never uploaded, and a node restored from S3 had no index over that
    /// generation.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_sidecar_built_after_its_generation_was_uploaded_reaches_s3() {
        use futures::StreamExt;

        let (_dir, engine, store, _prefix, tid) = s3_sync_fixture("test-late-sidecar", &[]);
        (0..5).for_each(|i| {
            engine
                .write(
                    &tid,
                    &make_key(&format!("k{i}")),
                    make_row(b"shared", 1000),
                    1000,
                )
                .unwrap();
        });
        engine.flush(&tid).unwrap();
        assert!(
            engine.sync_sstables_to_s3().await.unwrap() >= 1,
            "the generation is uploaded"
        );

        engine
            .add_index(&tid, "val_idx", 0, ferrosa_index::IndexType::BTree)
            .unwrap();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        while !engine.index_is_current(&tid, "val_idx") && std::time::Instant::now() < deadline {
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        }
        assert!(
            engine.index_is_current(&tid, "val_idx"),
            "the backfill completes"
        );

        engine.sync_sstables_to_s3().await.unwrap();

        let mut listing = store.list(None);
        let mut sidecar_objects = Vec::new();
        while let Some(object) = listing.next().await {
            let object = object.unwrap();
            if object.location.as_ref().ends_with("-val_idx.sidecar") {
                sidecar_objects.push(object.location.to_string());
            }
        }
        assert_eq!(
            sidecar_objects.len(),
            1,
            "the backfilled sidecar must be uploaded beside its generation: {sidecar_objects:?}"
        );
    }

